INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u3-C1','kor',1,2,'u3',2,'바른 자세로 발표하기 — 허리를 펴고 듣는 사람을 바라보며 알맞은 크기로 또박또박, 발표 전에 말할 것 정하기',ARRAY['2국01-01']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u3-C2','kor',1,2,'u3',2,'바른 자세로 듣기 — 말하는 사람을 바라보고 끝까지 듣기, 딴 일 하지 않기, 알아들었으면 고개 끄덕이기',ARRAY['2국01-01']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u3-C3','kor',1,2,'u3',4,'경험한 일 자세히 떠올려 말하기 — 언제·어디에서·무엇을·어떤 느낌 네 칸으로 정리해 한 문장으로, 특별한 일이 아니어도 됨, 첫마디·되돌아보기',ARRAY['2국01-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u3-C4','kor',1,2,'u3',6,'기억에 남는 일과 느낌 떠올리기 — 느낌(기쁜·놀란·속상한)으로 갈라 떠올리기, 일과 느낌 잇기, 그림으로 나타낼 한 장면 고르기',ARRAY['2국03-04']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u3-C5','kor',1,2,'u3',8,'그림일기의 짜임 알기 — 맨 위 날짜·요일·날씨, 그림, 글 세 부분; 들어가는 것 네 가지, 빠진 것 찾기, 안내문 것과 구별, 글감 고르기',ARRAY['2국03-04']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u3-C6','kor',1,2,'u3',10,'그림일기 쓰기 — 하루를 아침·낮·저녁으로 떠올려 글감 고르기, 맨 윗줄 쓰기, 그림에 넣을 것, 느낌이 까닭과 함께 드러난 문장, 시간 나누기, 다 쓰고 다시 읽어 고치기, 문장에 「무엇을」 넣기',ARRAY['2국03-04']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u3-C7','kor',1,2,'u3',12,'경험을 작품으로 나타내고 감상하기 — 네 칸 표로 정리, 한 장면 고르기, 작품 부분마다 할 일, 친구 작품에 무엇이 좋았는지 말하기, 전시·감상 예절',ARRAY['2국05-04']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u3-X01','kor',1,'u3',ARRAY['K1-2-u3-C1']::text[],'목소리를 크게 지르는 것이 잘 말하는 것이라고 여긴다','「소리를 지르면 또렷해지나요?」 알맞은 크기로 또박또박 말하는 것과 소리 지르는 것을 견주어 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u3-X02','kor',1,'u3',ARRAY['K1-2-u3-C1']::text[],'듣는 사람을 보지 않고 바닥·칠판을 보거나 허리를 굽힌 채 말한다','말하는 사람 앞에 거울이나 친구를 세우고 「누구를 보고 말하나요?」 되묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u3-X03','kor',1,'u3',ARRAY['K1-2-u3-C1']::text[],'발표하기 전에 무엇을 말할지 정하지 않고 일어난다','「무엇을 말할지 한 문장으로 먼저 정해 보자」 — 일어나기 전에 속으로 한 번 말해 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u3-X04','kor',1,'u3',ARRAY['K1-2-u3-C2']::text[],'들으면서 딴 곳을 보거나 딴 일을 한다','「말하는 사람 눈이 어디를 보고 있나요?」 듣는 사람이 바라보지 않으면 말하는 사람이 말을 잊는다는 것을 겪어 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u3-X05','kor',1,'u3',ARRAY['K1-2-u3-C2']::text[],'끝까지 듣지 않고 끼어들거나, 잘못 듣는 친구를 나무란다','「끝까지 들은 뒤에 말해요」 — 나무라는 말 대신 어떻게 하면 좋을지 알려 주는 말로 바꾸어 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u3-X06','kor',1,'u3',ARRAY['K1-2-u3-C3','K1-2-u3-C5']::text[],'특별한 큰 일이 있어야만 발표나 일기의 글감이 된다고 여긴다','「늘 하는 일이라도 그때 느낌이 남았나요?」 아침에 있었던 작은 일 하나를 함께 떠올리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u3-X07','kor',1,'u3',ARRAY['K1-2-u3-C3','K1-2-u3-C6']::text[],'「재미있었다」 한마디만 말하거나 쓴다 — 언제·어디에서·무엇을이 빠진다','네 칸(언제·어디에서·무엇을·느낌)을 손가락으로 세며 빠진 칸을 채우게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u3-X08','kor',1,'u3',ARRAY['K1-2-u3-C3','K1-2-u3-C7']::text[],'발표 뒤 되돌아보기나 작품 감상을 「누가 제일 잘했나」 가리기로 여긴다','「내 발표에서 잘된 것 하나·고칠 것 하나」만 말하게 하고, 남과 견주는 말은 받지 않기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u3-X09','kor',1,'u3',ARRAY['K1-2-u3-C4']::text[],'일과 느낌을 안 맞게 잇거나 느낌 갈래를 잘못 넣는다 (놀란 일을 기쁜 일에)','「그때 어떤 마음이었나요?」 얼굴 표정 카드로 느낌을 먼저 고르고 일을 붙이게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u3-X10','kor',1,'u3',ARRAY['K1-2-u3-C4','K1-2-u3-C6','K1-2-u3-C7']::text[],'그림일기의 그림을 잘 그리기·예쁘게 꾸미기 겨루기로 여겨 색칠에 힘쓴다','「그림만 보고 무슨 일인지 알 수 있나요?」 — 있었던 일이 보이면 된다고 짚어 주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u3-X11','kor',1,'u3',ARRAY['K1-2-u3-C5','K1-2-u3-C6']::text[],'날짜·요일·날씨를 빠뜨리거나 자리를 틀린다 (날씨를 글 끝에)','맨 윗줄을 손가락으로 짚으며 「날짜 · 요일 · 날씨」 세 가지를 차례로 세어 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u3-X12','kor',1,'u3',ARRAY['K1-2-u3-C5']::text[],'안내문·시간표에 들어갈 것(준비물·선생님 성함·학급 이름)을 그림일기에 넣는다','「이건 내가 겪은 일인가요, 알려 주는 글인가요?」 그림일기와 안내문을 나란히 놓고 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u3-X13','kor',1,'u3',ARRAY['K1-2-u3-C4','K1-2-u3-C6','K1-2-u3-C7']::text[],'여러 장면을 다 그리려 하거나 그림과 글이 서로 다른 일을 담는다','「가장 기억에 남는 한 장면은?」 글을 먼저 읽고 그 글에 맞는 그림인지 짚어 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u3-X14','kor',1,'u3',ARRAY['K1-2-u3-C5','K1-2-u3-C6']::text[],'하루 일을 아침부터 잠들 때까지 전부 늘어놓거나 날마다 똑같은 일을 쓴다','「그날 새롭게 느낀 일 하나만」 — 늘 하는 일(밥·세수)을 지우고 남는 것 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u3-X15','kor',1,'u3',ARRAY['K1-2-u3-C6']::text[],'느낌 문장이 없거나 「좋았다」만 쓴다 — 왜 그렇게 느꼈는지 까닭이 없다','「좋았다」 뒤에 「왜냐하면」을 붙여 한 번 더 말하게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u3-X16','kor',1,'u3',ARRAY['K1-2-u3-C6']::text[],'그림에 시간을 다 써서 정작 글을 못 쓴다','「그림일기의 반은 글」 — 그림은 간단히, 글 쓸 시간을 먼저 남기게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u3-X17','kor',1,'u3',ARRAY['K1-2-u3-C6']::text[],'다 쓴 뒤 다시 읽지 않거나, 고쳐 쓰기를 남과 견주는 일로 여긴다','다 쓴 일기를 소리 내어 한 번 읽고 빠진 칸·틀린 글자 하나를 스스로 찾게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u3-X18','kor',1,'u3',ARRAY['K1-2-u3-C7']::text[],'친구 작품에 꾸미기만 평가하거나(「못 그렸다」) 감상 예절을 지키지 않는다','「무엇이 좋았는지」 한 가지를 짚어 말하게 하고 작품에 손대지 않기 약속하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u3-X19','kor',1,'u3',ARRAY['K1-2-u3-C6']::text[],'문장에서 「무엇을」 자리를 빠뜨린다 (동생이 붑니다 → 동생이 풍선을 붑니다)','「무엇을?」 하고 되물어 빠진 말을 그림에서 찾아 넣게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_basic#1','kor',1,2,'u3','L01','g1_2_kor_u3_L01_basic','lesson_basic','K1-2-u3-C3',1,'mc','auto','있었던 일을 남에게 전하는 방법으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K1-2-u3-X07']::text[],true,'{"seq":1,"concept":"K1-2-u3-C3","difficulty":1,"kind":"mc","stem":"있었던 일을 남에게 전하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"아무에게도 말하지 않고 잊어버리기","correct":true},{"t":"말로 들려주기","mis":"K1-2-u3-X07"},{"t":"글과 그림으로 남기기","mis":"K1-2-u3-X07"}],"explanation":["말로 들려주거나 글과 그림으로 남기면 남에게 전할 수 있어요.","잊어버리면 아무에게도 전해지지 않아요.","전하는 방법 두 가지를 떠올려요."],"variant_rule":{"alt":[{"stem":"있었던 일을 오래 남기려면 어떻게 하는 것이 좋을까요?","options":[{"t":"글과 그림으로 남긴다","correct":true},{"t":"머릿속으로만 기억한다","mis":"K1-2-u3-X07"},{"t":"아무에게도 말하지 않는다","mis":"K1-2-u3-X07"}],"explanation":["글과 그림으로 남기면 나중에 다시 볼 수 있어요.","머릿속 기억은 시간이 지나면 흐려져요.","그림일기가 바로 그런 방법이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_basic#2','kor',1,2,'u3','L01','g1_2_kor_u3_L01_basic','lesson_basic','K1-2-u3-C1',1,'mc','auto','듣는 사람이 잘 알아듣는 발표는 어느 쪽일까요?',ARRAY['K1-2-u3-X02','K1-2-u3-X01']::text[],true,'{"seq":2,"concept":"K1-2-u3-C1","difficulty":1,"kind":"mc","stem":"듣는 사람이 잘 알아듣는 발표는 어느 쪽일까요?","options":[{"t":"허리를 펴고 듣는 사람을 보며 또박또박 말하는 발표","correct":true},{"t":"고개를 숙이고 아주 작게 말하는 발표","mis":"K1-2-u3-X02"},{"t":"소리를 지르며 빠르게 말하는 발표","mis":"K1-2-u3-X01"}],"explanation":["허리를 펴고 또박또박 말하면 잘 들려요.","고개를 숙이거나 소리를 지르면 말이 또렷하지 않아요.","듣는 사람이 되어 생각해 봐요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"오늘 아침 일을 발표해 볼까요?"},{"who":"준서","text":"(고개를 숙인 채 아주 작게) 밥…먹었어요."},{"who":"하율","text":"(책을 넘기며) 뭐라고?"}]},"variant_rule":{"alt":[{"stem":"두 발표 가운데 말이 더 잘 전해지는 것은 어느 것인가요?","options":[{"t":"단비의 발표","correct":true},{"t":"준서의 발표","mis":"K1-2-u3-X02"},{"t":"둘 다 똑같아요","mis":"K1-2-u3-X02"}],"explanation":["단비는 허리를 펴고 친구들을 보며 말했어요.","준서는 고개를 숙이고 아주 작게 말해서 하율이가 못 알아들었어요.","말풍선 옆 괄호 안을 봐요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"오늘 아침 일을 발표해 볼까요?"},{"who":"단비","text":"(허리를 펴고 친구들을 보며) 오늘 아침에 집 앞에서 노란 나비를 보았어요."},{"who":"은채","text":"(단비를 보며 고개를 끄덕인다)"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_basic#3','kor',1,2,'u3','L01','g1_2_kor_u3_L01_basic','lesson_basic','K1-2-u3-C5',1,'mc','auto','그림일기에 꼭 들어가는 것이 아닌 것은 어느 것인가요?',ARRAY['K1-2-u3-X11']::text[],true,'{"seq":3,"concept":"K1-2-u3-C5","difficulty":1,"kind":"mc","stem":"그림일기에 꼭 들어가는 것이 아닌 것은 어느 것인가요?","options":[{"t":"선생님 성함","correct":true},{"t":"날짜와 요일","mis":"K1-2-u3-X11"},{"t":"그림","mis":"K1-2-u3-X11"}],"explanation":["그림일기에는 날짜와 요일, 날씨, 그림, 글이 들어가요.","선생님 성함은 안내문에나 들어가요.","그림일기 틀을 떠올려요."],"asset":{"type":"diary","date":"10월 6일 화요일","weather":"☀️ 해가 쨍쨍","picture":"🧒🎈🎈","lines":["학교 운동장에서 친구와 풍선을 불었다.","내 풍선이 제일 크게 부풀어서 가슴이 두근거렸다."],"name":"단비"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 그림일기에 꼭 들어가는 것이 아닌 것은 어느 것인가요?","options":[{"t":"준비물","correct":true},{"t":"날씨","mis":"K1-2-u3-X11"},{"t":"글","mis":"K1-2-u3-X11"}],"explanation":["날씨와 글은 그림일기에 들어가요.","준비물은 안내문에 들어가는 것이에요.","단비의 그림일기를 봐요."],"asset":{"type":"diary","date":"10월 6일 화요일","weather":"☀️ 해가 쨍쨍","picture":"🧒🎈🎈","lines":["학교 운동장에서 친구와 풍선을 불었다.","내 풍선이 제일 크게 부풀어서 가슴이 두근거렸다."],"name":"단비"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_basic#4','kor',1,2,'u3','L01','g1_2_kor_u3_L01_basic','lesson_basic','K1-2-u3-C2',1,'mc','auto','친구가 발표할 때 듣는 사람이 해야 할 일은 무엇인가요?',ARRAY['K1-2-u3-X04']::text[],false,'{"seq":4,"concept":"K1-2-u3-C2","difficulty":1,"kind":"mc","stem":"친구가 발표할 때 듣는 사람이 해야 할 일은 무엇인가요?","options":[{"t":"말하는 친구를 바라보며 끝까지 듣는다","correct":true},{"t":"책을 넘기며 듣는다","mis":"K1-2-u3-X04"},{"t":"다른 친구와 이야기한다","mis":"K1-2-u3-X04"}],"explanation":["말하는 사람을 바라보고 끝까지 들어요.","딴 일을 하면 말하는 친구가 말을 잊을 수도 있어요.","단비를 바라보며 끄덕인 은채처럼 해요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"오늘 아침 일을 발표해 볼까요?"},{"who":"단비","text":"(허리를 펴고 친구들을 보며) 오늘 아침에 집 앞에서 노란 나비를 보았어요."},{"who":"은채","text":"(단비를 보며 고개를 끄덕인다)"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_basic#5','kor',1,2,'u3','L01','g1_2_kor_u3_L01_basic','lesson_basic','K1-2-u3-C3',2,'mc','auto','「같은 말인데 왜 다를까요?」 두 친구가 모두 「어제 놀이터에 갔어요」라고 말했어요. 듣는 사람이 장면을 더 잘 떠올리는 말은 어느 것인가요?',ARRAY['K1-2-u3-X07']::text[],false,'{"seq":5,"concept":"K1-2-u3-C3","difficulty":2,"kind":"mc","stem":"「같은 말인데 왜 다를까요?」 두 친구가 모두 「어제 놀이터에 갔어요」라고 말했어요. 듣는 사람이 장면을 더 잘 떠올리는 말은 어느 것인가요?","options":[{"t":"어제 저녁에 집 앞 놀이터에서 동생과 그네를 탔어요","correct":true},{"t":"어제 놀이터에 갔어요","mis":"K1-2-u3-X07"},{"t":"놀이터는 재미있어요","mis":"K1-2-u3-X07"}],"explanation":["언제·어디에서·누구와·무엇을이 들어 있어요.","「놀이터에 갔어요」만으로는 무엇을 했는지 몰라요.","네 칸이 들어 있는지 세어 봐요."],"asset":{"type":"passage","lines":["어제 저녁에 집 앞 놀이터에서 동생과 그네를 탔어요.","동생이 처음으로 혼자 그네를 탔어요.","나는 손뼉을 쳤어요.","동생이 자랑스러워서 기뻤어요."],"title":"시우의 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_basic#6','kor',1,2,'u3','L01','g1_2_kor_u3_L01_basic','lesson_basic','K1-2-u3-C3',2,'mc','auto','경험을 떠올릴 때 어디서부터 떠올리면 좋을까요?',ARRAY['K1-2-u3-X06']::text[],false,'{"seq":6,"concept":"K1-2-u3-C3","difficulty":2,"kind":"mc","stem":"경험을 떠올릴 때 어디서부터 떠올리면 좋을까요?","options":[{"t":"가까운 때(오늘·어제)부터","correct":true},{"t":"태어났을 때부터","mis":"K1-2-u3-X06"},{"t":"아주 특별한 날만","mis":"K1-2-u3-X06"}],"explanation":["가까운 때부터 떠올리면 자세히 생각나요.","너무 먼 일이나 특별한 날만 찾으면 떠오르는 것이 적어요.","오늘 아침부터 되짚어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_basic#7','kor',1,2,'u3','L01','g1_2_kor_u3_L01_basic','lesson_basic','K1-2-u3-C5',2,'match','auto','그림일기의 부분과 거기에 들어가는 것을 선으로 이어 보세요.','{}'::text[],true,'{"seq":7,"concept":"K1-2-u3-C5","difficulty":2,"kind":"match","stem":"그림일기의 부분과 거기에 들어가는 것을 선으로 이어 보세요.","pairs":[{"l":"맨 윗줄","r":"날짜·요일·날씨"},{"l":"그림 칸","r":"가장 기억에 남는 한 장면"},{"l":"글 칸","r":"있었던 일과 느낌"}],"mis":"K1-2-u3-X11","explanation":["맨 윗줄에는 날짜·요일·날씨를 써요.","그림 칸에는 한 장면, 글 칸에는 일과 느낌을 써요.","단비의 그림일기를 위에서부터 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 그림일기의 부분과 거기에 들어가는 것을 선으로 이어 보세요.","pairs":[{"l":"그림 칸","r":"한 장면"},{"l":"글 칸","r":"일과 느낌"},{"l":"맨 윗줄","r":"날짜·요일·날씨"}],"explanation":["그림 칸에는 한 장면이 들어가요.","글 칸에는 있었던 일과 느낌, 맨 윗줄에는 날짜·요일·날씨예요.","틀을 위에서부터 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_basic#8','kor',1,2,'u3','L01','g1_2_kor_u3_L01_basic','lesson_basic','K1-2-u3-C1',2,'ox','auto','발표할 때는 목소리를 크게 지를수록 잘 전해져요.',ARRAY['K1-2-u3-X01']::text[],true,'{"seq":8,"concept":"K1-2-u3-C1","difficulty":2,"kind":"ox","stem":"발표할 때는 목소리를 크게 지를수록 잘 전해져요.","answer":"X","reason_options":[{"t":"소리를 지르면 말이 또렷해지지 않으니 알맞은 크기로 또박또박 말해야 하니까","correct":true},{"t":"목소리가 클수록 멀리까지 들리니까","mis":"K1-2-u3-X01"}],"mis":"K1-2-u3-X01","explanation":["알맞은 크기로 또박또박 말해야 잘 전해져요.","소리를 지르면 커지기만 하고 또렷하지 않아요.","소리를 지르는 것과 알맞게 말하는 것은 달라요."],"variant_rule":{"alt":[{"stem":"발표할 때는 허리를 펴고 듣는 사람을 바라보며 말해요.","answer":"O","reason_options":[{"t":"그래야 하고 싶은 말이 정확하게 전해지니까","correct":true},{"t":"그래야 목소리가 커지니까","mis":"K1-2-u3-X01"}],"explanation":["바른 자세로 말하면 말이 정확하게 전해져요.","목소리 크기와는 다른 이야기예요.","듣는 사람을 보며 말해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_basic#9','kor',1,2,'u3','L01','g1_2_kor_u3_L01_basic','lesson_basic','K1-2-u3-C2',2,'mc','auto','말을 잘 알아들었다는 것을 말하는 사람에게 보여 주려면 어떻게 할까요?',ARRAY['K1-2-u3-X04']::text[],false,'{"seq":9,"concept":"K1-2-u3-C2","difficulty":2,"kind":"mc","stem":"말을 잘 알아들었다는 것을 말하는 사람에게 보여 주려면 어떻게 할까요?","options":[{"t":"고개를 끄덕인다","correct":true},{"t":"눈을 감는다","mis":"K1-2-u3-X04"},{"t":"크게 하품한다","mis":"K1-2-u3-X04"}],"explanation":["고개를 끄덕이면 알아들었다는 것이 보여요.","눈을 감거나 하품하면 안 듣는 것처럼 보여요.","은채가 어떻게 했는지 봐요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"오늘 아침 일을 발표해 볼까요?"},{"who":"단비","text":"(허리를 펴고 친구들을 보며) 오늘 아침에 집 앞에서 노란 나비를 보았어요."},{"who":"은채","text":"(단비를 보며 고개를 끄덕인다)"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_basic#10','kor',1,2,'u3','L01','g1_2_kor_u3_L01_basic','lesson_basic','K1-2-u3-C5',3,'error','auto','그림일기에 들어가는 것을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_challenge#1','kor',1,2,'u3','L01','g1_2_kor_u3_L01_challenge','lesson_challenge','K1-2-u3-C1',2,'mc','auto','하율이가 준서의 말을 알아듣지 못한 까닭은 무엇인가요?',ARRAY['K1-2-u3-X01','K1-2-u3-X04']::text[],false,'{"seq":1,"concept":"K1-2-u3-C1","difficulty":2,"kind":"mc","stem":"하율이가 준서의 말을 알아듣지 못한 까닭은 무엇인가요?","options":[{"t":"준서가 고개를 숙이고 아주 작게 말해서","correct":true},{"t":"준서가 너무 크게 말해서","mis":"K1-2-u3-X01"},{"t":"하율이가 준서를 바라보아서","mis":"K1-2-u3-X04"}],"explanation":["고개를 숙이고 작게 말하면 들리지 않아요.","준서는 크게 말하지 않았고, 하율이는 책을 넘기며 들었어요.","말풍선 옆 괄호 안을 봐요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"오늘 아침 일을 발표해 볼까요?"},{"who":"준서","text":"(고개를 숙인 채 아주 작게) 밥…먹었어요."},{"who":"하율","text":"(책을 넘기며) 뭐라고?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_challenge#2','kor',1,2,'u3','L01','g1_2_kor_u3_L01_challenge','lesson_challenge','K1-2-u3-C2',2,'mc','auto','하율이가 바르게 듣지 못한 점은 무엇인가요?',ARRAY['K1-2-u3-X04']::text[],false,'{"seq":2,"concept":"K1-2-u3-C2","difficulty":2,"kind":"mc","stem":"하율이가 바르게 듣지 못한 점은 무엇인가요?","options":[{"t":"책을 넘기며 들었다","correct":true},{"t":"준서를 바라보며 들었다","mis":"K1-2-u3-X04"},{"t":"끝까지 조용히 들었다","mis":"K1-2-u3-X04"}],"explanation":["책을 넘기며 들으면 말을 놓쳐요.","바라보며 끝까지 듣는 것은 바른 자세예요.","하율이의 괄호 안을 봐요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"오늘 아침 일을 발표해 볼까요?"},{"who":"준서","text":"(고개를 숙인 채 아주 작게) 밥…먹었어요."},{"who":"하율","text":"(책을 넘기며) 뭐라고?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_challenge#3','kor',1,2,'u3','L01','g1_2_kor_u3_L01_challenge','lesson_challenge','K1-2-u3-C3',3,'mc','auto','시우의 발표에 들어 있지 않은 것은 어느 것인가요?',ARRAY['K1-2-u3-X07']::text[],false,'{"seq":3,"concept":"K1-2-u3-C3","difficulty":3,"kind":"mc","stem":"시우의 발표에 들어 있지 않은 것은 어느 것인가요?","options":[{"t":"누구와 함께 보러 갔는지 적은 선생님 성함","correct":true},{"t":"언제 있었던 일인지","mis":"K1-2-u3-X07"},{"t":"그때 느낌이 어땠는지","mis":"K1-2-u3-X07"}],"explanation":["「어제 저녁」이 언제, 「기뻤어요」가 느낌이에요.","선생님 성함은 발표에 필요한 것이 아니에요.","네 칸(언제·어디·무엇·느낌)을 짚어요."],"asset":{"type":"passage","lines":["어제 저녁에 집 앞 놀이터에서 동생과 그네를 탔어요.","동생이 처음으로 혼자 그네를 탔어요.","나는 손뼉을 쳤어요.","동생이 자랑스러워서 기뻤어요."],"title":"시우의 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_challenge#4','kor',1,2,'u3','L01','g1_2_kor_u3_L01_challenge','lesson_challenge','K1-2-u3-C1',3,'error','auto','발표할 때 지킬 것을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_challenge#5','kor',1,2,'u3','L01','g1_2_kor_u3_L01_challenge','lesson_challenge','K1-2-u3-C5',3,'mc','auto','단비의 그림일기에서 「해가 쨍쨍」은 어느 자리에 쓴 것인가요?',ARRAY['K1-2-u3-X11']::text[],false,'{"seq":5,"concept":"K1-2-u3-C5","difficulty":3,"kind":"mc","stem":"단비의 그림일기에서 「해가 쨍쨍」은 어느 자리에 쓴 것인가요?","options":[{"t":"맨 윗줄, 날짜와 요일 옆 날씨 자리","correct":true},{"t":"글 칸 맨 끝","mis":"K1-2-u3-X11"},{"t":"그림 칸 안","mis":"K1-2-u3-X11"}],"explanation":["날씨는 맨 윗줄 날짜·요일 옆에 써요.","글 끝이나 그림 안에 쓰는 것이 아니에요.","틀의 맨 윗줄을 봐요."],"asset":{"type":"diary","date":"10월 6일 화요일","weather":"☀️ 해가 쨍쨍","picture":"🧒🎈🎈","lines":["학교 운동장에서 친구와 풍선을 불었다.","내 풍선이 제일 크게 부풀어서 가슴이 두근거렸다."],"name":"단비"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_challenge#6','kor',1,2,'u3','L01','g1_2_kor_u3_L01_challenge','lesson_challenge','K1-2-u3-C3',3,'mc','auto','하율이의 발표에서 「느낌」에 해당하는 말은 어느 것인가요?',ARRAY['K1-2-u3-X07']::text[],false,'{"seq":6,"concept":"K1-2-u3-C3","difficulty":3,"kind":"mc","stem":"하율이의 발표에서 「느낌」에 해당하는 말은 어느 것인가요?","options":[{"t":"다람쥐가 너무 가까이 와서 놀랐어요","correct":true},{"t":"우리 반은 뒷산에 올라갔어요","mis":"K1-2-u3-X07"},{"t":"다람쥐가 도토리를 물고 지나갔어요","mis":"K1-2-u3-X07"}],"explanation":["「놀랐어요」가 그때 느낌이에요.","뒷산에 간 것과 다람쥐가 지나간 것은 있었던 일이에요.","느낌을 나타내는 말을 찾아요."],"asset":{"type":"passage","lines":["지난주 금요일에 우리 반은 뒷산에 올라갔어요.","다람쥐가 도토리를 물고 지나갔어요.","우리는 숨을 죽이고 지켜보았어요.","다람쥐가 너무 가까이 와서 놀랐어요."],"title":"하율의 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_challenge#7','kor',1,2,'u3','L01','g1_2_kor_u3_L01_challenge','lesson_challenge','K1-2-u3-C2',3,'ox','auto','친구가 말하다가 말을 잊으면 「그것도 못 해?」 하고 말해 주는 것이 좋아요.',ARRAY['K1-2-u3-X05']::text[],false,'{"seq":7,"concept":"K1-2-u3-C2","difficulty":3,"kind":"ox","stem":"친구가 말하다가 말을 잊으면 「그것도 못 해?」 하고 말해 주는 것이 좋아요.","answer":"X","reason_options":[{"t":"나무라지 않고 어떻게 하면 좋을지 알려 주는 말이 친구에게 힘이 되니까","correct":true},{"t":"그래야 다음에 안 잊으니까","mis":"K1-2-u3-X05"}],"mis":"K1-2-u3-X05","explanation":["나무라는 말은 친구를 더 긴장하게 해요.","「천천히 다시 말해 봐」처럼 알려 주는 말이 좋아요.","단비가 은채에게 한 말을 떠올려요."],"asset":{"type":"speech","turns":[{"who":"은채","text":"(그림을 그리며 듣지 않는다)"},{"who":"단비","text":"은채야, 시우가 말할 때는 시우를 바라보면 좋겠어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_challenge#8','kor',1,2,'u3','L01','g1_2_kor_u3_L01_challenge','lesson_challenge','K1-2-u3-C5',4,'sa','auto','그림일기의 맨 윗줄에 쓰는 세 가지는 날짜, 요일, 그리고 무엇인가요? 한 낱말로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"K1-2-u3-C5","difficulty":4,"kind":"sa","stem":"그림일기의 맨 윗줄에 쓰는 세 가지는 날짜, 요일, 그리고 무엇인가요? 한 낱말로 쓰세요.","answer":["날씨"],"explanation":["맨 윗줄에는 날짜·요일·날씨를 써요.","그림이나 글은 아래 칸에 들어가요.","단비의 그림일기 맨 윗줄을 봐요."],"asset":{"type":"diary","date":"10월 6일 화요일","weather":"☀️ 해가 쨍쨍","picture":"🧒🎈🎈","lines":["학교 운동장에서 친구와 풍선을 불었다.","내 풍선이 제일 크게 부풀어서 가슴이 두근거렸다."],"name":"단비"},"variant_rule":{"alt":[{"stem":"그림일기의 세 부분은 맨 윗줄, 글 칸, 그리고 어느 칸인가요? 한 낱말로 쓰세요.","answer":["그림","그림 칸","그림칸"],"explanation":["그림일기는 맨 윗줄·그림·글 세 부분이에요.","날씨는 맨 윗줄에 들어가요.","틀을 위에서부터 봐요."],"asset":{"type":"diary","date":"10월 6일 화요일","weather":"☀️ 해가 쨍쨍","picture":"🧒🎈🎈","lines":["학교 운동장에서 친구와 풍선을 불었다.","내 풍선이 제일 크게 부풀어서 가슴이 두근거렸다."],"name":"단비"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_challenge#9','kor',1,2,'u3','L01','g1_2_kor_u3_L01_challenge','lesson_challenge','K1-2-u3-C3',4,'essay','teacher','오늘 아침에 있었던 일을 「언제 · 어디에서 · 무엇을 · 느낌」이 들어가게 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u3-C3","difficulty":4,"kind":"essay","stem":"오늘 아침에 있었던 일을 「언제 · 어디에서 · 무엇을 · 느낌」이 들어가게 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 오늘 아침에 집 앞에서 노란 나비를 보아서 반가웠다. — 네 칸이 들어 있으면 맞아요. 특별한 일이 아니어도 돼요.","scoring_points":["언제·어디에서가 있는가","무엇을 했는지가 있는가","느낌이 있는가"]},"explanation":["네 칸이 다 들어가면 듣는 사람이 장면을 떠올려요.","특별한 일이 아니어도 그때 느낌이 남았으면 돼요.","가까운 때부터 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_challenge#10','kor',1,2,'u3','L01','g1_2_kor_u3_L01_challenge','lesson_challenge','K1-2-u3-C1',4,'essay','teacher','친구 앞에서 발표할 때 지킬 것을 두 가지 쓰고, 그렇게 하면 무엇이 좋은지 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u3-C1","difficulty":4,"kind":"essay","stem":"친구 앞에서 발표할 때 지킬 것을 두 가지 쓰고, 그렇게 하면 무엇이 좋은지 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 허리를 펴고 듣는 사람을 바라본다, 알맞은 크기로 또박또박 말한다. 그러면 하고 싶은 말이 정확하게 전해진다. — 지킬 것 둘과 좋은 점이 있으면 맞아요.","scoring_points":["지킬 것을 두 가지 썼는가","둘 다 바른 발표 자세인가","좋은 점(정확하게 전해진다 등)을 썼는가"]},"explanation":["허리·눈·목소리 가운데 둘을 골라요.","소리 지르기는 지킬 것이 아니에요.","그렇게 하면 말이 정확하게 전해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_basic#1','kor',1,2,'u3','L02','g1_2_kor_u3_L02_basic','lesson_basic','K1-2-u3-C1',1,'mc','auto','바른 자세로 발표하는 사람은 누구일까요?',ARRAY['K1-2-u3-X02','K1-2-u3-X04']::text[],false,'{"seq":1,"concept":"K1-2-u3-C1","difficulty":1,"kind":"mc","stem":"바른 자세로 발표하는 사람은 누구일까요?","options":[{"t":"허리를 펴고 친구들을 보며 말하는 단비","correct":true},{"t":"고개를 숙이고 작게 말하는 준서","mis":"K1-2-u3-X02"},{"t":"책을 넘기며 듣는 하율","mis":"K1-2-u3-X04"}],"explanation":["단비는 허리를 펴고 듣는 사람을 보며 말했어요.","준서는 고개를 숙였고, 하율이는 말하는 사람이 아니에요.","괄호 안 자세를 봐요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"오늘 아침 일을 발표해 볼까요?"},{"who":"단비","text":"(허리를 펴고 친구들을 보며) 오늘 아침에 집 앞에서 노란 나비를 보았어요."},{"who":"은채","text":"(단비를 보며 고개를 끄덕인다)"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_basic#2','kor',1,2,'u3','L02','g1_2_kor_u3_L02_basic','lesson_basic','K1-2-u3-C1',1,'mc','auto','발표할 때 목소리는 어떻게 해야 할까요?',ARRAY['K1-2-u3-X01','K1-2-u3-X02']::text[],true,'{"seq":2,"concept":"K1-2-u3-C1","difficulty":1,"kind":"mc","stem":"발표할 때 목소리는 어떻게 해야 할까요?","options":[{"t":"알맞은 크기로 또박또박","correct":true},{"t":"되도록 크게 지르기","mis":"K1-2-u3-X01"},{"t":"들리지 않게 아주 작게","mis":"K1-2-u3-X02"}],"explanation":["알맞은 크기로 또박또박 말해요.","지르면 또렷하지 않고, 작으면 안 들려요.","듣는 사람이 편하게 듣는 크기예요."],"variant_rule":{"alt":[{"stem":"발표할 때 말은 어떻게 해야 할까요?","options":[{"t":"또박또박 천천히","correct":true},{"t":"빨리 한꺼번에","mis":"K1-2-u3-X01"},{"t":"속으로만","mis":"K1-2-u3-X02"}],"explanation":["또박또박 천천히 말해야 알아들어요.","빨리 하거나 속으로 하면 전해지지 않아요.","한 마디씩 끊어 말해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_basic#3','kor',1,2,'u3','L02','g1_2_kor_u3_L02_basic','lesson_basic','K1-2-u3-C2',1,'mc','auto','들을 때 해야 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u3-X04']::text[],true,'{"seq":3,"concept":"K1-2-u3-C2","difficulty":1,"kind":"mc","stem":"들을 때 해야 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"말하는 사람을 바라본다","correct":true},{"t":"그림을 그린다","mis":"K1-2-u3-X04"},{"t":"옆 친구와 이야기한다","mis":"K1-2-u3-X04"}],"explanation":["말하는 사람을 바라보며 들어요.","그림을 그리거나 이야기하면 딴 일을 하는 거예요.","눈이 어디를 보는지 생각해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 들을 때 해야 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"끝까지 듣는다","correct":true},{"t":"중간에 끼어든다","mis":"K1-2-u3-X05"},{"t":"창밖을 본다","mis":"K1-2-u3-X04"}],"explanation":["끝까지 들은 뒤에 말해요.","끼어들거나 창밖을 보면 말하는 사람이 말을 잊어요.","끝까지, 바라보며."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_basic#4','kor',1,2,'u3','L02','g1_2_kor_u3_L02_basic','lesson_basic','K1-2-u3-C1',1,'mc','auto','발표하기 전에 먼저 해야 할 일은 무엇인가요?',ARRAY['K1-2-u3-X01','K1-2-u3-X03']::text[],false,'{"seq":4,"concept":"K1-2-u3-C1","difficulty":1,"kind":"mc","stem":"발표하기 전에 먼저 해야 할 일은 무엇인가요?","options":[{"t":"무엇을 말할지 정한다","correct":true},{"t":"소리를 크게 낼 준비를 한다","mis":"K1-2-u3-X01"},{"t":"일어나서 생각한다","mis":"K1-2-u3-X03"}],"explanation":["무엇을 말할지 정한 뒤 일어나요.","정하지 않고 일어나면 말이 막혀요.","속으로 한 번 말해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_basic#5','kor',1,2,'u3','L02','g1_2_kor_u3_L02_basic','lesson_basic','K1-2-u3-C1',2,'mc','auto','허리를 펴고 듣는 사람을 바라보며 발표하면 무엇이 좋은가요?',ARRAY['K1-2-u3-X01','K1-2-u3-X02']::text[],false,'{"seq":5,"concept":"K1-2-u3-C1","difficulty":2,"kind":"mc","stem":"허리를 펴고 듣는 사람을 바라보며 발표하면 무엇이 좋은가요?","options":[{"t":"하고 싶은 말이 정확하게 전해진다","correct":true},{"t":"목소리가 저절로 커진다","mis":"K1-2-u3-X01"},{"t":"발표가 빨리 끝난다","mis":"K1-2-u3-X02"}],"explanation":["바른 자세는 말을 정확하게 전해 줘요.","목소리 크기나 빠르기와는 다른 일이에요.","듣는 사람을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_basic#6','kor',1,2,'u3','L02','g1_2_kor_u3_L02_basic','lesson_basic','K1-2-u3-C1',2,'match','auto','발표 자세와 그 까닭을 선으로 이어 보세요.','{}'::text[],true,'{"seq":6,"concept":"K1-2-u3-C1","difficulty":2,"kind":"match","stem":"발표 자세와 그 까닭을 선으로 이어 보세요.","pairs":[{"l":"허리를 편다","r":"말이 또렷하게 나온다"},{"l":"듣는 사람을 바라본다","r":"누구에게 말하는지 보인다"},{"l":"알맞은 크기로 말한다","r":"뒤에 앉은 친구도 들린다"}],"mis":"K1-2-u3-X02","explanation":["허리를 펴면 말이 또렷해요.","바라보면 누구에게 말하는지, 알맞은 크기면 뒤까지 들려요.","자세마다 까닭이 있어요."],"variant_rule":{"alt":[{"stem":"듣는 자세와 그 까닭을 선으로 이어 보세요.","pairs":[{"l":"바라보며 듣는다","r":"말하는 사람이 힘이 난다"},{"l":"끝까지 듣는다","r":"하려던 말을 끝까지 들을 수 있다"},{"l":"고개를 끄덕인다","r":"알아들었다는 것이 보인다"}],"explanation":["바라보면 말하는 사람이 힘이 나요.","끝까지 들어야 다 듣고, 끄덕이면 알아들었다는 것이 보여요.","듣는 자세에도 까닭이 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_basic#7','kor',1,2,'u3','L02','g1_2_kor_u3_L02_basic','lesson_basic','K1-2-u3-C2',2,'mc','auto','시우가 말을 잊고 머뭇거린 까닭은 무엇인가요?',ARRAY['K1-2-u3-X01','K1-2-u3-X03']::text[],false,'{"seq":7,"concept":"K1-2-u3-C2","difficulty":2,"kind":"mc","stem":"시우가 말을 잊고 머뭇거린 까닭은 무엇인가요?","options":[{"t":"준서가 말을 자르고 끼어들어서","correct":true},{"t":"시우가 소리를 질러서","mis":"K1-2-u3-X01"},{"t":"시우가 발표 전에 말할 것을 정해서","mis":"K1-2-u3-X03"}],"explanation":["말을 자르면 말하던 사람이 하려던 말을 잊어요.","시우는 소리를 지르지 않았고, 미리 정한 것은 좋은 일이에요.","준서의 괄호 안을 봐요."],"asset":{"type":"speech","turns":[{"who":"시우","text":"지난주에 할머니 댁에서…"},{"who":"준서","text":"(말을 자르며) 나도 할머니 댁 갔어!"},{"who":"시우","text":"(말을 잊고 머뭇거린다)"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_basic#8','kor',1,2,'u3','L02','g1_2_kor_u3_L02_basic','lesson_basic','K1-2-u3-C2',2,'mc','auto','딴 일을 하며 듣는 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u3-X05','K1-2-u3-X04']::text[],false,'{"seq":8,"concept":"K1-2-u3-C2","difficulty":2,"kind":"mc","stem":"딴 일을 하며 듣는 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"말하는 친구를 바라보면 좋겠어.","correct":true},{"t":"너는 왜 그것도 못 해?","mis":"K1-2-u3-X05"},{"t":"그냥 네 마음대로 해.","mis":"K1-2-u3-X04"}],"explanation":["나무라지 않고 어떻게 하면 좋을지 알려 주는 말이에요.","나무라거나 내버려 두면 바뀌지 않아요.","단비가 은채에게 한 말을 봐요."],"asset":{"type":"speech","turns":[{"who":"은채","text":"(그림을 그리며 듣지 않는다)"},{"who":"단비","text":"은채야, 시우가 말할 때는 시우를 바라보면 좋겠어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_basic#9','kor',1,2,'u3','L02','g1_2_kor_u3_L02_basic','lesson_basic','K1-2-u3-C2',2,'ox','auto','말을 잘 알아들었을 때는 고개를 끄덕여 주면 좋아요.',ARRAY['K1-2-u3-X04']::text[],false,'{"seq":9,"concept":"K1-2-u3-C2","difficulty":2,"kind":"ox","stem":"말을 잘 알아들었을 때는 고개를 끄덕여 주면 좋아요.","answer":"O","reason_options":[{"t":"말하는 사람이 알아들었다는 것을 알 수 있으니까","correct":true},{"t":"그래야 발표가 빨리 끝나니까","mis":"K1-2-u3-X04"}],"mis":"K1-2-u3-X04","explanation":["끄덕이면 알아들었다는 것이 보여요.","빨리 끝내려고 하는 것이 아니에요.","말하는 사람 마음을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_basic#10','kor',1,2,'u3','L02','g1_2_kor_u3_L02_basic','lesson_basic','K1-2-u3-C2',3,'error','auto','바르게 듣는 모습을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_challenge#1','kor',1,2,'u3','L02','g1_2_kor_u3_L02_challenge','lesson_challenge','K1-2-u3-C1',2,'mc','auto','발표 전에 할 일을 모두 한 친구는 누구일까요?',ARRAY['K1-2-u3-X03','K1-2-u3-X01']::text[],false,'{"seq":1,"concept":"K1-2-u3-C1","difficulty":2,"kind":"mc","stem":"발표 전에 할 일을 모두 한 친구는 누구일까요?","options":[{"t":"무엇을 말할지 한 문장으로 정하고 속으로 한 번 말해 본 단비","correct":true},{"t":"일어난 뒤에 무엇을 말할지 생각한 준서","mis":"K1-2-u3-X03"},{"t":"목소리를 지를 준비만 한 하율","mis":"K1-2-u3-X01"}],"explanation":["말할 것을 정하고 속으로 말해 본 뒤 일어나요.","일어나서 생각하면 말이 막히고, 소리 지르기는 준비가 아니에요.","발표 전 할 일 두 가지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_challenge#2','kor',1,2,'u3','L02','g1_2_kor_u3_L02_challenge','lesson_challenge','K1-2-u3-C2',2,'mc','auto','친구가 발표할 때 「책을 넘기며 듣기」가 안 되는 까닭은 무엇인가요?',ARRAY['K1-2-u3-X04']::text[],false,'{"seq":2,"concept":"K1-2-u3-C2","difficulty":2,"kind":"mc","stem":"친구가 발표할 때 「책을 넘기며 듣기」가 안 되는 까닭은 무엇인가요?","options":[{"t":"말하는 친구가 하려던 말을 잊을 수도 있어서","correct":true},{"t":"책이 찢어질 수 있어서","mis":"K1-2-u3-X04"},{"t":"선생님이 혼내서","mis":"K1-2-u3-X04"}],"explanation":["듣는 사람이 딴 일을 하면 말하는 사람이 힘이 빠지고 말을 잊어요.","책이나 선생님 때문이 아니에요.","말하는 사람 마음을 떠올려요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"오늘 아침 일을 발표해 볼까요?"},{"who":"준서","text":"(고개를 숙인 채 아주 작게) 밥…먹었어요."},{"who":"하율","text":"(책을 넘기며) 뭐라고?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_challenge#3','kor',1,2,'u3','L02','g1_2_kor_u3_L02_challenge','lesson_challenge','K1-2-u3-C1',3,'mc','auto','「허리를 펴고 또박또박 말하면 좋다」는 말과 뜻이 같은 것은 어느 것인가요?',ARRAY['K1-2-u3-X08','K1-2-u3-X01']::text[],false,'{"seq":3,"concept":"K1-2-u3-C1","difficulty":3,"kind":"mc","stem":"「허리를 펴고 또박또박 말하면 좋다」는 말과 뜻이 같은 것은 어느 것인가요?","options":[{"t":"바른 자세로 말하면 하고 싶은 말이 정확하게 전해진다","correct":true},{"t":"바른 자세로 말하면 발표를 제일 잘한 사람이 된다","mis":"K1-2-u3-X08"},{"t":"허리를 펴면 목소리가 커진다","mis":"K1-2-u3-X01"}],"explanation":["바른 자세는 말을 정확하게 전하려고 하는 거예요.","누가 제일 잘했는지 가리려는 것도, 목소리를 키우려는 것도 아니에요.","왜 바른 자세로 말하는지 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_challenge#4','kor',1,2,'u3','L02','g1_2_kor_u3_L02_challenge','lesson_challenge','K1-2-u3-C1',3,'error','auto','발표하기 전에 할 일을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_challenge#5','kor',1,2,'u3','L02','g1_2_kor_u3_L02_challenge','lesson_challenge','K1-2-u3-C2',3,'mc','auto','준서가 시우에게 해야 했던 바른 행동은 무엇인가요?',ARRAY['K1-2-u3-X05','K1-2-u3-X04']::text[],false,'{"seq":5,"concept":"K1-2-u3-C2","difficulty":3,"kind":"mc","stem":"준서가 시우에게 해야 했던 바른 행동은 무엇인가요?","options":[{"t":"시우가 다 말할 때까지 듣고 나서 자기 이야기를 한다","correct":true},{"t":"더 큰 소리로 자기 이야기를 한다","mis":"K1-2-u3-X05"},{"t":"시우를 보지 않고 다른 생각을 한다","mis":"K1-2-u3-X04"}],"explanation":["끝까지 듣고 나서 말해요.","더 크게 끼어들거나 딴 생각을 하면 더 나빠져요.","말을 자르면 생기는 일을 떠올려요."],"asset":{"type":"speech","turns":[{"who":"시우","text":"지난주에 할머니 댁에서…"},{"who":"준서","text":"(말을 자르며) 나도 할머니 댁 갔어!"},{"who":"시우","text":"(말을 잊고 머뭇거린다)"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_challenge#6','kor',1,2,'u3','L02','g1_2_kor_u3_L02_challenge','lesson_challenge','K1-2-u3-C1',3,'ox','auto','목소리를 크게 하는 것과 알맞은 크기로 또박또박 말하는 것은 같은 일이에요.',ARRAY['K1-2-u3-X01']::text[],false,'{"seq":6,"concept":"K1-2-u3-C1","difficulty":3,"kind":"ox","stem":"목소리를 크게 하는 것과 알맞은 크기로 또박또박 말하는 것은 같은 일이에요.","answer":"X","reason_options":[{"t":"소리를 지르면 커지기만 하고 말이 또렷해지지는 않으니까","correct":true},{"t":"둘 다 목소리에 관한 일이니까","mis":"K1-2-u3-X01"}],"mis":"K1-2-u3-X01","explanation":["크게 지르는 것과 또박또박은 달라요.","알맞은 크기로 한 마디씩 끊어 말해야 또렷해요.","뒤에 앉은 친구가 편하게 듣는 크기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_challenge#7','kor',1,2,'u3','L02','g1_2_kor_u3_L02_challenge','lesson_challenge','K1-2-u3-C2',3,'match','auto','듣는 모습과 그것이 말하는 사람에게 주는 영향을 선으로 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"K1-2-u3-C2","difficulty":3,"kind":"match","stem":"듣는 모습과 그것이 말하는 사람에게 주는 영향을 선으로 이어 보세요.","pairs":[{"l":"바라보며 끄덕인다","r":"힘이 나서 말이 잘 나온다"},{"l":"딴 일을 하며 듣는다","r":"하려던 말을 잊는다"},{"l":"중간에 끼어든다","r":"말이 끊겨 머뭇거린다"}],"mis":"K1-2-u3-X04","explanation":["바라보며 끄덕이면 말하는 사람이 힘이 나요.","딴 일을 하면 말을 잊고, 끼어들면 말이 끊겨요.","듣는 모습이 말하는 사람을 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_challenge#8','kor',1,2,'u3','L02','g1_2_kor_u3_L02_challenge','lesson_challenge','K1-2-u3-C1',4,'sa','auto','발표할 때 지킬 것 세 가지 가운데 빈칸에 들어갈 말을 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_challenge#9','kor',1,2,'u3','L02','g1_2_kor_u3_L02_challenge','lesson_challenge','K1-2-u3-C2',4,'essay','teacher','은채가 그림을 그리며 듣고 있어요. 나무라지 않고 어떻게 하면 좋을지 알려 주는 말을 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u3-C2","difficulty":4,"kind":"essay","stem":"은채가 그림을 그리며 듣고 있어요. 나무라지 않고 어떻게 하면 좋을지 알려 주는 말을 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 은채야, 시우가 말할 때는 그림을 잠깐 두고 시우를 바라보면 좋겠어. — 나무라는 말이 없고 어떻게 하면 좋을지가 들어 있으면 맞아요.","scoring_points":["나무라는 말(못 해·왜 그래)이 없는가","어떻게 하면 좋을지가 들어 있는가","은채에게 하는 말로 썼는가"]},"explanation":["「~하면 좋겠어」처럼 알려 주는 말이에요.","「그것도 못 해?」는 나무라는 말이에요.","단비의 말을 본보기로 삼아요."],"asset":{"type":"speech","turns":[{"who":"은채","text":"(그림을 그리며 듣지 않는다)"},{"who":"단비","text":"은채야, 시우가 말할 때는 시우를 바라보면 좋겠어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_challenge#10','kor',1,2,'u3','L02','g1_2_kor_u3_L02_challenge','lesson_challenge','K1-2-u3-C1',4,'essay','teacher','준서의 발표를 듣고, 준서가 고치면 좋을 점 두 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u3-C1","difficulty":4,"kind":"essay","stem":"준서의 발표를 듣고, 준서가 고치면 좋을 점 두 가지를 쓰세요.","answer_guide":{"answer":"예: 고개를 들고 친구들을 바라보며 말한다, 알맞은 크기로 또박또박 말한다. — 자세와 목소리 두 가지가 있으면 맞아요.","scoring_points":["자세(고개·허리·눈)에 관한 것이 있는가","목소리 크기에 관한 것이 있는가","「못한다」가 아니라 고칠 방법으로 썼는가"]},"explanation":["준서는 고개를 숙이고 아주 작게 말했어요.","고개를 들고 바라보기, 알맞은 크기로 말하기예요.","잘못을 나무라지 말고 방법을 써요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"오늘 아침 일을 발표해 볼까요?"},{"who":"준서","text":"(고개를 숙인 채 아주 작게) 밥…먹었어요."},{"who":"하율","text":"(책을 넘기며) 뭐라고?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_basic#1','kor',1,2,'u3','L04','g1_2_kor_u3_L04_basic','lesson_basic','K1-2-u3-C3',1,'mc','auto','경험한 일을 자세히 정리할 때 채우는 네 칸이 아닌 것은 어느 것인가요?',ARRAY['K1-2-u3-X07']::text[],true,'{"seq":1,"concept":"K1-2-u3-C3","difficulty":1,"kind":"mc","stem":"경험한 일을 자세히 정리할 때 채우는 네 칸이 아닌 것은 어느 것인가요?","options":[{"t":"선생님 성함","correct":true},{"t":"언제","mis":"K1-2-u3-X07"},{"t":"어디에서","mis":"K1-2-u3-X07"}],"explanation":["네 칸은 언제·어디에서·무엇을·느낌이에요.","선생님 성함은 네 칸에 없어요.","네 칸을 손가락으로 세어 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 경험한 일을 자세히 정리할 때 채우는 네 칸이 아닌 것은 어느 것인가요?","options":[{"t":"몇 점을 받았나","correct":true},{"t":"무엇을","mis":"K1-2-u3-X07"},{"t":"느낌","mis":"K1-2-u3-X07"}],"explanation":["네 칸은 언제·어디에서·무엇을·느낌이에요.","점수는 네 칸에 없어요.","네 칸을 세어 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_basic#2','kor',1,2,'u3','L04','g1_2_kor_u3_L04_basic','lesson_basic','K1-2-u3-C3',1,'mc','auto','특별한 일이 없었던 날에는 발표할 것이 없을까요?',ARRAY['K1-2-u3-X06']::text[],false,'{"seq":2,"concept":"K1-2-u3-C3","difficulty":1,"kind":"mc","stem":"특별한 일이 없었던 날에는 발표할 것이 없을까요?","options":[{"t":"아니요, 늘 있는 일이라도 그때 느낌이 남았으면 좋은 이야깃거리예요","correct":true},{"t":"네, 큰 일이 있어야만 발표할 수 있어요","mis":"K1-2-u3-X06"},{"t":"네, 특별한 날을 기다려야 해요","mis":"K1-2-u3-X06"}],"explanation":["늘 있는 일이라도 느낌이 남았으면 돼요.","큰 일이 있어야만 발표하는 것이 아니에요.","오늘 아침 작은 일을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_basic#3','kor',1,2,'u3','L04','g1_2_kor_u3_L04_basic','lesson_basic','K1-2-u3-C3',1,'mc','auto','경험한 일이 더 잘 드러난 문장은 어느 것인가요?',ARRAY['K1-2-u3-X07']::text[],true,'{"seq":3,"concept":"K1-2-u3-C3","difficulty":1,"kind":"mc","stem":"경험한 일이 더 잘 드러난 문장은 어느 것인가요?","options":[{"t":"오늘 아침에 신발장 앞에서 실내화 한 짝을 잃어버렸어요","correct":true},{"t":"실내화요","mis":"K1-2-u3-X07"},{"t":"잃어버렸어요","mis":"K1-2-u3-X07"}],"explanation":["언제·어디에서·무엇을이 들어 있어요.","한 낱말만 말하면 무슨 일인지 몰라요.","네 칸이 몇 개 들어 있는지 세어요."],"asset":{"type":"passage","lines":["오늘 아침에 신발장 앞에서 실내화 한 짝을 잃어버렸어요.","친구 은채가 함께 찾아 주었어요.","우산꽂이 옆에서 찾았을 때 마음이 놓였어요."],"title":"단비의 발표"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 경험한 일이 더 잘 드러난 문장은 어느 것인가요?","options":[{"t":"지난주 금요일에 우리 반은 뒷산에 올라갔어요","correct":true},{"t":"뒷산이요","mis":"K1-2-u3-X07"},{"t":"올라갔어요","mis":"K1-2-u3-X07"}],"explanation":["언제·누가·어디에·무엇을이 들어 있어요.","한 낱말만으로는 장면이 안 보여요.","네 칸을 세어요."],"asset":{"type":"passage","lines":["지난주 금요일에 우리 반은 뒷산에 올라갔어요.","다람쥐가 도토리를 물고 지나갔어요.","우리는 숨을 죽이고 지켜보았어요.","다람쥐가 너무 가까이 와서 놀랐어요."],"title":"하율의 발표"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_basic#4','kor',1,2,'u3','L04','g1_2_kor_u3_L04_basic','lesson_basic','K1-2-u3-C3',1,'mc','auto','발표를 시작할 첫마디로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u3-X07']::text[],false,'{"seq":4,"concept":"K1-2-u3-C3","difficulty":1,"kind":"mc","stem":"발표를 시작할 첫마디로 알맞은 것은 어느 것인가요?","options":[{"t":"오늘 아침에 있었던 일이에요.","correct":true},{"t":"끝이에요.","mis":"K1-2-u3-X07"},{"t":"재미있었어요.","mis":"K1-2-u3-X07"}],"explanation":["언제 있었던 일인지부터 말하면 듣기 좋아요.","「끝」이나 느낌부터 말하면 무슨 일인지 몰라요.","언제부터 시작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_basic#5','kor',1,2,'u3','L04','g1_2_kor_u3_L04_basic','lesson_basic','K1-2-u3-C3',2,'match','auto','물음과 알맞은 대답을 선으로 이어 보세요. (단비의 발표)','{}'::text[],true,'{"seq":5,"concept":"K1-2-u3-C3","difficulty":2,"kind":"match","stem":"물음과 알맞은 대답을 선으로 이어 보세요. (단비의 발표)","pairs":[{"l":"언제","r":"오늘 아침에"},{"l":"어디에서","r":"신발장 앞에서"},{"l":"무엇을","r":"실내화 한 짝을 잃어버렸다"},{"l":"느낌","r":"마음이 놓였다"}],"mis":"K1-2-u3-X07","explanation":["첫 줄에 언제·어디에서·무엇을이 있어요.","셋째 줄 끝에 느낌이 있어요.","발표를 한 줄씩 읽으며 짝을 찾아요."],"variant_rule":{"alt":[{"stem":"물음과 알맞은 대답을 선으로 이어 보세요. (시우의 발표)","pairs":[{"l":"언제","r":"어제 저녁에"},{"l":"어디에서","r":"집 앞 놀이터에서"},{"l":"무엇을","r":"동생과 그네를 탔다"},{"l":"느낌","r":"기뻤다"}],"explanation":["첫 줄에 언제·어디에서·무엇을이 있어요.","마지막 줄에 느낌이 있어요.","한 줄씩 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_basic#6','kor',1,2,'u3','L04','g1_2_kor_u3_L04_basic','lesson_basic','K1-2-u3-C3',2,'mc','auto','발표할 내용에 넣으면 듣는 사람이 장면을 떠올리기 좋은 것은 어느 것인가요?',ARRAY['K1-2-u3-X07']::text[],false,'{"seq":6,"concept":"K1-2-u3-C3","difficulty":2,"kind":"mc","stem":"발표할 내용에 넣으면 듣는 사람이 장면을 떠올리기 좋은 것은 어느 것인가요?","options":[{"t":"그때 누가 무엇을 어떻게 했는지","correct":true},{"t":"내가 몇 살인지","mis":"K1-2-u3-X07"},{"t":"친구들 이름 전부","mis":"K1-2-u3-X07"}],"explanation":["누가 무엇을 어떻게 했는지가 있으면 장면이 그려져요.","나이나 이름 목록은 장면과 상관없어요.","듣는 사람 머릿속에 그림이 그려지게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_basic#7','kor',1,2,'u3','L04','g1_2_kor_u3_L04_basic','lesson_basic','K1-2-u3-C3',2,'mc','auto','준서의 발표에서 빠진 것을 모두 고른 것은 어느 것인가요?',ARRAY['K1-2-u3-X07']::text[],false,'{"seq":7,"concept":"K1-2-u3-C3","difficulty":2,"kind":"mc","stem":"준서의 발표에서 빠진 것을 모두 고른 것은 어느 것인가요?","options":[{"t":"언제·어디에서가 빠졌다","correct":true},{"t":"느낌이 빠졌다","mis":"K1-2-u3-X07"},{"t":"아무것도 빠지지 않았다","mis":"K1-2-u3-X07"}],"explanation":["「그네를 탔어요」에는 언제·어디에서가 없어요.","「재미있었어요」는 느낌이에요.","네 칸을 하나씩 대어 봐요."],"asset":{"type":"passage","lines":["그네를 탔어요.","재미있었어요."],"title":"준서의 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_basic#8','kor',1,2,'u3','L04','g1_2_kor_u3_L04_basic','lesson_basic','K1-2-u3-C3',2,'mc','auto','발표한 뒤 스스로 확인할 것으로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u3-X08']::text[],true,'{"seq":8,"concept":"K1-2-u3-C3","difficulty":2,"kind":"mc","stem":"발표한 뒤 스스로 확인할 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"네 칸이 다 들어갔는지","correct":true},{"t":"누가 제일 잘했는지","mis":"K1-2-u3-X08"},{"t":"누가 가장 길게 말했는지","mis":"K1-2-u3-X08"}],"explanation":["내 발표를 되돌아보는 거예요.","잘한 사람을 가리는 시간이 아니에요.","네 칸과 자세를 되짚어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 발표한 뒤 스스로 확인할 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"듣는 사람을 바라보며 말했는지","correct":true},{"t":"친구보다 큰 소리였는지","mis":"K1-2-u3-X08"},{"t":"박수를 몇 번 받았는지","mis":"K1-2-u3-X08"}],"explanation":["내 자세를 되돌아봐요.","남과 견주는 것이 아니에요.","내 발표만 되짚어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_basic#9','kor',1,2,'u3','L04','g1_2_kor_u3_L04_basic','lesson_basic','K1-2-u3-C3',2,'ox','auto','경험한 일은 「언제」부터 말하면 듣는 사람이 알아듣기 쉬워요.',ARRAY['K1-2-u3-X07']::text[],false,'{"seq":9,"concept":"K1-2-u3-C3","difficulty":2,"kind":"ox","stem":"경험한 일은 「언제」부터 말하면 듣는 사람이 알아듣기 쉬워요.","answer":"O","reason_options":[{"t":"언제 있었던 일인지 알면 그다음 일이 머릿속에 차례로 그려지니까","correct":true},{"t":"「언제」만 말하면 발표가 끝나니까","mis":"K1-2-u3-X07"}],"mis":"K1-2-u3-X07","explanation":["언제부터 말하면 듣기 좋아요.","그다음 어디에서·무엇을·느낌을 이어요.","첫마디를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_basic#10','kor',1,2,'u3','L04','g1_2_kor_u3_L04_basic','lesson_basic','K1-2-u3-C3',3,'error','auto','발표에 넣으면 좋은 것을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_challenge#1','kor',1,2,'u3','L04','g1_2_kor_u3_L04_challenge','lesson_challenge','K1-2-u3-C3',2,'mc','auto','단비의 발표에서 「어디에서」에 해당하는 말은 어느 것인가요?',ARRAY['K1-2-u3-X07']::text[],false,'{"seq":1,"concept":"K1-2-u3-C3","difficulty":2,"kind":"mc","stem":"단비의 발표에서 「어디에서」에 해당하는 말은 어느 것인가요?","options":[{"t":"신발장 앞에서","correct":true},{"t":"오늘 아침에","mis":"K1-2-u3-X07"},{"t":"마음이 놓였어요","mis":"K1-2-u3-X07"}],"explanation":["「신발장 앞에서」가 장소예요.","「오늘 아침에」는 언제, 「마음이 놓였어요」는 느낌이에요.","물음을 하나씩 대어 봐요."],"asset":{"type":"passage","lines":["오늘 아침에 신발장 앞에서 실내화 한 짝을 잃어버렸어요.","친구 은채가 함께 찾아 주었어요.","우산꽂이 옆에서 찾았을 때 마음이 놓였어요."],"title":"단비의 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_challenge#2','kor',1,2,'u3','L04','g1_2_kor_u3_L04_challenge','lesson_challenge','K1-2-u3-C3',2,'mc','auto','네 칸을 한 문장으로 바르게 이은 것은 어느 것인가요?
(언제: 어제 낮 · 어디에서: 교실에서 · 무엇을: 화분에 물을 주었다 · 느낌: 뿌듯했다)',ARRAY['K1-2-u3-X07']::text[],false,'{"seq":2,"concept":"K1-2-u3-C3","difficulty":2,"kind":"mc","stem":"네 칸을 한 문장으로 바르게 이은 것은 어느 것인가요?\n(언제: 어제 낮 · 어디에서: 교실에서 · 무엇을: 화분에 물을 주었다 · 느낌: 뿌듯했다)","options":[{"t":"어제 낮에 교실에서 화분에 물을 주어서 뿌듯했다.","correct":true},{"t":"화분에 물을 주었다. 뿌듯했다.","mis":"K1-2-u3-X07"},{"t":"어제 낮에 교실에 있었다.","mis":"K1-2-u3-X07"}],"explanation":["네 칸이 한 문장에 다 들어 있어요.","언제·어디에서가 빠지거나 무엇을·느낌이 빠지면 안 돼요.","네 칸을 「~에서 ~해서 ~했다」로 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_challenge#3','kor',1,2,'u3','L04','g1_2_kor_u3_L04_challenge','lesson_challenge','K1-2-u3-C3',3,'error','auto','발표를 시작하는 첫마디를 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_challenge#4','kor',1,2,'u3','L04','g1_2_kor_u3_L04_challenge','lesson_challenge','K1-2-u3-C3',3,'mc','auto','하율이의 발표가 듣기 좋았던 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u3-X07','K1-2-u3-X08']::text[],false,'{"seq":4,"concept":"K1-2-u3-C3","difficulty":3,"kind":"mc","stem":"하율이의 발표가 듣기 좋았던 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"있었던 일과 그때 느낌이 함께 들어 있어서","correct":true},{"t":"다람쥐 이름을 지어 주어서","mis":"K1-2-u3-X07"},{"t":"가장 길게 말해서","mis":"K1-2-u3-X08"}],"explanation":["일(다람쥐를 봄)과 느낌(놀람)이 함께 있어요.","이름이나 길이와는 상관없어요.","네 칸을 대어 봐요."],"asset":{"type":"passage","lines":["지난주 금요일에 우리 반은 뒷산에 올라갔어요.","다람쥐가 도토리를 물고 지나갔어요.","우리는 숨을 죽이고 지켜보았어요.","다람쥐가 너무 가까이 와서 놀랐어요."],"title":"하율의 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_challenge#5','kor',1,2,'u3','L04','g1_2_kor_u3_L04_challenge','lesson_challenge','K1-2-u3-C3',3,'ox','auto','발표한 뒤에는 누가 제일 잘했는지 가려야 해요.',ARRAY['K1-2-u3-X08']::text[],false,'{"seq":5,"concept":"K1-2-u3-C3","difficulty":3,"kind":"ox","stem":"발표한 뒤에는 누가 제일 잘했는지 가려야 해요.","answer":"X","reason_options":[{"t":"발표 뒤 확인은 내 발표를 되돌아보는 것이지 겨루기가 아니니까","correct":true},{"t":"그래야 다음에 더 잘하니까","mis":"K1-2-u3-X08"}],"mis":"K1-2-u3-X08","explanation":["남과 견주는 것이 아니라 내 발표를 되짚어요.","네 칸이 들어갔는지, 자세가 바른지만 봐요.","되돌아보기의 뜻을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_challenge#6','kor',1,2,'u3','L04','g1_2_kor_u3_L04_challenge','lesson_challenge','K1-2-u3-C3',3,'mc','auto','준서의 발표를 자세하게 고치려면 무엇을 보태야 할까요?',ARRAY['K1-2-u3-X07']::text[],false,'{"seq":6,"concept":"K1-2-u3-C3","difficulty":3,"kind":"mc","stem":"준서의 발표를 자세하게 고치려면 무엇을 보태야 할까요?","options":[{"t":"언제 어디에서 누구와 탔는지","correct":true},{"t":"그네의 색깔과 값","mis":"K1-2-u3-X07"},{"t":"재미있었다는 말을 세 번 더","mis":"K1-2-u3-X07"}],"explanation":["언제·어디에서·누구와를 보태면 장면이 보여요.","값이나 같은 말 되풀이는 자세한 것이 아니에요.","빠진 칸을 채워요."],"asset":{"type":"passage","lines":["그네를 탔어요.","재미있었어요."],"title":"준서의 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_challenge#7','kor',1,2,'u3','L04','g1_2_kor_u3_L04_challenge','lesson_challenge','K1-2-u3-C3',3,'match','auto','발표의 부분과 거기에서 할 일을 선으로 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"K1-2-u3-C3","difficulty":3,"kind":"match","stem":"발표의 부분과 거기에서 할 일을 선으로 이어 보세요.","pairs":[{"l":"첫마디","r":"언제 있었던 일인지 말한다"},{"l":"가운데","r":"어디에서 무엇을 했는지 말한다"},{"l":"끝","r":"그때 느낌을 말한다"}],"mis":"K1-2-u3-X07","explanation":["첫마디는 언제, 가운데는 어디에서 무엇을이에요.","끝에는 느낌을 말해요.","시우의 발표 차례를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_challenge#8','kor',1,2,'u3','L04','g1_2_kor_u3_L04_challenge','lesson_challenge','K1-2-u3-C3',4,'sa','auto','시우의 발표에서 「느낌」을 나타내는 낱말을 찾아 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"K1-2-u3-C3","difficulty":4,"kind":"sa","stem":"시우의 발표에서 「느낌」을 나타내는 낱말을 찾아 쓰세요.","answer":["기뻤어요","기뻤다","기쁘다","기쁨","기뻐요"],"explanation":["마지막 줄 「기뻤어요」가 느낌이에요.","「탔어요」·「쳤어요」는 한 일이에요.","마음을 나타내는 말을 찾아요."],"asset":{"type":"passage","lines":["어제 저녁에 집 앞 놀이터에서 동생과 그네를 탔어요.","동생이 처음으로 혼자 그네를 탔어요.","나는 손뼉을 쳤어요.","동생이 자랑스러워서 기뻤어요."],"title":"시우의 발표"},"variant_rule":{"alt":[{"stem":"단비의 발표에서 「느낌」을 나타내는 말을 찾아 쓰세요.","answer":["마음이 놓였어요","마음이 놓였다","놓였어요","놓였다","안심"],"explanation":["「마음이 놓였어요」가 느낌이에요.","「잃어버렸어요」·「찾았을 때」는 한 일이에요.","마음을 나타내는 말을 찾아요."],"asset":{"type":"passage","lines":["오늘 아침에 신발장 앞에서 실내화 한 짝을 잃어버렸어요.","친구 은채가 함께 찾아 주었어요.","우산꽂이 옆에서 찾았을 때 마음이 놓였어요."],"title":"단비의 발표"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_challenge#9','kor',1,2,'u3','L04','g1_2_kor_u3_L04_challenge','lesson_challenge','K1-2-u3-C3',4,'essay','teacher','준서의 발표 「그네를 탔어요. 재미있었어요.」를 언제·어디에서·누구와가 들어가게 한 문장으로 고쳐 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u3-C3","difficulty":4,"kind":"essay","stem":"준서의 발표 「그네를 탔어요. 재미있었어요.」를 언제·어디에서·누구와가 들어가게 한 문장으로 고쳐 쓰세요.","answer_guide":{"answer":"예: 어제 저녁에 집 앞 놀이터에서 동생과 그네를 타서 재미있었어요. — 언제·어디에서·누구와 가운데 둘 이상이 더해졌으면 맞아요.","scoring_points":["언제가 들어갔는가","어디에서가 들어갔는가","한 문장으로 이었는가"]},"explanation":["빠진 칸을 채워 한 문장으로 이어요.","언제·어디에서·누구와는 아이가 정해도 돼요.","「재미있었어요」는 그대로 느낌이에요."],"asset":{"type":"passage","lines":["그네를 탔어요.","재미있었어요."],"title":"준서의 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_challenge#10','kor',1,2,'u3','L04','g1_2_kor_u3_L04_challenge','lesson_challenge','K1-2-u3-C3',4,'essay','teacher','이번 주에 있었던 일 하나를 네 칸(언제·어디에서·무엇을·느낌)이 들어가게 두 문장으로 쓰세요. 특별한 일이 아니어도 돼요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u3-C3","difficulty":4,"kind":"essay","stem":"이번 주에 있었던 일 하나를 네 칸(언제·어디에서·무엇을·느낌)이 들어가게 두 문장으로 쓰세요. 특별한 일이 아니어도 돼요.","answer_guide":{"answer":"예: 어제 낮에 급식실에서 처음으로 국을 다 먹었다. 그릇이 비어서 뿌듯했다. — 네 칸이 다 들어 있으면 맞아요.","scoring_points":["언제·어디에서가 있는가","무엇을 했는지가 있는가","느낌이 까닭과 함께 있는가"]},"explanation":["가까운 때부터 떠올려요.","늘 있는 일이라도 느낌이 남았으면 돼요.","네 칸을 손가락으로 세며 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_basic#1','kor',1,2,'u3','L06','g1_2_kor_u3_L06_basic','lesson_basic','K1-2-u3-C4',1,'mc','auto','「우리 반이 함께 한 일」로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u3-X09']::text[],true,'{"seq":1,"concept":"K1-2-u3-C4","difficulty":1,"kind":"mc","stem":"「우리 반이 함께 한 일」로 알맞은 것은 어느 것인가요?","options":[{"t":"다 같이 뒷산에 올라간 일","correct":true},{"t":"나 혼자 집에서 만화를 본 일","mis":"K1-2-u3-X09"},{"t":"동생과 집에서 그네를 탄 일","mis":"K1-2-u3-X09"}],"explanation":["우리 반이 다 같이 한 일이에요.","혼자 집에서 한 일은 우리 반이 함께 한 일이 아니에요.","「우리 반」이 들어가는지 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 「우리 반이 함께 한 일」로 알맞은 것은 어느 것인가요?","options":[{"t":"운동회 때 다 같이 달리기를 한 일","correct":true},{"t":"엄마와 시장에 간 일","mis":"K1-2-u3-X09"},{"t":"혼자 숙제를 한 일","mis":"K1-2-u3-X09"}],"explanation":["우리 반이 다 같이 한 일이에요.","엄마와 간 일, 혼자 한 일은 아니에요.","「우리 반」이 함께인지 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_basic#2','kor',1,2,'u3','L06','g1_2_kor_u3_L06_basic','lesson_basic','K1-2-u3-C4',1,'mc','auto','「다람쥐가 너무 가까이 와서 깜짝」 — 이 일은 어떤 일에 넣으면 좋을까요?',ARRAY['K1-2-u3-X09']::text[],true,'{"seq":2,"concept":"K1-2-u3-C4","difficulty":1,"kind":"mc","stem":"「다람쥐가 너무 가까이 와서 깜짝」 — 이 일은 어떤 일에 넣으면 좋을까요?","options":[{"t":"놀란 일","correct":true},{"t":"속상한 일","mis":"K1-2-u3-X09"},{"t":"심심한 일","mis":"K1-2-u3-X09"}],"explanation":["생각하지 못한 일이 일어나면 놀라요.","속상하거나 심심한 일이 아니에요.","그때 마음을 떠올려요."],"asset":{"type":"scene","icon":"🐿️😮"},"variant_rule":{"alt":[{"stem":"「친구가 내 생일을 기억하고 편지를 주었다」 — 이 일은 어떤 일에 넣으면 좋을까요?","options":[{"t":"기쁜 일","correct":true},{"t":"놀란 일","mis":"K1-2-u3-X09"},{"t":"속상한 일","mis":"K1-2-u3-X09"}],"explanation":["마음이 따뜻해지면 기쁜 일이에요.","놀라거나 속상한 일이 아니에요.","그때 마음을 떠올려요."],"asset":{"type":"scene","icon":"💌😊"}},{"stem":"「아끼던 연필을 잃어버렸다」 — 이 일은 어떤 일에 넣으면 좋을까요?","options":[{"t":"속상한 일","correct":true},{"t":"기쁜 일","mis":"K1-2-u3-X09"},{"t":"놀란 일","mis":"K1-2-u3-X09"}],"explanation":["아끼던 것을 잃으면 속상해요.","기쁘거나 놀란 일이 아니에요.","그때 마음을 떠올려요."],"asset":{"type":"scene","icon":"✏️😢"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_basic#3','kor',1,2,'u3','L06','g1_2_kor_u3_L06_basic','lesson_basic','K1-2-u3-C4',1,'mc','auto','기억에 남는 일을 떠올리는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u3-X06','K1-2-u3-X09']::text[],false,'{"seq":3,"concept":"K1-2-u3-C4","difficulty":1,"kind":"mc","stem":"기억에 남는 일을 떠올리는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"기쁜 일·놀란 일·속상한 일로 갈라서 떠올린다","correct":true},{"t":"가장 비싼 일만 떠올린다","mis":"K1-2-u3-X06"},{"t":"남이 한 일만 떠올린다","mis":"K1-2-u3-X09"}],"explanation":["느낌으로 갈라 떠올리면 잘 생각나요.","값이나 남의 일은 상관없어요.","세 갈래로 나눠 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_basic#4','kor',1,2,'u3','L06','g1_2_kor_u3_L06_basic','lesson_basic','K1-2-u3-C4',1,'mc','auto','그림일기의 그림을 그릴 때 가장 마음 쓸 것은 무엇인가요?',ARRAY['K1-2-u3-X10']::text[],true,'{"seq":4,"concept":"K1-2-u3-C4","difficulty":1,"kind":"mc","stem":"그림일기의 그림을 그릴 때 가장 마음 쓸 것은 무엇인가요?","options":[{"t":"있었던 일이 보이게 그린다","correct":true},{"t":"색을 오래 예쁘게 칠한다","mis":"K1-2-u3-X10"},{"t":"친구보다 잘 그린다","mis":"K1-2-u3-X10"}],"explanation":["그림일기의 그림은 있었던 일이 보이면 돼요.","잘 그리기 겨루기가 아니에요.","미술 시간이 아니에요."],"variant_rule":{"alt":[{"stem":"그림일기의 그림에 대한 말로 알맞은 것은 어느 것인가요?","options":[{"t":"무슨 일인지 알 수 있으면 돼요","correct":true},{"t":"색칠을 꼼꼼히 해야 돼요","mis":"K1-2-u3-X10"},{"t":"제일 잘 그려야 돼요","mis":"K1-2-u3-X10"}],"explanation":["무슨 일인지 보이는 것이 먼저예요.","색칠이나 겨루기는 상관없어요.","그림의 역할을 떠올려요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_basic#5','kor',1,2,'u3','L06','g1_2_kor_u3_L06_basic','lesson_basic','K1-2-u3-C4',2,'match','auto','있었던 일과 그때 느낌을 선으로 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K1-2-u3-C4","difficulty":2,"kind":"match","stem":"있었던 일과 그때 느낌을 선으로 이어 보세요.","pairs":[{"l":"달리기에서 넘어졌다","r":"속상했다"},{"l":"잃어버린 실내화를 찾았다","r":"마음이 놓였다"},{"l":"다람쥐가 바로 앞까지 왔다","r":"깜짝 놀랐다"}],"mis":"K1-2-u3-X09","explanation":["넘어지면 속상하고, 찾으면 마음이 놓여요.","생각지 못한 일은 놀라요.","일마다 느낌이 달라요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 있었던 일과 그때 느낌을 선으로 이어 보세요.","pairs":[{"l":"처음으로 혼자 그네를 탔다","r":"뿌듯했다"},{"l":"비가 와서 소풍이 미뤄졌다","r":"아쉬웠다"},{"l":"옥수수가 내 팔보다 길었다","r":"깜짝 놀랐다"}],"explanation":["처음 해내면 뿌듯하고, 미뤄지면 아쉬워요.","생각보다 큰 것을 보면 놀라요.","일마다 느낌이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_basic#6','kor',1,2,'u3','L06','g1_2_kor_u3_L06_basic','lesson_basic','K1-2-u3-C4',2,'mc','auto','기억에 남는 일이 더 잘 드러난 문장은 어느 것인가요?',ARRAY['K1-2-u3-X07']::text[],false,'{"seq":6,"concept":"K1-2-u3-C4","difficulty":2,"kind":"mc","stem":"기억에 남는 일이 더 잘 드러난 문장은 어느 것인가요?","options":[{"t":"뒷산에서 다람쥐가 도토리를 물고 바로 앞을 지나갔다","correct":true},{"t":"뒷산에 갔다","mis":"K1-2-u3-X07"},{"t":"재미있었다","mis":"K1-2-u3-X07"}],"explanation":["어디에서 무엇이 어떻게 했는지가 들어 있어요.","「갔다」·「재미있었다」만으로는 장면이 안 보여요.","듣는 사람 머릿속에 그림이 그려지게."],"asset":{"type":"passage","lines":["지난주 금요일에 우리 반은 뒷산에 올라갔어요.","다람쥐가 도토리를 물고 지나갔어요.","우리는 숨을 죽이고 지켜보았어요.","다람쥐가 너무 가까이 와서 놀랐어요."],"title":"하율의 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_basic#7','kor',1,2,'u3','L06','g1_2_kor_u3_L06_basic','lesson_basic','K1-2-u3-C4',2,'mc','auto','하율이의 뒷산 이야기로 그림을 그린다면 어느 장면이 좋을까요?',ARRAY['K1-2-u3-X13']::text[],false,'{"seq":7,"concept":"K1-2-u3-C4","difficulty":2,"kind":"mc","stem":"하율이의 뒷산 이야기로 그림을 그린다면 어느 장면이 좋을까요?","options":[{"t":"다람쥐가 바로 앞까지 와서 모두 숨을 죽인 장면","correct":true},{"t":"산에 오르고 다람쥐를 보고 내려오는 장면 전부","mis":"K1-2-u3-X13"},{"t":"뒷산 지도 전체","mis":"K1-2-u3-X13"}],"explanation":["가장 기억에 남는 한 장면을 골라요.","여러 장면을 다 그릴 수는 없어요.","글에서 가장 놀란 자리를 찾아요."],"asset":{"type":"passage","lines":["지난주 금요일에 우리 반은 뒷산에 올라갔어요.","다람쥐가 도토리를 물고 지나갔어요.","우리는 숨을 죽이고 지켜보았어요.","다람쥐가 너무 가까이 와서 놀랐어요."],"title":"하율의 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_basic#8','kor',1,2,'u3','L06','g1_2_kor_u3_L06_basic','lesson_basic','K1-2-u3-C4',2,'mc','auto','문장에 넣으면 그 장면이 잘 보이는 것은 어느 것인가요?',ARRAY['K1-2-u3-X07']::text[],false,'{"seq":8,"concept":"K1-2-u3-C4","difficulty":2,"kind":"mc","stem":"문장에 넣으면 그 장면이 잘 보이는 것은 어느 것인가요?","options":[{"t":"어디에서 무엇을 어떻게 했는지","correct":true},{"t":"그날 몇 시에 잤는지","mis":"K1-2-u3-X07"},{"t":"내 신발 크기","mis":"K1-2-u3-X07"}],"explanation":["어디에서·무엇을·어떻게가 장면을 만들어요.","잠든 시각이나 신발 크기는 장면과 상관없어요.","머릿속에 그림이 그려지는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_basic#9','kor',1,2,'u3','L06','g1_2_kor_u3_L06_basic','lesson_basic','K1-2-u3-C4',2,'ox','auto','그림일기의 그림은 미술 시간처럼 잘 그려야 해요.',ARRAY['K1-2-u3-X10']::text[],false,'{"seq":9,"concept":"K1-2-u3-C4","difficulty":2,"kind":"ox","stem":"그림일기의 그림은 미술 시간처럼 잘 그려야 해요.","answer":"X","reason_options":[{"t":"있었던 일이 보이면 되고 잘 그리기 겨루기가 아니니까","correct":true},{"t":"그림이 예뻐야 일기가 되니까","mis":"K1-2-u3-X10"}],"mis":"K1-2-u3-X10","explanation":["그림일기의 그림은 무슨 일인지 보이면 돼요.","색칠을 오래 하지 않아도 괜찮아요.","미술 시간이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_basic#10','kor',1,2,'u3','L06','g1_2_kor_u3_L06_basic','lesson_basic','K1-2-u3-C4',3,'error','auto','「놀란 일」에 넣을 것을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_challenge#1','kor',1,2,'u3','L06','g1_2_kor_u3_L06_challenge','lesson_challenge','K1-2-u3-C4',2,'mc','auto','「운동회에서 우리 반이 이어달리기를 했다」를 떠올릴 때 느낌으로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u3-X09']::text[],false,'{"seq":1,"concept":"K1-2-u3-C4","difficulty":2,"kind":"mc","stem":"「운동회에서 우리 반이 이어달리기를 했다」를 떠올릴 때 느낌으로 알맞은 것은 어느 것인가요?","options":[{"t":"바통을 넘겨줄 때 가슴이 두근거렸다","correct":true},{"t":"바통은 빨간색이었다","mis":"K1-2-u3-X09"},{"t":"운동회는 가을에 한다","mis":"K1-2-u3-X09"}],"explanation":["「두근거렸다」가 느낌이에요.","색깔이나 때는 느낌이 아니에요.","마음을 나타내는 말을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_challenge#2','kor',1,2,'u3','L06','g1_2_kor_u3_L06_challenge','lesson_challenge','K1-2-u3-C4',2,'mc','auto','일과 느낌이 알맞게 이어진 것은 어느 것인가요?',ARRAY['K1-2-u3-X09']::text[],true,'{"seq":2,"concept":"K1-2-u3-C4","difficulty":2,"kind":"mc","stem":"일과 느낌이 알맞게 이어진 것은 어느 것인가요?","options":[{"t":"비가 와서 소풍이 미뤄져 아쉬웠다","correct":true},{"t":"비가 와서 소풍이 미뤄져 신이 났다","mis":"K1-2-u3-X09"},{"t":"비가 와서 소풍이 미뤄져 배가 불렀다","mis":"K1-2-u3-X09"}],"explanation":["기다리던 일이 미뤄지면 아쉬워요.","신이 나거나 배가 부른 것은 이 일과 맞지 않아요.","일과 느낌이 맞는지 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 일과 느낌이 알맞게 이어진 것은 어느 것인가요?","options":[{"t":"잃어버린 실내화를 찾아서 마음이 놓였다","correct":true},{"t":"잃어버린 실내화를 찾아서 속상했다","mis":"K1-2-u3-X09"},{"t":"잃어버린 실내화를 찾아서 졸렸다","mis":"K1-2-u3-X09"}],"explanation":["찾으면 마음이 놓여요.","속상하거나 졸린 것은 맞지 않아요.","일과 느낌을 맞춰요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_challenge#3','kor',1,2,'u3','L06','g1_2_kor_u3_L06_challenge','lesson_challenge','K1-2-u3-C4',3,'error','auto','그림일기의 그림에 대해 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_challenge#4','kor',1,2,'u3','L06','g1_2_kor_u3_L06_challenge','lesson_challenge','K1-2-u3-C4',3,'mc','auto','시우의 옥수수 일기에서 그림 한 장면으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u3-X13']::text[],false,'{"seq":4,"concept":"K1-2-u3-C4","difficulty":3,"kind":"mc","stem":"시우의 옥수수 일기에서 그림 한 장면으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"내 팔보다 긴 옥수수를 들고 놀란 장면","correct":true},{"t":"밭에 가는 길의 버스","mis":"K1-2-u3-X13"},{"t":"집에 와서 옥수수를 먹는 장면과 밭 장면 둘 다","mis":"K1-2-u3-X13"}],"explanation":["글이 가장 놀란 자리가 옥수수 길이예요.","가는 길이나 두 장면은 글과 맞지 않아요.","글을 읽고 가장 남는 장면을 골라요."],"asset":{"type":"diary","date":"10월 2일 금요일","weather":"☁️ 구름이 많음","picture":"🌽👵","lines":["할머니와 밭에서 옥수수를 땄다.","옥수수가 내 팔보다 길어서 깜짝 놀랐다."],"name":"시우"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_challenge#5','kor',1,2,'u3','L06','g1_2_kor_u3_L06_challenge','lesson_challenge','K1-2-u3-C4',3,'match','auto','느낌의 갈래와 거기에 넣을 일을 선으로 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"K1-2-u3-C4","difficulty":3,"kind":"match","stem":"느낌의 갈래와 거기에 넣을 일을 선으로 이어 보세요.","pairs":[{"l":"기쁜 일","r":"처음으로 양말 짝을 다 찾았다"},{"l":"놀란 일","r":"옥수수가 팔보다 길었다"},{"l":"속상한 일","r":"달리기에서 넘어졌다"}],"mis":"K1-2-u3-X09","explanation":["처음 해내면 기쁘고, 생각보다 크면 놀라요.","넘어지면 속상해요.","일마다 느낌 갈래가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_challenge#6','kor',1,2,'u3','L06','g1_2_kor_u3_L06_challenge','lesson_challenge','K1-2-u3-C4',3,'ox','auto','그림으로 그릴 장면은 그날 있었던 일 가운데 가장 기억에 남는 한 장면으로 골라요.',ARRAY['K1-2-u3-X13']::text[],false,'{"seq":6,"concept":"K1-2-u3-C4","difficulty":3,"kind":"ox","stem":"그림으로 그릴 장면은 그날 있었던 일 가운데 가장 기억에 남는 한 장면으로 골라요.","answer":"O","reason_options":[{"t":"여러 장면을 다 그릴 수 없고 한 장면이면 무슨 일인지 보이니까","correct":true},{"t":"그림은 하나만 그려도 되니 아무거나 골라도 되니까","mis":"K1-2-u3-X13"}],"mis":"K1-2-u3-X13","explanation":["가장 남는 한 장면을 골라요.","아무거나가 아니라 글과 맞는 장면이에요.","글을 먼저 읽고 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_challenge#7','kor',1,2,'u3','L06','g1_2_kor_u3_L06_challenge','lesson_challenge','K1-2-u3-C4',3,'mc','auto','준서의 일기는 그림과 글이 맞지 않아요. 무엇이 문제인가요?',ARRAY['K1-2-u3-X10','K1-2-u3-X07']::text[],false,'{"seq":7,"concept":"K1-2-u3-C4","difficulty":3,"kind":"mc","stem":"준서의 일기는 그림과 글이 맞지 않아요. 무엇이 문제인가요?","options":[{"t":"글은 급식 이야기인데 그림은 강아지라서 서로 다른 일이에요","correct":true},{"t":"강아지를 더 예쁘게 그려야 해요","mis":"K1-2-u3-X10"},{"t":"글이 두 줄이라 짧아요","mis":"K1-2-u3-X07"}],"explanation":["그림과 글은 같은 일을 담아야 해요.","그림 솜씨나 글 길이 문제가 아니에요.","글을 읽고 그림이 맞는지 봐요."],"asset":{"type":"diary","date":"10월 7일 수요일","weather":"☀️ 해가 쨍쨍","picture":"🐶🦴","lines":["급식에 내가 좋아하는 카레가 나왔다.","한 그릇을 다 먹어서 배가 든든했다."],"name":"준서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_challenge#8','kor',1,2,'u3','L06','g1_2_kor_u3_L06_challenge','lesson_challenge','K1-2-u3-C4',4,'sa','auto','「아끼던 연필을 잃어버렸다」는 어떤 느낌의 갈래에 넣으면 좋을까요? 「◯◯한 일」의 빈칸을 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"K1-2-u3-C4","difficulty":4,"kind":"sa","stem":"「아끼던 연필을 잃어버렸다」는 어떤 느낌의 갈래에 넣으면 좋을까요? 「◯◯한 일」의 빈칸을 쓰세요.","answer":["속상","속상한","속상한 일","슬픈","슬픈 일","슬픈일","속상한일"],"explanation":["아끼던 것을 잃으면 속상해요.","기쁜 일·놀란 일이 아니에요.","그때 마음을 떠올려요."],"variant_rule":{"alt":[{"stem":"「친구가 내 생일을 기억하고 편지를 주었다」는 어떤 느낌의 갈래에 넣으면 좋을까요? 「◯◯ 일」의 빈칸을 쓰세요.","answer":["기쁜","기쁜 일","기쁜일","고마운","고마운 일","행복한","행복한 일"],"explanation":["마음이 따뜻해지면 기쁜 일이에요.","놀란 일·속상한 일이 아니에요.","그때 마음을 떠올려요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_challenge#9','kor',1,2,'u3','L06','g1_2_kor_u3_L06_challenge','lesson_challenge','K1-2-u3-C4',4,'essay','teacher','1학년이 되어 우리 반이 함께 한 일 가운데 기억에 남는 일 하나를, 어디에서 무엇을 어떻게 했는지와 그때 느낌이 들어가게 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u3-C4","difficulty":4,"kind":"essay","stem":"1학년이 되어 우리 반이 함께 한 일 가운데 기억에 남는 일 하나를, 어디에서 무엇을 어떻게 했는지와 그때 느낌이 들어가게 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 운동장에서 우리 반이 이어달리기를 했다. 바통을 넘겨줄 때 가슴이 두근거렸다. — 우리 반이 함께 한 일이고 장면과 느낌이 있으면 맞아요.","scoring_points":["우리 반이 함께 한 일인가","어디에서 무엇을 어떻게가 있는가","느낌이 있는가"]},"explanation":["혼자 한 일이 아니라 우리 반이 함께 한 일이에요.","장면이 보이게, 느낌까지 써요.","느낌으로 갈라 떠올리면 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_challenge#10','kor',1,2,'u3','L06','g1_2_kor_u3_L06_challenge','lesson_challenge','K1-2-u3-C4',4,'essay','teacher','준서의 급식 일기에 맞는 그림 한 장면을 말로 설명해 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u3-C4","difficulty":4,"kind":"essay","stem":"준서의 급식 일기에 맞는 그림 한 장면을 말로 설명해 쓰세요.","answer_guide":{"answer":"예: 카레가 담긴 식판을 들고 웃는 나. — 글(급식·카레)과 맞는 한 장면이면 맞아요.","scoring_points":["글의 일(급식·카레)과 맞는가","한 장면인가","무슨 일인지 알 수 있는가"]},"explanation":["글을 먼저 읽고 그에 맞는 장면을 골라요.","강아지 그림은 글과 맞지 않았어요.","한 장면만."],"asset":{"type":"diary","date":"10월 7일 수요일","weather":"☀️ 해가 쨍쨍","picture":"🐶🦴","lines":["급식에 내가 좋아하는 카레가 나왔다.","한 그릇을 다 먹어서 배가 든든했다."],"name":"준서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L08_basic#1','kor',1,2,'u3','L08','g1_2_kor_u3_L08_basic','lesson_basic','K1-2-u3-C5',1,'mc','auto','그림일기의 맨 위에는 무엇을 쓸까요?',ARRAY['K1-2-u3-X12','K1-2-u3-X11']::text[],false,'{"seq":1,"concept":"K1-2-u3-C5","difficulty":1,"kind":"mc","stem":"그림일기의 맨 위에는 무엇을 쓸까요?","options":[{"t":"날짜와 요일, 날씨","correct":true},{"t":"내 이름과 반","mis":"K1-2-u3-X12"},{"t":"그림 제목","mis":"K1-2-u3-X11"}],"explanation":["맨 윗줄에는 날짜와 요일, 날씨를 써요.","이름·반이나 제목은 맨 윗줄에 쓰는 것이 아니에요.","하율이의 그림일기 맨 윗줄을 봐요."],"asset":{"type":"diary","date":"9월 18일 목요일","weather":"🌧️ 비가 주룩주룩","picture":"☔🐌","lines":["집에 오는 길에 담 위에서 달팽이를 보았다.","달팽이가 비를 맞고도 천천히 가서 신기했다."],"name":"하율"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L08_basic#2','kor',1,2,'u3','L08','g1_2_kor_u3_L08_basic','lesson_basic','K1-2-u3-C5',1,'mc','auto','하율이의 그림일기에서 빠진 것은 무엇인가요?',ARRAY['K1-2-u3-X11']::text[],true,'{"seq":2,"concept":"K1-2-u3-C5","difficulty":1,"kind":"mc","stem":"하율이의 그림일기에서 빠진 것은 무엇인가요?","options":[{"t":"날짜와 요일","correct":true},{"t":"날씨","mis":"K1-2-u3-X11"},{"t":"그림","mis":"K1-2-u3-X11"}],"explanation":["맨 윗줄 앞자리가 비어 있어요.","날씨와 그림은 있어요.","틀의 빈칸을 찾아요."],"asset":{"type":"diary","date":null,"weather":"🌧️ 비가 주룩주룩","picture":"☔🐌","lines":["집에 오는 길에 담 위에서 달팽이를 보았다.","달팽이가 비를 맞고도 천천히 가서 신기했다."],"name":"하율"},"variant_rule":{"alt":[{"stem":"단비의 그림일기에서 빠진 것은 무엇인가요?","options":[{"t":"날씨","correct":true},{"t":"날짜와 요일","mis":"K1-2-u3-X11"},{"t":"글","mis":"K1-2-u3-X11"}],"explanation":["맨 윗줄 뒷자리 날씨가 비어 있어요.","날짜와 글은 있어요.","틀의 빈칸을 찾아요."],"asset":{"type":"diary","date":"10월 6일 화요일","weather":null,"picture":"🧒🎈🎈","lines":["학교 운동장에서 친구와 풍선을 불었다.","내 풍선이 제일 크게 부풀어서 가슴이 두근거렸다."],"name":"단비"}},{"stem":"시우의 그림일기에서 빠진 것은 무엇인가요?","options":[{"t":"그림","correct":true},{"t":"날씨","mis":"K1-2-u3-X11"},{"t":"글","mis":"K1-2-u3-X11"}],"explanation":["그림 칸이 비어 있어요.","날씨와 글은 있어요.","틀의 빈칸을 찾아요."],"asset":{"type":"diary","date":"10월 2일 금요일","weather":"☁️ 구름이 많음","picture":null,"lines":["할머니와 밭에서 옥수수를 땄다.","옥수수가 내 팔보다 길어서 깜짝 놀랐다."],"name":"시우"}},{"stem":"은채의 그림일기에서 빠진 것은 무엇인가요?","options":[{"t":"글","correct":true},{"t":"날짜와 요일","mis":"K1-2-u3-X11"},{"t":"그림","mis":"K1-2-u3-X11"}],"explanation":["글 칸이 비어 있어요.","날짜와 그림은 있어요.","틀의 빈칸을 찾아요."],"asset":{"type":"diary","date":"9월 25일 목요일","weather":"☀️ 바람이 시원함","picture":"🧦🧺","lines":null,"name":"은채"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L08_basic#3','kor',1,2,'u3','L08','g1_2_kor_u3_L08_basic','lesson_basic','K1-2-u3-C5',1,'mc','auto','그림일기는 세 부분으로 되어 있어요. 아닌 것은 어느 것인가요?',ARRAY['K1-2-u3-X11']::text[],false,'{"seq":3,"concept":"K1-2-u3-C5","difficulty":1,"kind":"mc","stem":"그림일기는 세 부분으로 되어 있어요. 아닌 것은 어느 것인가요?","options":[{"t":"준비물 칸","correct":true},{"t":"맨 윗줄","mis":"K1-2-u3-X11"},{"t":"그림 칸","mis":"K1-2-u3-X11"}],"explanation":["맨 윗줄·그림·글 세 부분이에요.","준비물 칸은 없어요.","틀을 위에서부터 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L08_basic#4','kor',1,2,'u3','L08','g1_2_kor_u3_L08_basic','lesson_basic','K1-2-u3-C5',1,'mc','auto','그림일기에 쓸 일로 더 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u3-X14']::text[],false,'{"seq":4,"concept":"K1-2-u3-C5","difficulty":1,"kind":"mc","stem":"그림일기에 쓸 일로 더 알맞은 것은 어느 것인가요?","options":[{"t":"비 오는 담 위에서 달팽이를 본 일","correct":true},{"t":"날마다 똑같이 세수한 일","mis":"K1-2-u3-X14"},{"t":"날마다 똑같이 신발을 신은 일","mis":"K1-2-u3-X14"}],"explanation":["그날 새롭게 느낀 일이 좋아요.","날마다 똑같이 하는 일은 나중에 읽어도 그날이 떠오르지 않아요.","그날만의 일을 찾아요."],"asset":{"type":"diary","date":"9월 18일 목요일","weather":"🌧️ 비가 주룩주룩","picture":"☔🐌","lines":["집에 오는 길에 담 위에서 달팽이를 보았다.","달팽이가 비를 맞고도 천천히 가서 신기했다."],"name":"하율"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L08_basic#5','kor',1,2,'u3','L08','g1_2_kor_u3_L08_basic','lesson_basic','K1-2-u3-C5',2,'match','auto','그림일기의 부분과 들어갈 내용을 선으로 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K1-2-u3-C5","difficulty":2,"kind":"match","stem":"그림일기의 부분과 들어갈 내용을 선으로 이어 보세요.","pairs":[{"l":"맨 윗줄","r":"10월 6일 화요일 · 해가 쨍쨍"},{"l":"그림 칸","r":"풍선을 부는 나"},{"l":"글 칸","r":"풍선이 커져서 두근거렸다"}],"mis":"K1-2-u3-X11","explanation":["맨 윗줄은 날짜·요일·날씨예요.","그림 칸은 한 장면, 글 칸은 일과 느낌이에요.","단비의 그림일기를 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 그림일기의 부분과 들어갈 내용을 선으로 이어 보세요.","pairs":[{"l":"맨 윗줄","r":"9월 18일 목요일 · 비가 주룩주룩"},{"l":"그림 칸","r":"담 위의 달팽이"},{"l":"글 칸","r":"달팽이가 천천히 가서 신기했다"}],"explanation":["맨 윗줄은 날짜·요일·날씨예요.","그림 칸은 한 장면, 글 칸은 일과 느낌이에요.","하율이의 그림일기를 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L08_basic#6','kor',1,2,'u3','L08','g1_2_kor_u3_L08_basic','lesson_basic','K1-2-u3-C5',2,'mc','auto','시우의 이 일기에서 잘못된 점은 무엇인가요?',ARRAY['K1-2-u3-X11','K1-2-u3-X10']::text[],false,'{"seq":6,"concept":"K1-2-u3-C5","difficulty":2,"kind":"mc","stem":"시우의 이 일기에서 잘못된 점은 무엇인가요?","options":[{"t":"준비물과 선생님 성함은 안내문에 들어갈 것인데 일기에 썼다","correct":true},{"t":"날씨를 썼다","mis":"K1-2-u3-X11"},{"t":"그림이 있다","mis":"K1-2-u3-X10"}],"explanation":["일기에는 내가 겪은 일과 느낌을 써요.","준비물·선생님 성함은 안내문 것이에요.","겪은 일인지 알려 주는 글인지 가려요."],"asset":{"type":"diary","date":"10월 10일 토요일","weather":"☀️ 맑음","picture":"✂️📄","lines":["준비물: 색종이, 풀, 가위","담임 선생님: 김○○"],"name":"시우"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L08_basic#7','kor',1,2,'u3','L08','g1_2_kor_u3_L08_basic','lesson_basic','K1-2-u3-C5',2,'mc','auto','날씨를 더 잘 나타낸 것은 어느 것인가요?',ARRAY['K1-2-u3-X11']::text[],true,'{"seq":7,"concept":"K1-2-u3-C5","difficulty":2,"kind":"mc","stem":"날씨를 더 잘 나타낸 것은 어느 것인가요?","options":[{"t":"☀️ 해가 쨍쨍 나서 눈이 부셨다","correct":true},{"t":"☀️ 맑음","mis":"K1-2-u3-X11"},{"t":"날씨 없음","mis":"K1-2-u3-X11"}],"explanation":["날씨도 그날 느낌이 드러나게 쓰면 좋아요.","「맑음」만 써도 되지만 느낌이 있으면 더 좋고, 안 쓰면 안 돼요.","그날 하늘을 떠올려요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 날씨를 더 잘 나타낸 것은 어느 것인가요?","options":[{"t":"🌧️ 비가 주룩주룩 와서 우산을 썼다","correct":true},{"t":"🌧️ 비","mis":"K1-2-u3-X11"},{"t":"날씨 없음","mis":"K1-2-u3-X11"}],"explanation":["그날 느낌이 드러나게 써요.","「비」만보다 더 좋고, 안 쓰면 안 돼요.","그날 하늘을 떠올려요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
