INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L08_basic#9','kor',1,2,'u3','L08','g1_2_kor_u3_L08_basic','lesson_basic','K1-2-u3-C5',2,'ox','auto','그림일기에는 그날 새롭게 느낀 일을 쓰는 것이 좋아요.',ARRAY['K1-2-u3-X14']::text[],false,'{"seq":9,"concept":"K1-2-u3-C5","difficulty":2,"kind":"ox","stem":"그림일기에는 그날 새롭게 느낀 일을 쓰는 것이 좋아요.","answer":"O","reason_options":[{"t":"날마다 똑같은 일은 나중에 읽어도 그날이 떠오르지 않으니까","correct":true},{"t":"새로운 일이어야 선생님이 좋아하니까","mis":"K1-2-u3-X14"}],"mis":"K1-2-u3-X14","explanation":["그날만의 일이 오래 남아요.","늘 하는 일은 그날이 떠오르지 않아요.","누구 보라고가 아니라 나를 위해 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L08_basic#10','kor',1,2,'u3','L08','g1_2_kor_u3_L08_basic','lesson_basic','K1-2-u3-C5',3,'error','auto','그림일기 글에 쓰면 좋은 것을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L08_challenge#1','kor',1,2,'u3','L08','g1_2_kor_u3_L08_challenge','lesson_challenge','K1-2-u3-C5',2,'mc','auto','단비의 그림일기에서 「날씨」가 들어갈 자리는 어디인가요?',ARRAY['K1-2-u3-X11']::text[],false,'{"seq":1,"concept":"K1-2-u3-C5","difficulty":2,"kind":"mc","stem":"단비의 그림일기에서 「날씨」가 들어갈 자리는 어디인가요?","options":[{"t":"맨 윗줄, 날짜와 요일 옆","correct":true},{"t":"글 칸 맨 끝","mis":"K1-2-u3-X11"},{"t":"그림 칸 안","mis":"K1-2-u3-X11"}],"explanation":["날씨는 맨 윗줄에 써요.","글 끝이나 그림 안이 아니에요.","비어 있는 자리를 봐요."],"asset":{"type":"diary","date":"10월 6일 화요일","weather":null,"picture":"🧒🎈🎈","lines":["학교 운동장에서 친구와 풍선을 불었다.","내 풍선이 제일 크게 부풀어서 가슴이 두근거렸다."],"name":"단비"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L08_challenge#2','kor',1,2,'u3','L08','g1_2_kor_u3_L08_challenge','lesson_challenge','K1-2-u3-C5',2,'mc','auto','이 일기에서 「날씨: 바람이 불었다」는 어디로 옮겨 써야 할까요?',ARRAY['K1-2-u3-X11']::text[],false,'{"seq":2,"concept":"K1-2-u3-C5","difficulty":2,"kind":"mc","stem":"이 일기에서 「날씨: 바람이 불었다」는 어디로 옮겨 써야 할까요?","options":[{"t":"맨 윗줄 날짜·요일 옆으로","correct":true},{"t":"그림 칸으로","mis":"K1-2-u3-X11"},{"t":"그대로 두어도 돼요","mis":"K1-2-u3-X11"}],"explanation":["날씨는 맨 윗줄에 써요.","글 끝에 있으면 자리가 틀린 거예요.","틀의 빈자리를 봐요."],"asset":{"type":"diary","date":"10월 13일 월요일","weather":null,"picture":"🍂🧒","lines":["놀이터에서 낙엽을 모아 던졌다.","낙엽이 눈처럼 내려서 웃음이 났다.","날씨: 바람이 불었다."],"name":"단비"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L08_challenge#3','kor',1,2,'u3','L08','g1_2_kor_u3_L08_challenge','lesson_challenge','K1-2-u3-C5',3,'error','auto','그림일기와 안내문을 가르려고 해요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L08_challenge#4','kor',1,2,'u3','L08','g1_2_kor_u3_L08_challenge','lesson_challenge','K1-2-u3-C5',3,'mc','auto','준서의 일기가 그날을 떠올리기 어려운 까닭은 무엇인가요?',ARRAY['K1-2-u3-X07','K1-2-u3-X10']::text[],false,'{"seq":4,"concept":"K1-2-u3-C5","difficulty":3,"kind":"mc","stem":"준서의 일기가 그날을 떠올리기 어려운 까닭은 무엇인가요?","options":[{"t":"날마다 똑같이 하는 일만 차례로 늘어놓아서","correct":true},{"t":"글이 세 줄이라 길어서","mis":"K1-2-u3-X07"},{"t":"그림이 세 개라서","mis":"K1-2-u3-X10"}],"explanation":["일어나고 밥 먹고 학교 가는 것은 날마다 같아요.","줄 수나 그림 수 문제가 아니에요.","그날 새롭게 느낀 일이 없어요."],"asset":{"type":"diary","date":"10월 8일 목요일","weather":"☁️ 구름이 많음","picture":"🛏️🍚🏫","lines":["아침에 일어났다. 밥을 먹었다.","학교에 갔다. 집에 왔다.","저녁을 먹고 잤다."],"name":"준서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L08_challenge#5','kor',1,2,'u3','L08','g1_2_kor_u3_L08_challenge','lesson_challenge','K1-2-u3-C5',3,'mc','auto','하율이의 일기에서 고치면 좋을 점은 무엇인가요?',ARRAY['K1-2-u3-X07','K1-2-u3-X11']::text[],false,'{"seq":5,"concept":"K1-2-u3-C5","difficulty":3,"kind":"mc","stem":"하율이의 일기에서 고치면 좋을 점은 무엇인가요?","options":[{"t":"「재미있었다」만 있고 무엇이 왜 재미있었는지가 없다","correct":true},{"t":"달리기를 했다는 말을 빼야 한다","mis":"K1-2-u3-X07"},{"t":"날씨를 지워야 한다","mis":"K1-2-u3-X11"}],"explanation":["느낌에는 까닭이 있어야 그날이 되살아나요.","한 일과 날씨는 그대로 두어요.","「왜냐하면」을 붙여 봐요."],"asset":{"type":"diary","date":"10월 9일 금요일","weather":"☀️ 해가 쨍쨍","picture":"🏃🏅","lines":["체육 시간에 달리기를 했다.","재미있었다."],"name":"하율"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L08_challenge#6','kor',1,2,'u3','L08','g1_2_kor_u3_L08_challenge','lesson_challenge','K1-2-u3-C5',3,'match','auto','글과 그 글이 어디에 들어가는지 선으로 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"K1-2-u3-C5","difficulty":3,"kind":"match","stem":"글과 그 글이 어디에 들어가는지 선으로 이어 보세요.","pairs":[{"l":"비 오는 길에 달팽이를 봐서 신기했다","r":"그림일기"},{"l":"준비물: 색종이, 풀","r":"안내문"},{"l":"9월 18일 목요일 · 비가 주룩주룩","r":"그림일기 맨 윗줄"}],"mis":"K1-2-u3-X12","explanation":["겪은 일과 느낌은 그림일기예요.","준비물은 안내문, 날짜·요일·날씨는 맨 윗줄이에요.","글의 성격을 가려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L08_challenge#7','kor',1,2,'u3','L08','g1_2_kor_u3_L08_challenge','lesson_challenge','K1-2-u3-C5',3,'ox','auto','날씨는 「맑음」처럼 한 낱말로만 써야 해요.',ARRAY['K1-2-u3-X11']::text[],false,'{"seq":7,"concept":"K1-2-u3-C5","difficulty":3,"kind":"ox","stem":"날씨는 「맑음」처럼 한 낱말로만 써야 해요.","answer":"X","reason_options":[{"t":"날씨도 그날 느낌이 드러나게 길게 써도 되니까","correct":true},{"t":"날씨는 꼭 한 글자여야 하니까","mis":"K1-2-u3-X11"}],"mis":"K1-2-u3-X11","explanation":["「해가 쨍쨍 나서 눈이 부셨다」처럼 써도 좋아요.","한 낱말로 써도 되지만 꼭 그래야 하는 것은 아니에요.","그날 하늘을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L08_challenge#8','kor',1,2,'u3','L08','g1_2_kor_u3_L08_challenge','lesson_challenge','K1-2-u3-C5',4,'sa','auto','이 그림일기 맨 윗줄에 빠진 것 하나를 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"K1-2-u3-C5","difficulty":4,"kind":"sa","stem":"이 그림일기 맨 윗줄에 빠진 것 하나를 쓰세요.","answer":["날씨"],"explanation":["날짜와 요일은 있는데 날씨가 없어요.","맨 윗줄은 날짜·요일·날씨예요.","빈칸 자리를 봐요."],"asset":{"type":"diary","date":"10월 6일 화요일","weather":null,"picture":"🧒🎈🎈","lines":["학교 운동장에서 친구와 풍선을 불었다.","내 풍선이 제일 크게 부풀어서 가슴이 두근거렸다."],"name":"단비"},"variant_rule":{"alt":[{"stem":"이 그림일기 맨 윗줄에 빠진 것을 쓰세요.","answer":["날짜와 요일","날짜","날짜 요일","날짜, 요일","날짜·요일","요일"],"explanation":["날씨는 있는데 날짜와 요일이 없어요.","맨 윗줄은 날짜·요일·날씨예요.","빈칸 자리를 봐요."],"asset":{"type":"diary","date":null,"weather":"🌧️ 비가 주룩주룩","picture":"☔🐌","lines":["집에 오는 길에 담 위에서 달팽이를 보았다.","달팽이가 비를 맞고도 천천히 가서 신기했다."],"name":"하율"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L08_challenge#9','kor',1,2,'u3','L08','g1_2_kor_u3_L08_challenge','lesson_challenge','K1-2-u3-C5',4,'essay','teacher','시우의 일기에는 안내문 것이 들어 있어요. 어떤 글을 빼고 무엇을 넣어야 그림일기가 되는지 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u3-C5","difficulty":4,"kind":"essay","stem":"시우의 일기에는 안내문 것이 들어 있어요. 어떤 글을 빼고 무엇을 넣어야 그림일기가 되는지 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 준비물과 선생님 성함을 뺀다. 그 자리에 내가 겪은 일과 그때 느낌을 쓴다. — 뺄 것과 넣을 것이 맞으면 돼요.","scoring_points":["준비물·선생님 성함을 뺀다고 했는가","겪은 일과 느낌을 넣는다고 했는가","두 문장으로 썼는가"]},"explanation":["안내문 것은 빼요.","내가 겪은 일과 느낌을 넣어요.","그림일기와 안내문을 가려요."],"asset":{"type":"diary","date":"10월 10일 토요일","weather":"☀️ 맑음","picture":"✂️📄","lines":["준비물: 색종이, 풀, 가위","담임 선생님: 김○○"],"name":"시우"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L08_challenge#10','kor',1,2,'u3','L08','g1_2_kor_u3_L08_challenge','lesson_challenge','K1-2-u3-C5',4,'essay','teacher','하율이의 일기 「재미있었다.」를 무엇이 왜 재미있었는지가 드러나게 한 문장으로 고쳐 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u3-C5","difficulty":4,"kind":"essay","stem":"하율이의 일기 「재미있었다.」를 무엇이 왜 재미있었는지가 드러나게 한 문장으로 고쳐 쓰세요.","answer_guide":{"answer":"예: 처음으로 반 친구들을 앞질러서 바람을 가르는 것 같아 재미있었다. — 무엇이·왜가 들어 있으면 맞아요.","scoring_points":["무엇이 재미있었는지가 있는가","왜 그렇게 느꼈는지가 있는가","한 문장인가"]},"explanation":["느낌에 까닭을 붙여요.","「왜냐하면」을 붙여 말해 봐요.","달리기 장면을 떠올려요."],"asset":{"type":"diary","date":"10월 9일 금요일","weather":"☀️ 해가 쨍쨍","picture":"🏃🏅","lines":["체육 시간에 달리기를 했다.","재미있었다."],"name":"하율"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L10_basic#1','kor',1,2,'u3','L10','g1_2_kor_u3_L10_basic','lesson_basic','K1-2-u3-C6',1,'mc','auto','그림일기에 쓸 일을 고를 때 하루를 어떻게 갈라 떠올리면 좋을까요?',ARRAY['K1-2-u3-X14']::text[],true,'{"seq":1,"concept":"K1-2-u3-C6","difficulty":1,"kind":"mc","stem":"그림일기에 쓸 일을 고를 때 하루를 어떻게 갈라 떠올리면 좋을까요?","options":[{"t":"아침 · 낮 · 저녁","correct":true},{"t":"월요일 · 화요일 · 수요일","mis":"K1-2-u3-X14"},{"t":"집 · 학교 · 가게","mis":"K1-2-u3-X14"}],"explanation":["하루를 아침·낮·저녁으로 갈라 떠올려요.","요일이나 장소로 가르는 것이 아니에요.","어제 하루를 세 토막으로."],"variant_rule":{"alt":[{"stem":"어제 하루를 되돌려 글감을 찾을 때 알맞은 방법은 어느 것인가요?","options":[{"t":"아침·낮·저녁으로 갈라 그때 마음이 움직인 일을 찾는다","correct":true},{"t":"가장 오래 한 일을 고른다","mis":"K1-2-u3-X14"},{"t":"친구가 쓴 것과 같은 일을 고른다","mis":"K1-2-u3-X14"}],"explanation":["하루를 세 토막으로 갈라 마음이 움직인 일을 찾아요.","오래 한 일이나 친구와 같은 일은 글감 고르는 법이 아니에요.","마음이 움직인 일."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L10_basic#2','kor',1,2,'u3','L10','g1_2_kor_u3_L10_basic','lesson_basic','K1-2-u3-C6',1,'mc','auto','그림일기를 쓰는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u3-X16','K1-2-u3-X14']::text[],false,'{"seq":2,"concept":"K1-2-u3-C6","difficulty":1,"kind":"mc","stem":"그림일기를 쓰는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"글감 고르기 → 맨 윗줄 쓰기 → 그림 그리기 → 글 쓰기 → 다시 읽기","correct":true},{"t":"그림 색칠하기 → 글감 고르기","mis":"K1-2-u3-X16"},{"t":"글 쓰기 → 글감 고르기","mis":"K1-2-u3-X14"}],"explanation":["글감을 고르고 맨 윗줄, 그림, 글 차례로 써요.","글감을 고르기 전에 색칠하거나 글을 쓸 수는 없어요.","차례를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L10_basic#3','kor',1,2,'u3','L10','g1_2_kor_u3_L10_basic','lesson_basic','K1-2-u3-C6',1,'mc','auto','맨 윗줄을 바르게 쓴 것은 어느 것인가요?',ARRAY['K1-2-u3-X12','K1-2-u3-X11']::text[],true,'{"seq":3,"concept":"K1-2-u3-C6","difficulty":1,"kind":"mc","stem":"맨 윗줄을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"10월 2일 금요일 · 구름이 많음","correct":true},{"t":"시우 · 10월 2일","mis":"K1-2-u3-X12"},{"t":"10월 2일 · 옥수수","mis":"K1-2-u3-X11"}],"explanation":["날짜와 요일 다음에 날씨까지 써요.","이름이나 글감은 맨 윗줄에 쓰지 않아요.","날짜·요일·날씨 차례예요."],"asset":{"type":"diary","date":"10월 2일 금요일","weather":"☁️ 구름이 많음","picture":"🌽👵","lines":["할머니와 밭에서 옥수수를 땄다.","옥수수가 내 팔보다 길어서 깜짝 놀랐다."],"name":"시우"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 맨 윗줄을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"9월 25일 목요일 · 바람이 시원함","correct":true},{"t":"9월 25일 · 양말","mis":"K1-2-u3-X11"},{"t":"은채 · 목요일","mis":"K1-2-u3-X12"}],"explanation":["날짜·요일·날씨를 차례로 써요.","글감이나 이름은 맨 윗줄에 안 써요.","은채의 일기를 봐요."],"asset":{"type":"diary","date":"9월 25일 목요일","weather":"☀️ 바람이 시원함","picture":"🧦🧺","lines":["저녁에 빨래 개기를 처음 도왔다.","양말 짝을 다 찾았을 때 어깨가 으쓱했다."],"name":"은채"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L10_basic#4','kor',1,2,'u3','L10','g1_2_kor_u3_L10_basic','lesson_basic','K1-2-u3-C6',1,'mc','auto','그림일기의 글에 꼭 들어가야 하는 것은 무엇인가요?',ARRAY['K1-2-u3-X12','K1-2-u3-X07']::text[],false,'{"seq":4,"concept":"K1-2-u3-C6","difficulty":1,"kind":"mc","stem":"그림일기의 글에 꼭 들어가야 하는 것은 무엇인가요?","options":[{"t":"있었던 일과 그때 느낌","correct":true},{"t":"준비물","mis":"K1-2-u3-X12"},{"t":"친구 이름 전부","mis":"K1-2-u3-X07"}],"explanation":["글에는 있었던 일과 느낌을 써요.","준비물이나 이름 목록이 아니에요.","글 칸을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L10_basic#5','kor',1,2,'u3','L10','g1_2_kor_u3_L10_basic','lesson_basic','K1-2-u3-C6',2,'match','auto','정리 물음과 알맞은 대답을 선으로 이어 보세요. (은채의 일기)','{}'::text[],true,'{"seq":5,"concept":"K1-2-u3-C6","difficulty":2,"kind":"match","stem":"정리 물음과 알맞은 대답을 선으로 이어 보세요. (은채의 일기)","pairs":[{"l":"언제","r":"저녁에"},{"l":"무엇을","r":"빨래 개기를 도왔다"},{"l":"느낌","r":"어깨가 으쓱했다"}],"mis":"K1-2-u3-X07","explanation":["「저녁에」가 언제, 「빨래 개기」가 무엇을이에요.","「으쓱했다」가 느낌이에요.","은채의 글을 한 줄씩 읽어요."],"variant_rule":{"alt":[{"stem":"정리 물음과 알맞은 대답을 선으로 이어 보세요. (시우의 일기)","pairs":[{"l":"누구와","r":"할머니와"},{"l":"무엇을","r":"옥수수를 땄다"},{"l":"느낌","r":"깜짝 놀랐다"}],"explanation":["할머니와 옥수수를 땄어요.","놀란 것이 느낌이에요.","시우의 글을 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L10_basic#6','kor',1,2,'u3','L10','g1_2_kor_u3_L10_basic','lesson_basic','K1-2-u3-C6',2,'mc','auto','그림에 넣으면 좋은 것은 어느 것인가요?',ARRAY['K1-2-u3-X13','K1-2-u3-X10']::text[],false,'{"seq":6,"concept":"K1-2-u3-C6","difficulty":2,"kind":"mc","stem":"그림에 넣으면 좋은 것은 어느 것인가요?","options":[{"t":"누가 어디에서 무엇을 하는지","correct":true},{"t":"그날 먹은 것 전부","mis":"K1-2-u3-X13"},{"t":"글자 많이","mis":"K1-2-u3-X10"}],"explanation":["그림만 보아도 무슨 일인지 알 수 있어야 해요.","먹은 것 전부나 글자는 그림에 넣을 것이 아니에요.","한 장면이 보이게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L10_basic#7','kor',1,2,'u3','L10','g1_2_kor_u3_L10_basic','lesson_basic','K1-2-u3-C6',2,'mc','auto','생각이나 느낌이 잘 드러난 문장은 어느 것인가요?',ARRAY['K1-2-u3-X15']::text[],true,'{"seq":7,"concept":"K1-2-u3-C6","difficulty":2,"kind":"mc","stem":"생각이나 느낌이 잘 드러난 문장은 어느 것인가요?","options":[{"t":"양말 짝을 다 찾았을 때 어깨가 으쓱했다","correct":true},{"t":"양말을 갰다","mis":"K1-2-u3-X15"},{"t":"좋았다","mis":"K1-2-u3-X15"}],"explanation":["무엇을 했을 때 어떤 마음이었는지가 있어요.","「갰다」만, 「좋았다」만으로는 느낌이 안 보여요.","까닭과 느낌이 이어진 문장."],"asset":{"type":"diary","date":"9월 25일 목요일","weather":"☀️ 바람이 시원함","picture":"🧦🧺","lines":["저녁에 빨래 개기를 처음 도왔다.","양말 짝을 다 찾았을 때 어깨가 으쓱했다."],"name":"은채"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 생각이나 느낌이 잘 드러난 문장은 어느 것인가요?","options":[{"t":"옥수수가 내 팔보다 길어서 깜짝 놀랐다","correct":true},{"t":"옥수수를 땄다","mis":"K1-2-u3-X15"},{"t":"재미있었다","mis":"K1-2-u3-X15"}],"explanation":["왜 놀랐는지까지 이어져 있어요.","「땄다」·「재미있었다」만으로는 느낌이 안 보여요.","까닭까지."],"asset":{"type":"diary","date":"10월 2일 금요일","weather":"☁️ 구름이 많음","picture":"🌽👵","lines":["할머니와 밭에서 옥수수를 땄다.","옥수수가 내 팔보다 길어서 깜짝 놀랐다."],"name":"시우"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L10_basic#8','kor',1,2,'u3','L10','g1_2_kor_u3_L10_basic','lesson_basic','K1-2-u3-C6',2,'mc','auto','그림일기를 쓸 때 조심할 것은 무엇인가요?',ARRAY['K1-2-u3-X16','K1-2-u3-X11']::text[],false,'{"seq":8,"concept":"K1-2-u3-C6","difficulty":2,"kind":"mc","stem":"그림일기를 쓸 때 조심할 것은 무엇인가요?","options":[{"t":"그림에 시간을 다 쓰지 않는다","correct":true},{"t":"글을 쓰지 않는다","mis":"K1-2-u3-X16"},{"t":"맨 윗줄을 비워 둔다","mis":"K1-2-u3-X11"}],"explanation":["그림에 시간을 다 쓰면 정작 글을 못 써요.","그림일기의 반은 글이에요.","시간을 나누어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L10_basic#9','kor',1,2,'u3','L10','g1_2_kor_u3_L10_basic','lesson_basic','K1-2-u3-C6',2,'ox','auto','그림일기를 다 쓰고 나면 다시 읽어 보고 빠진 곳을 고쳐 써요.',ARRAY['K1-2-u3-X17']::text[],false,'{"seq":9,"concept":"K1-2-u3-C6","difficulty":2,"kind":"ox","stem":"그림일기를 다 쓰고 나면 다시 읽어 보고 빠진 곳을 고쳐 써요.","answer":"O","reason_options":[{"t":"다시 읽어야 빠진 칸이나 틀린 글자를 찾을 수 있으니까","correct":true},{"t":"다시 읽으면 친구보다 잘 쓴 것을 알 수 있으니까","mis":"K1-2-u3-X17"}],"mis":"K1-2-u3-X17","explanation":["다 쓴 뒤 다시 읽어 고쳐요.","남과 견주는 것이 아니라 내 일기를 되읽는 거예요.","빠진 칸·틀린 글자를 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L10_basic#10','kor',1,2,'u3','L10','g1_2_kor_u3_L10_basic','lesson_basic','K1-2-u3-C6',3,'blank','auto','그림을 보고 빈칸에 알맞은 말을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L10_challenge#1','kor',1,2,'u3','L10','g1_2_kor_u3_L10_challenge','lesson_challenge','K1-2-u3-C6',2,'mc','auto','어제 하루를 되돌려 글감을 고를 때 가장 좋은 것은 어느 것인가요?',ARRAY['K1-2-u3-X14']::text[],false,'{"seq":1,"concept":"K1-2-u3-C6","difficulty":2,"kind":"mc","stem":"어제 하루를 되돌려 글감을 고를 때 가장 좋은 것은 어느 것인가요?","options":[{"t":"그때 마음이 움직인 일","correct":true},{"t":"가장 오래 걸린 일","mis":"K1-2-u3-X14"},{"t":"날마다 똑같이 한 일","mis":"K1-2-u3-X14"}],"explanation":["마음이 움직인 일이 좋은 글감이에요.","오래 걸린 일이나 늘 하는 일은 그날이 떠오르지 않아요.","아침·낮·저녁을 되짚어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L10_challenge#2','kor',1,2,'u3','L10','g1_2_kor_u3_L10_challenge','lesson_challenge','K1-2-u3-C6',2,'mc','auto','준서의 일기를 고치려면 어떻게 해야 할까요?',ARRAY['K1-2-u3-X14','K1-2-u3-X13']::text[],false,'{"seq":2,"concept":"K1-2-u3-C6","difficulty":2,"kind":"mc","stem":"준서의 일기를 고치려면 어떻게 해야 할까요?","options":[{"t":"하루를 다 늘어놓지 말고 마음이 움직인 일 하나를 골라 느낌까지 쓴다","correct":true},{"t":"일어난 시각까지 더 자세히 적는다","mis":"K1-2-u3-X14"},{"t":"그림을 하나 더 그린다","mis":"K1-2-u3-X13"}],"explanation":["늘 하는 일을 지우고 그날만의 일 하나를 골라요.","시각이나 그림 수가 문제가 아니에요.","느낌까지 써요."],"asset":{"type":"diary","date":"10월 8일 목요일","weather":"☁️ 구름이 많음","picture":"🛏️🍚🏫","lines":["아침에 일어났다. 밥을 먹었다.","학교에 갔다. 집에 왔다.","저녁을 먹고 잤다."],"name":"준서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L10_challenge#3','kor',1,2,'u3','L10','g1_2_kor_u3_L10_challenge','lesson_challenge','K1-2-u3-C6',3,'error','auto','그림일기를 다 쓰고 확인할 것을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L10_challenge#4','kor',1,2,'u3','L10','g1_2_kor_u3_L10_challenge','lesson_challenge','K1-2-u3-C6',3,'mc','auto','「그림일기의 반은 글이에요」라는 말과 뜻이 같은 것은 어느 것인가요?',ARRAY['K1-2-u3-X16','K1-2-u3-X11']::text[],false,'{"seq":4,"concept":"K1-2-u3-C6","difficulty":3,"kind":"mc","stem":"「그림일기의 반은 글이에요」라는 말과 뜻이 같은 것은 어느 것인가요?","options":[{"t":"그림에 시간을 다 쓰면 글을 못 쓰니 시간을 나누어야 한다","correct":true},{"t":"글을 그림보다 두 배 길게 써야 한다","mis":"K1-2-u3-X16"},{"t":"그림은 그리지 않아도 된다","mis":"K1-2-u3-X11"}],"explanation":["그림과 글에 시간을 나누어요.","길이를 재거나 그림을 빼라는 말이 아니에요.","시간을 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L10_challenge#5','kor',1,2,'u3','L10','g1_2_kor_u3_L10_challenge','lesson_challenge','K1-2-u3-C6',3,'match','auto','그림일기를 쓰는 차례와 거기서 할 일을 선으로 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"K1-2-u3-C6","difficulty":3,"kind":"match","stem":"그림일기를 쓰는 차례와 거기서 할 일을 선으로 이어 보세요.","pairs":[{"l":"첫째","r":"아침·낮·저녁을 되짚어 글감을 고른다"},{"l":"둘째","r":"날짜·요일·날씨를 쓴다"},{"l":"셋째","r":"한 장면을 그리고 일과 느낌을 쓴다"},{"l":"넷째","r":"다시 읽고 빠진 곳을 고친다"}],"mis":"K1-2-u3-X17","explanation":["글감 → 맨 윗줄 → 그림과 글 → 다시 읽기예요.","차례가 바뀌면 빠지는 것이 생겨요.","네 걸음을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L10_challenge#6','kor',1,2,'u3','L10','g1_2_kor_u3_L10_challenge','lesson_challenge','K1-2-u3-C6',3,'ox','auto','느낌은 「좋았다」 한마디면 충분해요.',ARRAY['K1-2-u3-X15']::text[],false,'{"seq":6,"concept":"K1-2-u3-C6","difficulty":3,"kind":"ox","stem":"느낌은 「좋았다」 한마디면 충분해요.","answer":"X","reason_options":[{"t":"왜 그렇게 느꼈는지까지 이어 써야 그날이 되살아나니까","correct":true},{"t":"느낌은 짧을수록 좋으니까","mis":"K1-2-u3-X15"}],"mis":"K1-2-u3-X15","explanation":["느낌에는 까닭을 붙여요.","「좋았다」만 쓰면 무엇이 좋았는지 몰라요.","「왜냐하면」을 붙여 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L10_challenge#7','kor',1,2,'u3','L10','g1_2_kor_u3_L10_challenge','lesson_challenge','K1-2-u3-C6',3,'mc','auto','이 일기에서 고칠 점을 바르게 말한 것은 어느 것인가요?',ARRAY['K1-2-u3-X14','K1-2-u3-X10']::text[],false,'{"seq":7,"concept":"K1-2-u3-C6","difficulty":3,"kind":"mc","stem":"이 일기에서 고칠 점을 바르게 말한 것은 어느 것인가요?","options":[{"t":"날씨를 글 끝이 아니라 맨 윗줄에 써야 한다","correct":true},{"t":"낙엽 이야기를 빼야 한다","mis":"K1-2-u3-X14"},{"t":"그림을 더 예쁘게 칠해야 한다","mis":"K1-2-u3-X10"}],"explanation":["날씨 자리는 맨 윗줄이에요.","낙엽 이야기는 좋은 글감이고 그림은 보이면 돼요.","틀의 자리를 봐요."],"asset":{"type":"diary","date":"10월 13일 월요일","weather":null,"picture":"🍂🧒","lines":["놀이터에서 낙엽을 모아 던졌다.","낙엽이 눈처럼 내려서 웃음이 났다.","날씨: 바람이 불었다."],"name":"단비"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L10_challenge#8','kor',1,2,'u3','L10','g1_2_kor_u3_L10_challenge','lesson_challenge','K1-2-u3-C6',4,'sa','auto','그림을 보고 빈칸에 알맞은 말을 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L10_challenge#9','kor',1,2,'u3','L10','g1_2_kor_u3_L10_challenge','lesson_challenge','K1-2-u3-C6',4,'essay','teacher','어제 있었던 일 하나를 골라 그림일기의 글을 두 문장으로 쓰세요. 첫 문장에는 언제·어디에서·무엇을, 둘째 문장에는 느낌과 그 까닭을 넣으세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u3-C6","difficulty":4,"kind":"essay","stem":"어제 있었던 일 하나를 골라 그림일기의 글을 두 문장으로 쓰세요. 첫 문장에는 언제·어디에서·무엇을, 둘째 문장에는 느낌과 그 까닭을 넣으세요.","answer_guide":{"answer":"예: 어제 저녁에 집에서 동생과 종이배를 접었다. 내 배가 물에 떠서 신이 났다. — 두 문장에 일과 느낌·까닭이 있으면 맞아요.","scoring_points":["언제·어디에서·무엇을이 있는가","느낌이 있는가","느낌의 까닭이 있는가"]},"explanation":["아침·낮·저녁을 되짚어 하나를 골라요.","첫 문장은 일, 둘째 문장은 느낌과 까닭이에요.","늘 하는 일 말고 마음이 움직인 일."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L10_challenge#10','kor',1,2,'u3','L10','g1_2_kor_u3_L10_challenge','lesson_challenge','K1-2-u3-C6',4,'essay','teacher','준서의 일기 「아침에 일어났다. 밥을 먹었다. 학교에 갔다. 집에 왔다. 저녁을 먹고 잤다.」를 그날만의 일 하나와 느낌이 드러나게 두 문장으로 고쳐 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u3-C6","difficulty":4,"kind":"essay","stem":"준서의 일기 「아침에 일어났다. 밥을 먹었다. 학교에 갔다. 집에 왔다. 저녁을 먹고 잤다.」를 그날만의 일 하나와 느낌이 드러나게 두 문장으로 고쳐 쓰세요.","answer_guide":{"answer":"예: 학교 가는 길에 길고양이가 내 뒤를 따라왔다. 자꾸 돌아보게 되어 웃음이 났다. — 늘 하는 일 나열이 없고 한 가지 일과 느낌이 있으면 맞아요.","scoring_points":["늘 하는 일 나열을 없앴는가","한 가지 일을 골랐는가","느낌이 있는가"]},"explanation":["날마다 같은 일은 지워요.","그날만의 일 하나를 골라요.","느낌까지 써요."],"asset":{"type":"diary","date":"10월 8일 목요일","weather":"☁️ 구름이 많음","picture":"🛏️🍚🏫","lines":["아침에 일어났다. 밥을 먹었다.","학교에 갔다. 집에 왔다.","저녁을 먹고 잤다."],"name":"준서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_basic#1','kor',1,2,'u3','L12','g1_2_kor_u3_L12_basic','lesson_basic','K1-2-u3-C7',1,'mc','auto','친구와 있었던 일 가운데 작품으로 나타낼 것으로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u3-X09']::text[],true,'{"seq":1,"concept":"K1-2-u3-C7","difficulty":1,"kind":"mc","stem":"친구와 있었던 일 가운데 작품으로 나타낼 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"함께 실내화를 찾아서 마음이 놓였던 일","correct":true},{"t":"나 혼자 집에서 잔 일","mis":"K1-2-u3-X09"},{"t":"친구 이름을 외운 일","mis":"K1-2-u3-X09"}],"explanation":["함께한 일이면서 그때 느낌이 남은 일이 좋아요.","혼자 한 일이나 이름 외우기는 함께한 일이 아니에요.","「친구와 함께 · 느낌」 둘 다."],"asset":{"type":"passage","lines":["오늘 아침에 신발장 앞에서 실내화 한 짝을 잃어버렸어요.","친구 은채가 함께 찾아 주었어요.","우산꽂이 옆에서 찾았을 때 마음이 놓였어요."],"title":"단비의 발표"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구와 있었던 일 가운데 작품으로 나타낼 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"친구와 뒷산에서 다람쥐를 보고 놀란 일","correct":true},{"t":"혼자 숙제를 한 일","mis":"K1-2-u3-X09"},{"t":"친구 집 주소를 외운 일","mis":"K1-2-u3-X09"}],"explanation":["함께한 일이면서 느낌이 남은 일이에요.","혼자 한 일, 외운 일은 아니에요.","함께·느낌."],"asset":{"type":"passage","lines":["지난주 금요일에 우리 반은 뒷산에 올라갔어요.","다람쥐가 도토리를 물고 지나갔어요.","우리는 숨을 죽이고 지켜보았어요.","다람쥐가 너무 가까이 와서 놀랐어요."],"title":"하율의 발표"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_basic#2','kor',1,2,'u3','L12','g1_2_kor_u3_L12_basic','lesson_basic','K1-2-u3-C7',1,'mc','auto','작품을 만들 때 가장 마음 쓸 것은 무엇인가요?',ARRAY['K1-2-u3-X10']::text[],false,'{"seq":2,"concept":"K1-2-u3-C7","difficulty":1,"kind":"mc","stem":"작품을 만들 때 가장 마음 쓸 것은 무엇인가요?","options":[{"t":"있었던 일이 드러나게 한다","correct":true},{"t":"가장 예쁘게 꾸민다","mis":"K1-2-u3-X10"},{"t":"친구보다 크게 만든다","mis":"K1-2-u3-X10"}],"explanation":["있었던 일이 드러나는 것이 먼저예요.","예쁘게 꾸미기나 크기 겨루기가 아니에요.","미술 시간의 꾸미기가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_basic#3','kor',1,2,'u3','L12','g1_2_kor_u3_L12_basic','lesson_basic','K1-2-u3-C7',1,'mc','auto','친구 작품을 보고 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u3-X18']::text[],true,'{"seq":3,"concept":"K1-2-u3-C7","difficulty":1,"kind":"mc","stem":"친구 작품을 보고 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"달팽이가 비를 맞는 모습이 잘 보여서 좋았어.","correct":true},{"t":"색칠이 삐져나왔네.","mis":"K1-2-u3-X18"},{"t":"내 것이 더 잘 그렸어.","mis":"K1-2-u3-X18"}],"explanation":["무엇이 좋았는지 짚어 말해 주면 힘이 나요.","꾸미기만 따지거나 견주는 말은 아니에요.","하율이의 말을 봐요."],"asset":{"type":"speech","turns":[{"who":"시우","text":"내 작품 제목은 「달팽이와 비」예요. 담 위를 가는 달팽이를 그렸어요."},{"who":"하율","text":"달팽이가 비를 맞는 모습이 잘 보여서 좋았어."},{"who":"준서","text":"색칠이 삐져나왔네."}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구 작품을 보고 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"풍선이 커지는 순간이 잘 보여서 좋았어.","correct":true},{"t":"풍선 색이 이상해.","mis":"K1-2-u3-X18"},{"t":"내 작품이 제일 낫지?","mis":"K1-2-u3-X18"}],"explanation":["무엇이 좋았는지를 말해요.","꾸미기 흉이나 견주는 말은 아니에요.","좋은 점 하나를 짚어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_basic#4','kor',1,2,'u3','L12','g1_2_kor_u3_L12_basic','lesson_basic','K1-2-u3-C7',1,'mc','auto','작품을 만드는 세 걸음으로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u3-X13','K1-2-u3-X10']::text[],false,'{"seq":4,"concept":"K1-2-u3-C7","difficulty":1,"kind":"mc","stem":"작품을 만드는 세 걸음으로 알맞은 것은 어느 것인가요?","options":[{"t":"떠올리기 → 정리하기 → 만들기","correct":true},{"t":"만들기 → 떠올리기 → 정리하기","mis":"K1-2-u3-X13"},{"t":"색칠하기 → 전시하기 → 떠올리기","mis":"K1-2-u3-X10"}],"explanation":["떠올리고 정리한 뒤에 만들어요.","만들기부터 하면 무엇을 나타낼지 몰라요.","세 걸음 차례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_basic#5','kor',1,2,'u3','L12','g1_2_kor_u3_L12_basic','lesson_basic','K1-2-u3-C7',2,'mc','auto','떠올리기 표에 채울 네 칸으로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u3-X07','K1-2-u3-X10']::text[],true,'{"seq":5,"concept":"K1-2-u3-C7","difficulty":2,"kind":"mc","stem":"떠올리기 표에 채울 네 칸으로 알맞은 것은 어느 것인가요?","options":[{"t":"언제 · 어디에서 · 무엇을 · 느낌","correct":true},{"t":"이름 · 나이 · 키 · 몸무게","mis":"K1-2-u3-X07"},{"t":"색깔 · 크기 · 값 · 무게","mis":"K1-2-u3-X10"}],"explanation":["네 칸은 언제·어디에서·무엇을·느낌이에요.","나이나 색깔은 장면을 떠올리는 데 필요 없어요.","발표 때 네 칸과 같아요."],"variant_rule":{"alt":[{"stem":"떠올리기 표에 꼭 넣을 것이 아닌 것은 어느 것인가요?","options":[{"t":"그 친구의 생일","correct":true},{"t":"무엇을 했는지","mis":"K1-2-u3-X07"},{"t":"그때 느낌","mis":"K1-2-u3-X07"}],"explanation":["네 칸은 언제·어디에서·무엇을·느낌이에요.","생일은 장면을 떠올리는 데 필요 없어요.","네 칸만."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_basic#6','kor',1,2,'u3','L12','g1_2_kor_u3_L12_basic','lesson_basic','K1-2-u3-C7',2,'mc','auto','그림으로 나타낼 장면으로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u3-X13']::text[],false,'{"seq":6,"concept":"K1-2-u3-C7","difficulty":2,"kind":"mc","stem":"그림으로 나타낼 장면으로 알맞은 것은 어느 것인가요?","options":[{"t":"그 일을 가장 잘 보여 주는 한 장면","correct":true},{"t":"그날 있었던 일 전부","mis":"K1-2-u3-X13"},{"t":"제일 그리기 쉬운 장면","mis":"K1-2-u3-X13"}],"explanation":["그 일을 가장 잘 보여 주는 한 장면을 골라요.","전부 그리거나 쉬운 것만 고르면 일이 안 보여요.","글에 맞는 장면."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_basic#7','kor',1,2,'u3','L12','g1_2_kor_u3_L12_basic','lesson_basic','K1-2-u3-C7',2,'match','auto','작품의 부분과 거기서 할 일을 선으로 이어 보세요.','{}'::text[],true,'{"seq":7,"concept":"K1-2-u3-C7","difficulty":2,"kind":"match","stem":"작품의 부분과 거기서 할 일을 선으로 이어 보세요.","pairs":[{"l":"제목","r":"무슨 일인지 한마디로 쓴다"},{"l":"그림","r":"가장 남는 한 장면을 그린다"},{"l":"글","r":"있었던 일과 느낌을 쓴다"}],"mis":"K1-2-u3-X13","explanation":["제목은 한마디, 그림은 한 장면이에요.","글에는 일과 느낌을 써요.","시우의 작품 소개를 떠올려요."],"variant_rule":{"alt":[{"stem":"작품을 만드는 걸음과 거기서 할 일을 선으로 이어 보세요.","pairs":[{"l":"떠올리기","r":"친구와 있었던 일을 느낌으로 갈라 떠올린다"},{"l":"정리하기","r":"네 칸 표를 채운다"},{"l":"만들기","r":"한 장면을 그리고 글을 쓴다"}],"explanation":["떠올리고, 표로 정리하고, 만들어요.","순서대로 해야 빠지는 것이 없어요.","세 걸음."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_basic#8','kor',1,2,'u3','L12','g1_2_kor_u3_L12_basic','lesson_basic','K1-2-u3-C7',2,'mc','auto','전시하고 감상할 때 지킬 것으로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u3-X08','K1-2-u3-X18']::text[],false,'{"seq":8,"concept":"K1-2-u3-C7","difficulty":2,"kind":"mc","stem":"전시하고 감상할 때 지킬 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"친구 작품에 손대지 않고 좋은 점을 말한다","correct":true},{"t":"누가 제일 잘했는지 가린다","mis":"K1-2-u3-X08"},{"t":"마음에 안 드는 작품은 떼어 낸다","mis":"K1-2-u3-X18"}],"explanation":["손대지 않고 좋은 점을 말해요.","잘한 사람을 가리는 시간이 아니고, 떼어 내면 안 돼요.","모두 즐거운 감상."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_basic#9','kor',1,2,'u3','L12','g1_2_kor_u3_L12_basic','lesson_basic','K1-2-u3-C7',2,'ox','auto','친구 작품을 볼 때는 무엇이 좋았는지 짚어 말해 주면 좋아요.',ARRAY['K1-2-u3-X18']::text[],false,'{"seq":9,"concept":"K1-2-u3-C7","difficulty":2,"kind":"ox","stem":"친구 작품을 볼 때는 무엇이 좋았는지 짚어 말해 주면 좋아요.","answer":"O","reason_options":[{"t":"어디가 좋았는지 알면 친구가 힘이 나니까","correct":true},{"t":"그래야 내 작품이 더 돋보이니까","mis":"K1-2-u3-X18"}],"mis":"K1-2-u3-X18","explanation":["좋은 점을 짚어 주면 힘이 나요.","내 작품을 돋보이게 하려는 것이 아니에요.","하율이처럼 말해요."],"asset":{"type":"speech","turns":[{"who":"시우","text":"내 작품 제목은 「달팽이와 비」예요. 담 위를 가는 달팽이를 그렸어요."},{"who":"하율","text":"달팽이가 비를 맞는 모습이 잘 보여서 좋았어."},{"who":"준서","text":"색칠이 삐져나왔네."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_basic#10','kor',1,2,'u3','L12','g1_2_kor_u3_L12_basic','lesson_basic','K1-2-u3-C7',3,'error','auto','감상할 때 지킬 것을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_challenge#1','kor',1,2,'u3','L12','g1_2_kor_u3_L12_challenge','lesson_challenge','K1-2-u3-C7',2,'mc','auto','준서의 말이 알맞지 않은 까닭은 무엇인가요?',ARRAY['K1-2-u3-X02','K1-2-u3-X04']::text[],false,'{"seq":1,"concept":"K1-2-u3-C7","difficulty":2,"kind":"mc","stem":"준서의 말이 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"있었던 일이 보이는지가 아니라 색칠만 따졌기 때문에","correct":true},{"t":"너무 작게 말해서","mis":"K1-2-u3-X02"},{"t":"시우를 바라보지 않아서","mis":"K1-2-u3-X04"}],"explanation":["작품은 있었던 일이 드러나면 돼요.","색칠이 삐져나온 것을 따지는 말은 감상이 아니에요.","무엇이 좋았는지를 말해요."],"asset":{"type":"speech","turns":[{"who":"시우","text":"내 작품 제목은 「달팽이와 비」예요. 담 위를 가는 달팽이를 그렸어요."},{"who":"하율","text":"달팽이가 비를 맞는 모습이 잘 보여서 좋았어."},{"who":"준서","text":"색칠이 삐져나왔네."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_challenge#2','kor',1,2,'u3','L12','g1_2_kor_u3_L12_challenge','lesson_challenge','K1-2-u3-C7',2,'mc','auto','시우의 작품 소개에서 「제목」은 무엇인가요?',ARRAY['K1-2-u3-X13','K1-2-u3-X18']::text[],false,'{"seq":2,"concept":"K1-2-u3-C7","difficulty":2,"kind":"mc","stem":"시우의 작품 소개에서 「제목」은 무엇인가요?","options":[{"t":"달팽이와 비","correct":true},{"t":"담 위를 가는 달팽이","mis":"K1-2-u3-X13"},{"t":"하율이의 말","mis":"K1-2-u3-X18"}],"explanation":["「달팽이와 비」가 제목이에요.","「담 위를 가는 달팽이」는 그린 장면이에요.","소개의 첫 마디를 봐요."],"asset":{"type":"speech","turns":[{"who":"시우","text":"내 작품 제목은 「달팽이와 비」예요. 담 위를 가는 달팽이를 그렸어요."},{"who":"하율","text":"달팽이가 비를 맞는 모습이 잘 보여서 좋았어."},{"who":"준서","text":"색칠이 삐져나왔네."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_challenge#3','kor',1,2,'u3','L12','g1_2_kor_u3_L12_challenge','lesson_challenge','K1-2-u3-C7',3,'error','auto','작품을 만들 때 할 일을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_challenge#4','kor',1,2,'u3','L12','g1_2_kor_u3_L12_challenge','lesson_challenge','K1-2-u3-C7',3,'mc','auto','「작품을 만들 때 예쁘게 꾸미는 것보다 있었던 일이 드러나는 것이 먼저」라는 말과 뜻이 같은 것은 어느 것인가요?',ARRAY['K1-2-u3-X10']::text[],false,'{"seq":4,"concept":"K1-2-u3-C7","difficulty":3,"kind":"mc","stem":"「작품을 만들 때 예쁘게 꾸미는 것보다 있었던 일이 드러나는 것이 먼저」라는 말과 뜻이 같은 것은 어느 것인가요?","options":[{"t":"그림만 보아도 무슨 일인지 알 수 있어야 한다","correct":true},{"t":"색을 많이 쓸수록 좋은 작품이다","mis":"K1-2-u3-X10"},{"t":"꾸미기를 하면 안 된다","mis":"K1-2-u3-X10"}],"explanation":["무슨 일인지 보이는 것이 먼저예요.","색을 많이 쓰거나 꾸미기 자체가 문제는 아니에요.","드러남이 먼저."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_challenge#5','kor',1,2,'u3','L12','g1_2_kor_u3_L12_challenge','lesson_challenge','K1-2-u3-C7',3,'match','auto','친구에게 하는 말과 그 말이 어떤 말인지 선으로 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"K1-2-u3-C7","difficulty":3,"kind":"match","stem":"친구에게 하는 말과 그 말이 어떤 말인지 선으로 이어 보세요.","pairs":[{"l":"비 맞는 달팽이가 잘 보여서 좋았어","r":"좋은 점을 짚어 주는 말"},{"l":"색칠이 삐져나왔네","r":"꾸미기만 따지는 말"},{"l":"내 것이 더 잘 그렸어","r":"남과 견주는 말"}],"mis":"K1-2-u3-X18","explanation":["좋은 점을 짚어 주는 말이 감상이에요.","꾸미기만 따지거나 견주는 말은 감상이 아니에요.","세 말을 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_challenge#6','kor',1,2,'u3','L12','g1_2_kor_u3_L12_challenge','lesson_challenge','K1-2-u3-C7',3,'ox','auto','전시 시간은 누가 제일 잘 만들었는지 뽑는 시간이에요.',ARRAY['K1-2-u3-X08']::text[],false,'{"seq":6,"concept":"K1-2-u3-C7","difficulty":3,"kind":"ox","stem":"전시 시간은 누가 제일 잘 만들었는지 뽑는 시간이에요.","answer":"X","reason_options":[{"t":"잘한 사람을 가리는 것이 아니라 서로 작품을 보고 좋은 점을 나누는 시간이니까","correct":true},{"t":"전시를 하면 꼭 상을 주어야 하니까","mis":"K1-2-u3-X08"}],"mis":"K1-2-u3-X08","explanation":["감상은 좋은 점을 나누는 거예요.","잘한 사람을 가리는 시간이 아니에요.","모두 즐거우려면."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_challenge#7','kor',1,2,'u3','L12','g1_2_kor_u3_L12_challenge','lesson_challenge','K1-2-u3-C7',3,'mc','auto','하율이와 은채가 함께 실내화를 찾은 일을 작품으로 만들려고 해요. 네 칸 표의 「느낌」 칸에 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u3-X07']::text[],false,'{"seq":7,"concept":"K1-2-u3-C7","difficulty":3,"kind":"mc","stem":"하율이와 은채가 함께 실내화를 찾은 일을 작품으로 만들려고 해요. 네 칸 표의 「느낌」 칸에 알맞은 것은 어느 것인가요?","options":[{"t":"찾았을 때 마음이 놓였다","correct":true},{"t":"신발장 앞에서","mis":"K1-2-u3-X07"},{"t":"실내화 한 짝","mis":"K1-2-u3-X07"}],"explanation":["「마음이 놓였다」가 느낌이에요.","「신발장 앞에서」는 어디에서, 「실내화」는 무엇을이에요.","네 칸을 가려요."],"asset":{"type":"passage","lines":["오늘 아침에 신발장 앞에서 실내화 한 짝을 잃어버렸어요.","친구 은채가 함께 찾아 주었어요.","우산꽂이 옆에서 찾았을 때 마음이 놓였어요."],"title":"단비의 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_challenge#8','kor',1,2,'u3','L12','g1_2_kor_u3_L12_challenge','lesson_challenge','K1-2-u3-C7',4,'sa','auto','작품을 만드는 세 걸음 가운데 빈칸에 들어갈 말을 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_challenge#9','kor',1,2,'u3','L12','g1_2_kor_u3_L12_challenge','lesson_challenge','K1-2-u3-C7',4,'essay','teacher','준서의 말 「색칠이 삐져나왔네.」를 시우에게 힘이 되는 감상의 말로 고쳐 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u3-C7","difficulty":4,"kind":"essay","stem":"준서의 말 「색칠이 삐져나왔네.」를 시우에게 힘이 되는 감상의 말로 고쳐 쓰세요.","answer_guide":{"answer":"예: 달팽이가 천천히 가는 모습이 느껴져서 좋았어. — 작품에서 좋은 점 하나를 짚었고 흉보는 말이 없으면 맞아요.","scoring_points":["좋은 점을 짚었는가","흉보거나 견주는 말이 없는가","시우의 작품(달팽이·비)과 이어지는가"]},"explanation":["무엇이 좋았는지를 말해요.","꾸미기 흉은 빼요.","하율이의 말을 본보기로."],"asset":{"type":"speech","turns":[{"who":"시우","text":"내 작품 제목은 「달팽이와 비」예요. 담 위를 가는 달팽이를 그렸어요."},{"who":"하율","text":"달팽이가 비를 맞는 모습이 잘 보여서 좋았어."},{"who":"준서","text":"색칠이 삐져나왔네."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_challenge#10','kor',1,2,'u3','L12','g1_2_kor_u3_L12_challenge','lesson_challenge','K1-2-u3-C7',4,'essay','teacher','친구와 있었던 일 하나를 골라 작품 소개말을 쓰세요. 제목 한마디, 그린 장면, 그때 느낌이 들어가게 세 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u3-C7","difficulty":4,"kind":"essay","stem":"친구와 있었던 일 하나를 골라 작품 소개말을 쓰세요. 제목 한마디, 그린 장면, 그때 느낌이 들어가게 세 문장으로 쓰세요.","answer_guide":{"answer":"예: 내 작품 제목은 「찾았다, 실내화」예요. 우산꽂이 옆에서 실내화를 찾는 장면을 그렸어요. 찾았을 때 마음이 놓였어요. — 제목·장면·느낌이 있으면 맞아요.","scoring_points":["제목이 있는가","그린 장면이 한 장면인가","느낌이 있는가"]},"explanation":["시우의 소개말처럼 제목부터.","한 장면을 말해요.","느낌까지."],"asset":{"type":"speech","turns":[{"who":"시우","text":"내 작품 제목은 「달팽이와 비」예요. 담 위를 가는 달팽이를 그렸어요."},{"who":"하율","text":"달팽이가 비를 맞는 모습이 잘 보여서 좋았어."},{"who":"준서","text":"색칠이 삐져나왔네."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#1','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C1',1,'mc','auto','바른 자세로 발표하는 모습은 어느 것인가요?',ARRAY['K1-2-u3-X02','K1-2-u3-X01']::text[],false,'{"seq":1,"concept":"K1-2-u3-C1","difficulty":1,"kind":"mc","stem":"바른 자세로 발표하는 모습은 어느 것인가요?","options":[{"t":"허리를 펴고 듣는 사람을 바라보며 또박또박 말한다","correct":true},{"t":"고개를 숙이고 작게 말한다","mis":"K1-2-u3-X02"},{"t":"소리를 지르며 말한다","mis":"K1-2-u3-X01"}],"explanation":["허리·눈·목소리 세 가지가 바른 자세예요.","고개를 숙이거나 소리를 지르면 안 돼요.","듣는 사람이 편하게 듣게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#2','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C2',1,'mc','auto','친구가 발표할 때 바르게 듣는 모습은 어느 것인가요?',ARRAY['K1-2-u3-X04','K1-2-u3-X05']::text[],false,'{"seq":2,"concept":"K1-2-u3-C2","difficulty":1,"kind":"mc","stem":"친구가 발표할 때 바르게 듣는 모습은 어느 것인가요?","options":[{"t":"말하는 친구를 바라보며 끝까지 듣는다","correct":true},{"t":"책을 넘기며 듣는다","mis":"K1-2-u3-X04"},{"t":"중간에 끼어든다","mis":"K1-2-u3-X05"}],"explanation":["바라보며 끝까지 들어요.","딴 일을 하거나 끼어들면 안 돼요.","말하는 친구 마음을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#3','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C3',1,'mc','auto','경험한 일이 더 잘 드러난 문장은 어느 것인가요?',ARRAY['K1-2-u3-X07']::text[],false,'{"seq":3,"concept":"K1-2-u3-C3","difficulty":1,"kind":"mc","stem":"경험한 일이 더 잘 드러난 문장은 어느 것인가요?","options":[{"t":"오늘 아침에 학교 운동장에서 친구와 풍선을 불었다","correct":true},{"t":"풍선이요","mis":"K1-2-u3-X07"},{"t":"불었어요","mis":"K1-2-u3-X07"}],"explanation":["언제·어디에서·무엇을이 들어 있어요.","한 낱말만으로는 무슨 일인지 몰라요.","네 칸을 세어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#4','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C4',1,'mc','auto','「내 풍선이 제일 크게 부풀었다」 — 이 일은 어떤 일에 넣으면 좋을까요?',ARRAY['K1-2-u3-X09']::text[],false,'{"seq":4,"concept":"K1-2-u3-C4","difficulty":1,"kind":"mc","stem":"「내 풍선이 제일 크게 부풀었다」 — 이 일은 어떤 일에 넣으면 좋을까요?","options":[{"t":"기쁜 일","correct":true},{"t":"속상한 일","mis":"K1-2-u3-X09"},{"t":"심심한 일","mis":"K1-2-u3-X09"}],"explanation":["잘되면 기뻐요.","속상하거나 심심하지 않아요.","그때 마음."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#5','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C5',1,'mc','auto','그림일기의 맨 위에는 무엇을 쓸까요?',ARRAY['K1-2-u3-X12']::text[],false,'{"seq":5,"concept":"K1-2-u3-C5","difficulty":1,"kind":"mc","stem":"그림일기의 맨 위에는 무엇을 쓸까요?","options":[{"t":"날짜와 요일, 날씨","correct":true},{"t":"내 이름과 반","mis":"K1-2-u3-X12"},{"t":"준비물","mis":"K1-2-u3-X12"}],"explanation":["맨 윗줄은 날짜·요일·날씨예요.","이름·반·준비물은 안내문 것이에요.","틀의 맨 윗줄."],"asset":{"type":"diary","date":"10월 6일 화요일","weather":"☀️ 해가 쨍쨍","picture":"🧒🎈🎈","lines":["학교 운동장에서 친구와 풍선을 불었다.","내 풍선이 제일 크게 부풀어서 가슴이 두근거렸다."],"name":"단비"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#6','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C5',1,'mc','auto','이 그림일기에서 빠진 것은 무엇인가요?',ARRAY['K1-2-u3-X11']::text[],false,'{"seq":6,"concept":"K1-2-u3-C5","difficulty":1,"kind":"mc","stem":"이 그림일기에서 빠진 것은 무엇인가요?","options":[{"t":"날씨","correct":true},{"t":"날짜와 요일","mis":"K1-2-u3-X11"},{"t":"글","mis":"K1-2-u3-X11"}],"explanation":["맨 윗줄 뒷자리가 비어 있어요.","날짜와 글은 있어요.","빈칸을 찾아요."],"asset":{"type":"diary","date":"10월 6일 화요일","weather":null,"picture":"🧒🎈🎈","lines":["학교 운동장에서 친구와 풍선을 불었다.","내 풍선이 제일 크게 부풀어서 가슴이 두근거렸다."],"name":"단비"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#7','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C6',1,'mc','auto','그림일기에 쓸 일로 더 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u3-X14']::text[],false,'{"seq":7,"concept":"K1-2-u3-C6","difficulty":1,"kind":"mc","stem":"그림일기에 쓸 일로 더 알맞은 것은 어느 것인가요?","options":[{"t":"친구와 풍선을 불다가 내 풍선이 제일 크게 부푼 일","correct":true},{"t":"날마다 똑같이 세수한 일","mis":"K1-2-u3-X14"},{"t":"날마다 똑같이 신발을 신은 일","mis":"K1-2-u3-X14"}],"explanation":["그날 새롭게 느낀 일이 좋아요.","날마다 같은 일은 그날이 떠오르지 않아요.","그날만의 일."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#8','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C7',1,'mc','auto','친구 작품을 보고 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u3-X18']::text[],false,'{"seq":8,"concept":"K1-2-u3-C7","difficulty":1,"kind":"mc","stem":"친구 작품을 보고 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"풍선이 커지는 순간이 잘 보여서 좋았어.","correct":true},{"t":"색칠이 삐져나왔네.","mis":"K1-2-u3-X18"},{"t":"내 것이 더 잘 그렸어.","mis":"K1-2-u3-X18"}],"explanation":["좋은 점을 짚어 말해요.","흉보거나 견주는 말은 아니에요.","힘이 나는 말."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#9','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C1',2,'match','auto','발표 자세와 그 까닭을 선으로 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u3-C1","difficulty":2,"kind":"match","stem":"발표 자세와 그 까닭을 선으로 이어 보세요.","pairs":[{"l":"허리를 편다","r":"말이 또렷하게 나온다"},{"l":"듣는 사람을 바라본다","r":"누구에게 말하는지 보인다"},{"l":"알맞은 크기로 말한다","r":"뒤에 앉은 친구도 들린다"}],"mis":"K1-2-u3-X02","explanation":["허리를 펴면 말이 또렷해요.","바라보면 누구에게 말하는지, 알맞은 크기면 뒤까지 들려요.","자세마다 까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
