INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#15','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C2',2,'ox','auto','친구가 발표할 때 그림을 그리며 들어도 괜찮아요.',ARRAY['K1-2-u3-X04']::text[],false,'{"seq":15,"concept":"K1-2-u3-C2","difficulty":2,"kind":"ox","stem":"친구가 발표할 때 그림을 그리며 들어도 괜찮아요.","answer":"X","reason_options":[{"t":"딴 일을 하면 말을 놓치고 말하는 친구가 말을 잊을 수도 있으니까","correct":true},{"t":"조용히만 하면 무엇을 해도 되니까","mis":"K1-2-u3-X04"}],"mis":"K1-2-u3-X04","explanation":["딴 일을 하며 들으면 안 돼요.","조용해도 바라보지 않으면 말하는 사람이 힘이 빠져요.","눈과 귀를 말하는 사람에게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#16','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C7',2,'mc','auto','작품을 만드는 세 걸음으로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u3-X13','K1-2-u3-X10']::text[],false,'{"seq":16,"concept":"K1-2-u3-C7","difficulty":2,"kind":"mc","stem":"작품을 만드는 세 걸음으로 알맞은 것은 어느 것인가요?","options":[{"t":"떠올리기 → 정리하기 → 만들기","correct":true},{"t":"만들기 → 떠올리기 → 정리하기","mis":"K1-2-u3-X13"},{"t":"색칠하기 → 전시하기 → 떠올리기","mis":"K1-2-u3-X10"}],"explanation":["떠올리고 정리한 뒤 만들어요.","만들기부터 하면 무엇을 나타낼지 몰라요.","세 걸음."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
