INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#18','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C5',3,'error','auto','그림일기에 들어가는 것을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#19','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C6',3,'ox','auto','그림을 오래 예쁘게 칠하느라 글을 못 써도 괜찮아요.',ARRAY['K1-2-u3-X16']::text[],false,'{"seq":19,"concept":"K1-2-u3-C6","difficulty":3,"kind":"ox","stem":"그림을 오래 예쁘게 칠하느라 글을 못 써도 괜찮아요.","answer":"X","reason_options":[{"t":"그림일기의 반은 글이라 시간을 나누어 써야 하니까","correct":true},{"t":"그림만 잘 그리면 일기가 되니까","mis":"K1-2-u3-X16"}],"mis":"K1-2-u3-X16","explanation":["그림에 시간을 다 쓰면 글을 못 써요.","그림은 간단히, 글 쓸 시간을 남겨요.","반은 글."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#20','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C4',3,'mc','auto','준서의 일기에서 고칠 점은 무엇인가요?',ARRAY['K1-2-u3-X10','K1-2-u3-X07']::text[],false,'{"seq":20,"concept":"K1-2-u3-C4","difficulty":3,"kind":"mc","stem":"준서의 일기에서 고칠 점은 무엇인가요?","options":[{"t":"글은 급식 이야기인데 그림은 강아지라서 서로 다른 일이에요","correct":true},{"t":"강아지를 더 예쁘게 그려야 해요","mis":"K1-2-u3-X10"},{"t":"글이 두 줄이라 짧아요","mis":"K1-2-u3-X07"}],"explanation":["그림과 글은 같은 일을 담아요.","그림 솜씨나 글 길이가 문제가 아니에요.","글을 읽고 그림을 봐요."],"asset":{"type":"diary","date":"10월 7일 수요일","weather":"☀️ 해가 쨍쨍","picture":"🐶🦴","lines":["급식에 내가 좋아하는 카레가 나왔다.","한 그릇을 다 먹어서 배가 든든했다."],"name":"준서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#21','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C3',3,'error','auto','발표에 넣으면 좋은 것을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#22','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C7',3,'ox','auto','전시 시간은 누가 제일 잘 만들었는지 뽑는 시간이에요.',ARRAY['K1-2-u3-X08']::text[],false,'{"seq":22,"concept":"K1-2-u3-C7","difficulty":3,"kind":"ox","stem":"전시 시간은 누가 제일 잘 만들었는지 뽑는 시간이에요.","answer":"X","reason_options":[{"t":"서로 작품을 보고 좋은 점을 나누는 시간이지 가리는 시간이 아니니까","correct":true},{"t":"전시를 하면 꼭 상을 주어야 하니까","mis":"K1-2-u3-X08"}],"mis":"K1-2-u3-X08","explanation":["좋은 점을 나누는 시간이에요.","잘한 사람을 가리지 않아요.","모두 즐겁게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#23','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C6',4,'sa','auto','그림을 보고 빈칸에 알맞은 말을 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#24','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C6',4,'essay','teacher','단비의 그림일기를 보고, 날씨를 그날 느낌이 드러나게 한 문장으로 바꾸어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u3-C6","difficulty":4,"kind":"essay","stem":"단비의 그림일기를 보고, 날씨를 그날 느낌이 드러나게 한 문장으로 바꾸어 쓰세요.","answer_guide":{"answer":"예: 해가 쨍쨍 나서 눈이 부셨다. — 날씨와 느낌이 이어져 있으면 맞아요.","scoring_points":["날씨(해)가 있는가","느낌이 있는가","한 문장인가"]},"explanation":["날씨도 느낌이 드러나게 써요.","「맑음」만보다 그날이 되살아나요.","하늘을 떠올려요."],"asset":{"type":"diary","date":"10월 6일 화요일","weather":"☀️ 해가 쨍쨍","picture":"🧒🎈🎈","lines":["학교 운동장에서 친구와 풍선을 불었다.","내 풍선이 제일 크게 부풀어서 가슴이 두근거렸다."],"name":"단비"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#25','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C7',4,'essay','teacher','단비의 일기를 작품으로 만든다고 생각하고 소개말을 쓰세요. 제목 한마디, 그린 장면, 그때 느낌이 들어가게 세 문장으로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u3-C7","difficulty":4,"kind":"essay","stem":"단비의 일기를 작품으로 만든다고 생각하고 소개말을 쓰세요. 제목 한마디, 그린 장면, 그때 느낌이 들어가게 세 문장으로 쓰세요.","answer_guide":{"answer":"예: 내 작품 제목은 「제일 큰 풍선」이에요. 운동장에서 풍선이 커지는 장면을 그렸어요. 그때 가슴이 두근거렸어요. — 제목·장면·느낌이 있으면 맞아요.","scoring_points":["제목이 있는가","그린 장면이 한 장면인가","느낌이 있는가"]},"explanation":["제목부터 말해요.","한 장면을 말해요.","느낌까지."],"asset":{"type":"diary","date":"10월 6일 화요일","weather":"☀️ 해가 쨍쨍","picture":"🧒🎈🎈","lines":["학교 운동장에서 친구와 풍선을 불었다.","내 풍선이 제일 크게 부풀어서 가슴이 두근거렸다."],"name":"단비"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_b#1','kor',1,2,'u3','','g1_2_kor_u3_review_b','unit_review','K1-2-u3-C1',1,'mc','auto','발표할 때 목소리로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u3-X01','K1-2-u3-X02']::text[],false,'{"seq":1,"concept":"K1-2-u3-C1","difficulty":1,"kind":"mc","stem":"발표할 때 목소리로 알맞은 것은 어느 것인가요?","options":[{"t":"알맞은 크기로 또박또박","correct":true},{"t":"되도록 크게 지르기","mis":"K1-2-u3-X01"},{"t":"들리지 않게 작게","mis":"K1-2-u3-X02"}],"explanation":["알맞은 크기로 또박또박이에요.","지르거나 너무 작으면 안 돼요.","뒤에 앉은 친구도 듣게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_b#2','kor',1,2,'u3','','g1_2_kor_u3_review_b','unit_review','K1-2-u3-C2',1,'mc','auto','말을 잘 알아들었을 때 할 수 있는 것은 어느 것인가요?',ARRAY['K1-2-u3-X04']::text[],false,'{"seq":2,"concept":"K1-2-u3-C2","difficulty":1,"kind":"mc","stem":"말을 잘 알아들었을 때 할 수 있는 것은 어느 것인가요?","options":[{"t":"고개를 끄덕인다","correct":true},{"t":"하품을 한다","mis":"K1-2-u3-X04"},{"t":"창밖을 본다","mis":"K1-2-u3-X04"}],"explanation":["끄덕이면 알아들었다는 것이 보여요.","하품이나 창밖 보기는 안 듣는 것처럼 보여요.","말하는 사람에게 보여 주기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_b#3','kor',1,2,'u3','','g1_2_kor_u3_review_b','unit_review','K1-2-u3-C3',1,'mc','auto','경험한 일이 더 잘 드러난 문장은 어느 것인가요?',ARRAY['K1-2-u3-X07']::text[],false,'{"seq":3,"concept":"K1-2-u3-C3","difficulty":1,"kind":"mc","stem":"경험한 일이 더 잘 드러난 문장은 어느 것인가요?","options":[{"t":"어제 집에 오는 길에 담 위에서 달팽이를 보았다","correct":true},{"t":"달팽이요","mis":"K1-2-u3-X07"},{"t":"보았어요","mis":"K1-2-u3-X07"}],"explanation":["언제·어디에서·무엇을이 들어 있어요.","한 낱말만으로는 장면이 안 보여요.","네 칸을 세어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_b#4','kor',1,2,'u3','','g1_2_kor_u3_review_b','unit_review','K1-2-u3-C4',1,'mc','auto','「비 맞는 달팽이가 천천히 담을 올라갔다」 — 이 일은 어떤 일에 넣으면 좋을까요?',ARRAY['K1-2-u3-X09']::text[],false,'{"seq":4,"concept":"K1-2-u3-C4","difficulty":1,"kind":"mc","stem":"「비 맞는 달팽이가 천천히 담을 올라갔다」 — 이 일은 어떤 일에 넣으면 좋을까요?","options":[{"t":"신기한 일","correct":true},{"t":"속상한 일","mis":"K1-2-u3-X09"},{"t":"무서운 일","mis":"K1-2-u3-X09"}],"explanation":["처음 보는 모습이면 신기해요.","속상하거나 무섭지 않아요.","그때 마음."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_b#5','kor',1,2,'u3','','g1_2_kor_u3_review_b','unit_review','K1-2-u3-C5',1,'mc','auto','그림일기의 맨 위에는 무엇을 쓸까요?',ARRAY['K1-2-u3-X11','K1-2-u3-X12']::text[],false,'{"seq":5,"concept":"K1-2-u3-C5","difficulty":1,"kind":"mc","stem":"그림일기의 맨 위에는 무엇을 쓸까요?","options":[{"t":"날짜와 요일, 날씨","correct":true},{"t":"그림 제목","mis":"K1-2-u3-X11"},{"t":"선생님 성함","mis":"K1-2-u3-X12"}],"explanation":["맨 윗줄은 날짜·요일·날씨예요.","제목이나 선생님 성함은 아니에요.","틀의 맨 윗줄."],"asset":{"type":"diary","date":"9월 18일 목요일","weather":"🌧️ 비가 주룩주룩","picture":"☔🐌","lines":["집에 오는 길에 담 위에서 달팽이를 보았다.","달팽이가 비를 맞고도 천천히 가서 신기했다."],"name":"하율"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_b#6','kor',1,2,'u3','','g1_2_kor_u3_review_b','unit_review','K1-2-u3-C5',1,'mc','auto','이 그림일기에서 빠진 것은 무엇인가요?',ARRAY['K1-2-u3-X11']::text[],false,'{"seq":6,"concept":"K1-2-u3-C5","difficulty":1,"kind":"mc","stem":"이 그림일기에서 빠진 것은 무엇인가요?","options":[{"t":"날짜와 요일","correct":true},{"t":"날씨","mis":"K1-2-u3-X11"},{"t":"그림","mis":"K1-2-u3-X11"}],"explanation":["맨 윗줄 앞자리가 비어 있어요.","날씨와 그림은 있어요.","빈칸을 찾아요."],"asset":{"type":"diary","date":null,"weather":"🌧️ 비가 주룩주룩","picture":"☔🐌","lines":["집에 오는 길에 담 위에서 달팽이를 보았다.","달팽이가 비를 맞고도 천천히 가서 신기했다."],"name":"하율"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
