INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_b#8','kor',1,2,'u3','','g1_2_kor_u3_review_b','unit_review','K1-2-u3-C7',1,'mc','auto','친구 작품을 보고 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u3-X18']::text[],false,'{"seq":8,"concept":"K1-2-u3-C7","difficulty":1,"kind":"mc","stem":"친구 작품을 보고 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"달팽이가 비를 맞는 모습이 잘 보여서 좋았어.","correct":true},{"t":"달팽이가 이상하게 생겼네.","mis":"K1-2-u3-X18"},{"t":"내가 더 잘 그려.","mis":"K1-2-u3-X18"}],"explanation":["좋은 점을 짚어 말해요.","흉보거나 견주는 말은 아니에요.","힘이 나는 말."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_b#9','kor',1,2,'u3','','g1_2_kor_u3_review_b','unit_review','K1-2-u3-C1',2,'match','auto','발표 자세와 그 까닭을 선으로 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u3-C1","difficulty":2,"kind":"match","stem":"발표 자세와 그 까닭을 선으로 이어 보세요.","pairs":[{"l":"또박또박 말한다","r":"한 마디씩 잘 들린다"},{"l":"무엇을 말할지 미리 정한다","r":"말이 막히지 않는다"},{"l":"듣는 사람을 바라본다","r":"누구에게 말하는지 보인다"}],"mis":"K1-2-u3-X03","explanation":["또박또박이면 한 마디씩 들려요.","미리 정하면 안 막히고, 바라보면 누구에게인지 보여요.","자세마다 까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
