INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_b#15','kor',1,2,'u3','','g1_2_kor_u3_review_b','unit_review','K1-2-u3-C2',2,'ox','auto','궁금한 것이 있으면 친구가 말하는 중간에 바로 물어도 돼요.',ARRAY['K1-2-u3-X05']::text[],false,'{"seq":15,"concept":"K1-2-u3-C2","difficulty":2,"kind":"ox","stem":"궁금한 것이 있으면 친구가 말하는 중간에 바로 물어도 돼요.","answer":"X","reason_options":[{"t":"끝까지 들은 뒤에 물어야 말하는 친구가 말을 잊지 않으니까","correct":true},{"t":"궁금한 것은 바로 풀어야 하니까","mis":"K1-2-u3-X05"}],"mis":"K1-2-u3-X05","explanation":["끝까지 듣고 나서 물어요.","말을 자르면 말하는 사람이 머뭇거려요.","끝까지."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
