INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_b#19','kor',1,2,'u3','','g1_2_kor_u3_review_b','unit_review','K1-2-u3-C6',3,'ox','auto','그림일기를 다 쓰면 다시 읽어 보고 빠진 곳을 고쳐 써요.',ARRAY['K1-2-u3-X17']::text[],false,'{"seq":19,"concept":"K1-2-u3-C6","difficulty":3,"kind":"ox","stem":"그림일기를 다 쓰면 다시 읽어 보고 빠진 곳을 고쳐 써요.","answer":"O","reason_options":[{"t":"다시 읽어야 빠진 칸·틀린 글자를 찾을 수 있으니까","correct":true},{"t":"다시 읽으면 친구보다 잘 쓴 것을 알 수 있으니까","mis":"K1-2-u3-X17"}],"mis":"K1-2-u3-X17","explanation":["다 쓴 뒤 되읽어요.","남과 견주는 것이 아니에요.","빠진 칸을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_b#20','kor',1,2,'u3','','g1_2_kor_u3_review_b','unit_review','K1-2-u3-C4',3,'mc','auto','일과 느낌이 알맞게 이어진 것은 어느 것인가요?',ARRAY['K1-2-u3-X09']::text[],false,'{"seq":20,"concept":"K1-2-u3-C4","difficulty":3,"kind":"mc","stem":"일과 느낌이 알맞게 이어진 것은 어느 것인가요?","options":[{"t":"비가 와서 소풍이 미뤄져 아쉬웠다","correct":true},{"t":"비가 와서 소풍이 미뤄져 신이 났다","mis":"K1-2-u3-X09"},{"t":"비가 와서 소풍이 미뤄져 배가 불렀다","mis":"K1-2-u3-X09"}],"explanation":["기다리던 일이 미뤄지면 아쉬워요.","신나거나 배부른 것은 맞지 않아요.","일과 느낌을 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_b#21','kor',1,2,'u3','','g1_2_kor_u3_review_b','unit_review','K1-2-u3-C3',3,'error','auto','발표를 시작하는 첫마디를 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_b#22','kor',1,2,'u3','','g1_2_kor_u3_review_b','unit_review','K1-2-u3-C7',3,'ox','auto','친구 작품을 볼 때는 손대지 않고 끝까지 봐요.',ARRAY['K1-2-u3-X18']::text[],false,'{"seq":22,"concept":"K1-2-u3-C7","difficulty":3,"kind":"ox","stem":"친구 작품을 볼 때는 손대지 않고 끝까지 봐요.","answer":"O","reason_options":[{"t":"작품이 망가지면 안 되고 끝까지 봐야 무엇이 좋은지 알 수 있으니까","correct":true},{"t":"선생님이 보고 있으니까","mis":"K1-2-u3-X18"}],"mis":"K1-2-u3-X18","explanation":["손대지 않고 끝까지 봐요.","누가 보아서가 아니라 작품과 친구를 위해서예요.","감상 예절."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_b#23','kor',1,2,'u3','','g1_2_kor_u3_review_b','unit_review','K1-2-u3-C6',4,'sa','auto','그림을 보고 빈칸에 알맞은 말을 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_b#24','kor',1,2,'u3','','g1_2_kor_u3_review_b','unit_review','K1-2-u3-C6',4,'essay','teacher','하율이의 일기를 보고, 날씨를 그날 느낌이 드러나게 한 문장으로 바꾸어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u3-C6","difficulty":4,"kind":"essay","stem":"하율이의 일기를 보고, 날씨를 그날 느낌이 드러나게 한 문장으로 바꾸어 쓰세요.","answer_guide":{"answer":"예: 비가 주룩주룩 와서 우산 위가 시끄러웠다. — 날씨와 느낌이 이어져 있으면 맞아요.","scoring_points":["날씨(비)가 있는가","느낌이 있는가","한 문장인가"]},"explanation":["날씨도 느낌이 드러나게 써요.","「비」만보다 그날이 되살아나요.","하늘을 떠올려요."],"asset":{"type":"diary","date":"9월 18일 목요일","weather":"🌧️ 비가 주룩주룩","picture":"☔🐌","lines":["집에 오는 길에 담 위에서 달팽이를 보았다.","달팽이가 비를 맞고도 천천히 가서 신기했다."],"name":"하율"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_b#25','kor',1,2,'u3','','g1_2_kor_u3_review_b','unit_review','K1-2-u3-C7',4,'essay','teacher','하율이의 일기를 작품으로 만든다고 생각하고 소개말을 쓰세요. 제목 한마디, 그린 장면, 그때 느낌이 들어가게 세 문장으로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u3-C7","difficulty":4,"kind":"essay","stem":"하율이의 일기를 작품으로 만든다고 생각하고 소개말을 쓰세요. 제목 한마디, 그린 장면, 그때 느낌이 들어가게 세 문장으로 쓰세요.","answer_guide":{"answer":"예: 내 작품 제목은 「비 오는 날 달팽이」예요. 담 위를 천천히 가는 달팽이를 그렸어요. 비를 맞고도 가서 신기했어요. — 제목·장면·느낌이 있으면 맞아요.","scoring_points":["제목이 있는가","그린 장면이 한 장면인가","느낌이 있는가"]},"explanation":["제목부터 말해요.","한 장면을 말해요.","느낌까지."],"asset":{"type":"diary","date":"9월 18일 목요일","weather":"🌧️ 비가 주룩주룩","picture":"☔🐌","lines":["집에 오는 길에 담 위에서 달팽이를 보았다.","달팽이가 비를 맞고도 천천히 가서 신기했다."],"name":"하율"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_c#1','kor',1,2,'u3','','g1_2_kor_u3_review_c','unit_review','K1-2-u3-C1',1,'mc','auto','발표하기 전에 먼저 할 일은 무엇인가요?',ARRAY['K1-2-u3-X03','K1-2-u3-X01']::text[],false,'{"seq":1,"concept":"K1-2-u3-C1","difficulty":1,"kind":"mc","stem":"발표하기 전에 먼저 할 일은 무엇인가요?","options":[{"t":"무엇을 말할지 정한다","correct":true},{"t":"일어나서 생각한다","mis":"K1-2-u3-X03"},{"t":"소리를 지를 준비를 한다","mis":"K1-2-u3-X01"}],"explanation":["말할 것을 정한 뒤 일어나요.","일어나서 생각하면 말이 막혀요.","속으로 한 번 말해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_c#2','kor',1,2,'u3','','g1_2_kor_u3_review_c','unit_review','K1-2-u3-C2',1,'mc','auto','들을 때 하지 말아야 할 것은 어느 것인가요?',ARRAY['K1-2-u3-X04','K1-2-u3-X05']::text[],false,'{"seq":2,"concept":"K1-2-u3-C2","difficulty":1,"kind":"mc","stem":"들을 때 하지 말아야 할 것은 어느 것인가요?","options":[{"t":"옆 친구와 이야기하기","correct":true},{"t":"말하는 사람 바라보기","mis":"K1-2-u3-X04"},{"t":"끝까지 듣기","mis":"K1-2-u3-X05"}],"explanation":["옆 친구와 이야기하면 딴 일을 하는 거예요.","바라보기와 끝까지 듣기는 바른 자세예요.","눈과 귀를 말하는 사람에게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_c#3','kor',1,2,'u3','','g1_2_kor_u3_review_c','unit_review','K1-2-u3-C3',1,'mc','auto','경험한 일이 더 잘 드러난 문장은 어느 것인가요?',ARRAY['K1-2-u3-X07']::text[],false,'{"seq":3,"concept":"K1-2-u3-C3","difficulty":1,"kind":"mc","stem":"경험한 일이 더 잘 드러난 문장은 어느 것인가요?","options":[{"t":"지난 금요일에 할머니와 밭에서 옥수수를 땄다","correct":true},{"t":"옥수수요","mis":"K1-2-u3-X07"},{"t":"땄어요","mis":"K1-2-u3-X07"}],"explanation":["언제·누구와·어디에서·무엇을이 들어 있어요.","한 낱말만으로는 모르겠어요.","네 칸을 세어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_c#4','kor',1,2,'u3','','g1_2_kor_u3_review_c','unit_review','K1-2-u3-C4',1,'mc','auto','「옥수수가 내 팔보다 길었다」 — 이 일은 어떤 일에 넣으면 좋을까요?',ARRAY['K1-2-u3-X09']::text[],false,'{"seq":4,"concept":"K1-2-u3-C4","difficulty":1,"kind":"mc","stem":"「옥수수가 내 팔보다 길었다」 — 이 일은 어떤 일에 넣으면 좋을까요?","options":[{"t":"놀란 일","correct":true},{"t":"속상한 일","mis":"K1-2-u3-X09"},{"t":"심심한 일","mis":"K1-2-u3-X09"}],"explanation":["생각보다 크면 놀라요.","속상하거나 심심하지 않아요.","그때 마음."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_c#5','kor',1,2,'u3','','g1_2_kor_u3_review_c','unit_review','K1-2-u3-C5',1,'mc','auto','그림일기의 맨 위에는 무엇을 쓸까요?',ARRAY['K1-2-u3-X12','K1-2-u3-X11']::text[],false,'{"seq":5,"concept":"K1-2-u3-C5","difficulty":1,"kind":"mc","stem":"그림일기의 맨 위에는 무엇을 쓸까요?","options":[{"t":"날짜와 요일, 날씨","correct":true},{"t":"학급 이름","mis":"K1-2-u3-X12"},{"t":"느낌","mis":"K1-2-u3-X11"}],"explanation":["맨 윗줄은 날짜·요일·날씨예요.","학급 이름은 안내문, 느낌은 글 칸이에요.","틀의 맨 윗줄."],"asset":{"type":"diary","date":"10월 2일 금요일","weather":"☁️ 구름이 많음","picture":"🌽👵","lines":["할머니와 밭에서 옥수수를 땄다.","옥수수가 내 팔보다 길어서 깜짝 놀랐다."],"name":"시우"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_c#6','kor',1,2,'u3','','g1_2_kor_u3_review_c','unit_review','K1-2-u3-C5',1,'mc','auto','이 그림일기에서 빠진 것은 무엇인가요?',ARRAY['K1-2-u3-X11']::text[],false,'{"seq":6,"concept":"K1-2-u3-C5","difficulty":1,"kind":"mc","stem":"이 그림일기에서 빠진 것은 무엇인가요?","options":[{"t":"그림","correct":true},{"t":"날짜와 요일","mis":"K1-2-u3-X11"},{"t":"글","mis":"K1-2-u3-X11"}],"explanation":["그림 칸이 비어 있어요.","날짜와 글은 있어요.","빈칸을 찾아요."],"asset":{"type":"diary","date":"10월 2일 금요일","weather":"☁️ 구름이 많음","picture":null,"lines":["할머니와 밭에서 옥수수를 땄다.","옥수수가 내 팔보다 길어서 깜짝 놀랐다."],"name":"시우"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_c#7','kor',1,2,'u3','','g1_2_kor_u3_review_c','unit_review','K1-2-u3-C6',1,'mc','auto','그림일기에 쓸 일로 더 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u3-X14']::text[],false,'{"seq":7,"concept":"K1-2-u3-C6","difficulty":1,"kind":"mc","stem":"그림일기에 쓸 일로 더 알맞은 것은 어느 것인가요?","options":[{"t":"할머니와 밭에서 옥수수를 딴 일","correct":true},{"t":"날마다 똑같이 밥을 먹은 일","mis":"K1-2-u3-X14"},{"t":"날마다 똑같이 잠을 잔 일","mis":"K1-2-u3-X14"}],"explanation":["그날 새롭게 느낀 일이 좋아요.","날마다 같은 일은 아니에요.","그날만의 일."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_c#8','kor',1,2,'u3','','g1_2_kor_u3_review_c','unit_review','K1-2-u3-C7',1,'mc','auto','친구 작품을 보고 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u3-X18']::text[],false,'{"seq":8,"concept":"K1-2-u3-C7","difficulty":1,"kind":"mc","stem":"친구 작품을 보고 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"옥수수가 팔보다 긴 것이 잘 보여서 좋았어.","correct":true},{"t":"옥수수 색이 틀렸어.","mis":"K1-2-u3-X18"},{"t":"내 작품이 제일 낫지?","mis":"K1-2-u3-X18"}],"explanation":["좋은 점을 짚어 말해요.","흉보거나 견주는 말은 아니에요.","힘이 나는 말."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_c#9','kor',1,2,'u3','','g1_2_kor_u3_review_c','unit_review','K1-2-u3-C1',2,'match','auto','발표 자세와 그 까닭을 선으로 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u3-C1","difficulty":2,"kind":"match","stem":"발표 자세와 그 까닭을 선으로 이어 보세요.","pairs":[{"l":"허리를 편다","r":"말이 또렷하게 나온다"},{"l":"알맞은 크기로 말한다","r":"뒤에 앉은 친구도 들린다"},{"l":"무엇을 말할지 미리 정한다","r":"말이 막히지 않는다"}],"mis":"K1-2-u3-X01","explanation":["허리를 펴면 또렷해요.","알맞은 크기면 뒤까지, 미리 정하면 안 막혀요.","자세마다 까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_c#10','kor',1,2,'u3','','g1_2_kor_u3_review_c','unit_review','K1-2-u3-C3',2,'match','auto','물음과 알맞은 대답을 선으로 이어 보세요. (시우의 일기)','{}'::text[],false,'{"seq":10,"concept":"K1-2-u3-C3","difficulty":2,"kind":"match","stem":"물음과 알맞은 대답을 선으로 이어 보세요. (시우의 일기)","pairs":[{"l":"누구와","r":"할머니와"},{"l":"무엇을","r":"밭에서 옥수수를 땄다"},{"l":"느낌","r":"깜짝 놀랐다"}],"mis":"K1-2-u3-X07","explanation":["할머니와 옥수수를 땄어요.","「놀랐다」가 느낌이에요.","글을 한 줄씩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_c#11','kor',1,2,'u3','','g1_2_kor_u3_review_c','unit_review','K1-2-u3-C4',2,'mc','auto','시우의 일기로 그림을 그린다면 어느 장면이 좋을까요?',ARRAY['K1-2-u3-X13']::text[],false,'{"seq":11,"concept":"K1-2-u3-C4","difficulty":2,"kind":"mc","stem":"시우의 일기로 그림을 그린다면 어느 장면이 좋을까요?","options":[{"t":"팔보다 긴 옥수수를 들고 놀란 나","correct":true},{"t":"밭에 가는 버스와 밭과 집 장면 전부","mis":"K1-2-u3-X13"},{"t":"옥수수 요리법","mis":"K1-2-u3-X13"}],"explanation":["가장 기억에 남는 한 장면이에요.","전부나 요리법은 안 돼요.","글에서 가장 놀란 자리."],"asset":{"type":"diary","date":"10월 2일 금요일","weather":"☁️ 구름이 많음","picture":"🌽👵","lines":["할머니와 밭에서 옥수수를 땄다.","옥수수가 내 팔보다 길어서 깜짝 놀랐다."],"name":"시우"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
