INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_c#15','kor',1,2,'u3','','g1_2_kor_u3_review_c','unit_review','K1-2-u3-C2',2,'ox','auto','말을 알아들었으면 고개를 끄덕여 주면 좋아요.',ARRAY['K1-2-u3-X04']::text[],false,'{"seq":15,"concept":"K1-2-u3-C2","difficulty":2,"kind":"ox","stem":"말을 알아들었으면 고개를 끄덕여 주면 좋아요.","answer":"O","reason_options":[{"t":"알아들었다는 것이 말하는 친구에게 보이니까","correct":true},{"t":"그래야 발표가 빨리 끝나니까","mis":"K1-2-u3-X04"}],"mis":"K1-2-u3-X04","explanation":["끄덕이면 알아들었다는 것이 보여요.","빨리 끝내려는 것이 아니에요.","말하는 사람 마음."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
