INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_c#19','kor',1,2,'u3','','g1_2_kor_u3_review_c','unit_review','K1-2-u3-C6',3,'ox','auto','느낌은 「좋았다」 한마디면 충분해요.',ARRAY['K1-2-u3-X15']::text[],false,'{"seq":19,"concept":"K1-2-u3-C6","difficulty":3,"kind":"ox","stem":"느낌은 「좋았다」 한마디면 충분해요.","answer":"X","reason_options":[{"t":"왜 그렇게 느꼈는지까지 써야 그날이 되살아나니까","correct":true},{"t":"느낌은 짧을수록 좋으니까","mis":"K1-2-u3-X15"}],"mis":"K1-2-u3-X15","explanation":["느낌에 까닭을 붙여요.","「좋았다」만으로는 무엇이 좋았는지 몰라요.","「왜냐하면」."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
