INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_c#22','kor',1,2,'u3','','g1_2_kor_u3_review_c','unit_review','K1-2-u3-C7',3,'ox','auto','친구 작품에 「색칠이 삐져나왔네」라고 말해 주면 친구에게 힘이 돼요.',ARRAY['K1-2-u3-X18']::text[],false,'{"seq":22,"concept":"K1-2-u3-C7","difficulty":3,"kind":"ox","stem":"친구 작품에 「색칠이 삐져나왔네」라고 말해 주면 친구에게 힘이 돼요.","answer":"X","reason_options":[{"t":"꾸미기만 따지는 말은 힘이 빠지게 하고, 무엇이 좋았는지 짚어 주어야 힘이 나니까","correct":true},{"t":"그래야 다음에 잘 칠하니까","mis":"K1-2-u3-X18"}],"mis":"K1-2-u3-X18","explanation":["좋은 점을 짚어 말해요.","꾸미기 흉은 감상이 아니에요.","힘이 나는 말."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_c#23','kor',1,2,'u3','','g1_2_kor_u3_review_c','unit_review','K1-2-u3-C6',4,'sa','auto','그림을 보고 빈칸에 알맞은 말을 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_c#24','kor',1,2,'u3','','g1_2_kor_u3_review_c','unit_review','K1-2-u3-C6',4,'essay','teacher','시우의 일기를 보고, 날씨를 그날 느낌이 드러나게 한 문장으로 바꾸어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u3-C6","difficulty":4,"kind":"essay","stem":"시우의 일기를 보고, 날씨를 그날 느낌이 드러나게 한 문장으로 바꾸어 쓰세요.","answer_guide":{"answer":"예: 구름이 많아서 해가 숨바꼭질하는 것 같았다. — 날씨와 느낌이 이어져 있으면 맞아요.","scoring_points":["날씨(구름)가 있는가","느낌이 있는가","한 문장인가"]},"explanation":["날씨도 느낌이 드러나게 써요.","「구름 많음」만보다 그날이 되살아나요.","하늘을 떠올려요."],"asset":{"type":"diary","date":"10월 2일 금요일","weather":"☁️ 구름이 많음","picture":"🌽👵","lines":["할머니와 밭에서 옥수수를 땄다.","옥수수가 내 팔보다 길어서 깜짝 놀랐다."],"name":"시우"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_c#25','kor',1,2,'u3','','g1_2_kor_u3_review_c','unit_review','K1-2-u3-C7',4,'essay','teacher','시우의 일기를 작품으로 만든다고 생각하고 소개말을 쓰세요. 제목 한마디, 그린 장면, 그때 느낌이 들어가게 세 문장으로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u3-C7","difficulty":4,"kind":"essay","stem":"시우의 일기를 작품으로 만든다고 생각하고 소개말을 쓰세요. 제목 한마디, 그린 장면, 그때 느낌이 들어가게 세 문장으로 쓰세요.","answer_guide":{"answer":"예: 내 작품 제목은 「팔보다 긴 옥수수」예요. 밭에서 옥수수를 들고 놀란 나를 그렸어요. 옥수수가 팔보다 길어서 깜짝 놀랐어요. — 제목·장면·느낌이 있으면 맞아요.","scoring_points":["제목이 있는가","그린 장면이 한 장면인가","느낌이 있는가"]},"explanation":["제목부터 말해요.","한 장면을 말해요.","느낌까지."],"asset":{"type":"diary","date":"10월 2일 금요일","weather":"☁️ 구름이 많음","picture":"🌽👵","lines":["할머니와 밭에서 옥수수를 땄다.","옥수수가 내 팔보다 길어서 깜짝 놀랐다."],"name":"시우"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_d#1','kor',1,2,'u3','','g1_2_kor_u3_review_d','unit_review','K1-2-u3-C1',1,'mc','auto','발표할 때 눈은 어디를 보아야 할까요?',ARRAY['K1-2-u3-X02']::text[],false,'{"seq":1,"concept":"K1-2-u3-C1","difficulty":1,"kind":"mc","stem":"발표할 때 눈은 어디를 보아야 할까요?","options":[{"t":"듣는 사람","correct":true},{"t":"바닥","mis":"K1-2-u3-X02"},{"t":"칠판","mis":"K1-2-u3-X02"}],"explanation":["듣는 사람을 바라보며 말해요.","바닥이나 칠판을 보면 누구에게 말하는지 안 보여요.","누구에게 말하나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_d#2','kor',1,2,'u3','','g1_2_kor_u3_review_d','unit_review','K1-2-u3-C2',1,'mc','auto','딴 일을 하며 듣는 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u3-X05','K1-2-u3-X04']::text[],false,'{"seq":2,"concept":"K1-2-u3-C2","difficulty":1,"kind":"mc","stem":"딴 일을 하며 듣는 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"말하는 친구를 바라보면 좋겠어.","correct":true},{"t":"너는 왜 그것도 못 해?","mis":"K1-2-u3-X05"},{"t":"그냥 네 마음대로 해.","mis":"K1-2-u3-X04"}],"explanation":["나무라지 않고 알려 주는 말이에요.","나무라거나 내버려 두면 안 돼요.","어떻게 하면 좋을지 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_d#3','kor',1,2,'u3','','g1_2_kor_u3_review_d','unit_review','K1-2-u3-C3',1,'mc','auto','경험한 일이 더 잘 드러난 문장은 어느 것인가요?',ARRAY['K1-2-u3-X07']::text[],false,'{"seq":3,"concept":"K1-2-u3-C3","difficulty":1,"kind":"mc","stem":"경험한 일이 더 잘 드러난 문장은 어느 것인가요?","options":[{"t":"어제 저녁에 집에서 빨래 개기를 도왔다","correct":true},{"t":"빨래요","mis":"K1-2-u3-X07"},{"t":"도왔어요","mis":"K1-2-u3-X07"}],"explanation":["언제·어디에서·무엇을이 들어 있어요.","한 낱말만으로는 장면이 안 보여요.","네 칸을 세어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_d#4','kor',1,2,'u3','','g1_2_kor_u3_review_d','unit_review','K1-2-u3-C4',1,'mc','auto','「양말 짝을 다 찾았다」 — 이 일은 어떤 일에 넣으면 좋을까요?',ARRAY['K1-2-u3-X09']::text[],false,'{"seq":4,"concept":"K1-2-u3-C4","difficulty":1,"kind":"mc","stem":"「양말 짝을 다 찾았다」 — 이 일은 어떤 일에 넣으면 좋을까요?","options":[{"t":"뿌듯한 일","correct":true},{"t":"속상한 일","mis":"K1-2-u3-X09"},{"t":"무서운 일","mis":"K1-2-u3-X09"}],"explanation":["해내면 뿌듯해요.","속상하거나 무섭지 않아요.","그때 마음."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_d#5','kor',1,2,'u3','','g1_2_kor_u3_review_d','unit_review','K1-2-u3-C5',1,'mc','auto','그림일기의 맨 위에는 무엇을 쓸까요?',ARRAY['K1-2-u3-X12','K1-2-u3-X11']::text[],false,'{"seq":5,"concept":"K1-2-u3-C5","difficulty":1,"kind":"mc","stem":"그림일기의 맨 위에는 무엇을 쓸까요?","options":[{"t":"날짜와 요일, 날씨","correct":true},{"t":"준비물","mis":"K1-2-u3-X12"},{"t":"그림","mis":"K1-2-u3-X11"}],"explanation":["맨 윗줄은 날짜·요일·날씨예요.","준비물은 안내문, 그림은 가운데 칸이에요.","틀의 맨 윗줄."],"asset":{"type":"diary","date":"9월 25일 목요일","weather":"☀️ 바람이 시원함","picture":"🧦🧺","lines":["저녁에 빨래 개기를 처음 도왔다.","양말 짝을 다 찾았을 때 어깨가 으쓱했다."],"name":"은채"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_d#6','kor',1,2,'u3','','g1_2_kor_u3_review_d','unit_review','K1-2-u3-C5',1,'mc','auto','이 그림일기에서 빠진 것은 무엇인가요?',ARRAY['K1-2-u3-X11']::text[],false,'{"seq":6,"concept":"K1-2-u3-C5","difficulty":1,"kind":"mc","stem":"이 그림일기에서 빠진 것은 무엇인가요?","options":[{"t":"글","correct":true},{"t":"날씨","mis":"K1-2-u3-X11"},{"t":"그림","mis":"K1-2-u3-X11"}],"explanation":["글 칸이 비어 있어요.","날씨와 그림은 있어요.","빈칸을 찾아요."],"asset":{"type":"diary","date":"9월 25일 목요일","weather":"☀️ 바람이 시원함","picture":"🧦🧺","lines":null,"name":"은채"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_d#7','kor',1,2,'u3','','g1_2_kor_u3_review_d','unit_review','K1-2-u3-C6',1,'mc','auto','그림일기에 쓸 일로 더 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u3-X14']::text[],false,'{"seq":7,"concept":"K1-2-u3-C6","difficulty":1,"kind":"mc","stem":"그림일기에 쓸 일로 더 알맞은 것은 어느 것인가요?","options":[{"t":"처음으로 빨래 개기를 도운 일","correct":true},{"t":"날마다 똑같이 옷을 입은 일","mis":"K1-2-u3-X14"},{"t":"날마다 똑같이 학교에 간 일","mis":"K1-2-u3-X14"}],"explanation":["처음 해 본 일이 오래 남아요.","날마다 같은 일은 아니에요.","그날만의 일."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_d#8','kor',1,2,'u3','','g1_2_kor_u3_review_d','unit_review','K1-2-u3-C7',1,'mc','auto','친구 작품을 보고 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u3-X18']::text[],false,'{"seq":8,"concept":"K1-2-u3-C7","difficulty":1,"kind":"mc","stem":"친구 작품을 보고 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"양말 짝을 찾는 모습이 잘 보여서 좋았어.","correct":true},{"t":"양말을 왜 이렇게 그렸어?","mis":"K1-2-u3-X18"},{"t":"내 것보다 못하네.","mis":"K1-2-u3-X18"}],"explanation":["좋은 점을 짚어 말해요.","흉보거나 견주는 말은 아니에요.","힘이 나는 말."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_d#9','kor',1,2,'u3','','g1_2_kor_u3_review_d','unit_review','K1-2-u3-C1',2,'match','auto','발표 자세와 그 까닭을 선으로 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u3-C1","difficulty":2,"kind":"match","stem":"발표 자세와 그 까닭을 선으로 이어 보세요.","pairs":[{"l":"듣는 사람을 바라본다","r":"누구에게 말하는지 보인다"},{"l":"또박또박 말한다","r":"한 마디씩 잘 들린다"},{"l":"허리를 편다","r":"말이 또렷하게 나온다"}],"mis":"K1-2-u3-X02","explanation":["바라보면 누구에게인지 보여요.","또박또박·허리 펴기는 말을 또렷하게 해요.","자세마다 까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_d#10','kor',1,2,'u3','','g1_2_kor_u3_review_d','unit_review','K1-2-u3-C3',2,'match','auto','물음과 알맞은 대답을 선으로 이어 보세요. (은채의 일기)','{}'::text[],false,'{"seq":10,"concept":"K1-2-u3-C3","difficulty":2,"kind":"match","stem":"물음과 알맞은 대답을 선으로 이어 보세요. (은채의 일기)","pairs":[{"l":"언제","r":"저녁에"},{"l":"무엇을","r":"빨래 개기를 도왔다"},{"l":"느낌","r":"어깨가 으쓱했다"}],"mis":"K1-2-u3-X07","explanation":["저녁에 빨래 개기를 도왔어요.","「으쓱했다」가 느낌이에요.","글을 한 줄씩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_d#11','kor',1,2,'u3','','g1_2_kor_u3_review_d','unit_review','K1-2-u3-C4',2,'mc','auto','은채의 일기로 그림을 그린다면 어느 장면이 좋을까요?',ARRAY['K1-2-u3-X13']::text[],false,'{"seq":11,"concept":"K1-2-u3-C4","difficulty":2,"kind":"mc","stem":"은채의 일기로 그림을 그린다면 어느 장면이 좋을까요?","options":[{"t":"양말 짝을 다 찾아 놓은 빨래 바구니 앞의 나","correct":true},{"t":"하루 일 전부","mis":"K1-2-u3-X13"},{"t":"세탁기 설명서","mis":"K1-2-u3-X13"}],"explanation":["가장 기억에 남는 한 장면이에요.","전부나 설명서는 안 돼요.","글에서 가장 으쓱한 자리."],"asset":{"type":"diary","date":"9월 25일 목요일","weather":"☀️ 바람이 시원함","picture":"🧦🧺","lines":["저녁에 빨래 개기를 처음 도왔다.","양말 짝을 다 찾았을 때 어깨가 으쓱했다."],"name":"은채"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_d#12','kor',1,2,'u3','','g1_2_kor_u3_review_d','unit_review','K1-2-u3-C5',2,'blank','auto','그림일기 맨 윗줄에 알맞은 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_d#13','kor',1,2,'u3','','g1_2_kor_u3_review_d','unit_review','K1-2-u3-C6',2,'mc','auto','맨 윗줄을 바르게 쓴 것은 어느 것인가요?',ARRAY['K1-2-u3-X12','K1-2-u3-X11']::text[],false,'{"seq":13,"concept":"K1-2-u3-C6","difficulty":2,"kind":"mc","stem":"맨 윗줄을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"9월 25일 목요일 · 바람이 시원함","correct":true},{"t":"은채 · 9월 25일","mis":"K1-2-u3-X12"},{"t":"9월 25일 · 양말","mis":"K1-2-u3-X11"}],"explanation":["날짜·요일·날씨 차례예요.","이름이나 글감은 안 써요.","세 가지."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_d#14','kor',1,2,'u3','','g1_2_kor_u3_review_d','unit_review','K1-2-u3-C6',2,'mc','auto','생각이나 느낌이 잘 드러난 문장은 어느 것인가요?',ARRAY['K1-2-u3-X15']::text[],false,'{"seq":14,"concept":"K1-2-u3-C6","difficulty":2,"kind":"mc","stem":"생각이나 느낌이 잘 드러난 문장은 어느 것인가요?","options":[{"t":"양말 짝을 다 찾았을 때 어깨가 으쓱했다","correct":true},{"t":"빨래를 갰다","mis":"K1-2-u3-X15"},{"t":"재미있었다","mis":"K1-2-u3-X15"}],"explanation":["왜 으쓱했는지까지 있어요.","한 일만, 「재미있었다」만으로는 안 보여요.","까닭과 느낌."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_d#15','kor',1,2,'u3','','g1_2_kor_u3_review_d','unit_review','K1-2-u3-C2',2,'ox','auto','친구가 말을 잊으면 「그것도 못 해?」 하고 말해 주는 것이 좋아요.',ARRAY['K1-2-u3-X05']::text[],false,'{"seq":15,"concept":"K1-2-u3-C2","difficulty":2,"kind":"ox","stem":"친구가 말을 잊으면 「그것도 못 해?」 하고 말해 주는 것이 좋아요.","answer":"X","reason_options":[{"t":"나무라지 않고 어떻게 하면 좋을지 알려 주는 말이 힘이 되니까","correct":true},{"t":"그래야 다음에 안 잊으니까","mis":"K1-2-u3-X05"}],"mis":"K1-2-u3-X05","explanation":["나무라는 말은 더 긴장하게 해요.","「천천히 다시 말해 봐」처럼 알려 줘요.","힘이 되는 말."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_d#16','kor',1,2,'u3','','g1_2_kor_u3_review_d','unit_review','K1-2-u3-C7',2,'mc','auto','작품을 만들 때 가장 마음 쓸 것은 무엇인가요?',ARRAY['K1-2-u3-X10']::text[],false,'{"seq":16,"concept":"K1-2-u3-C7","difficulty":2,"kind":"mc","stem":"작품을 만들 때 가장 마음 쓸 것은 무엇인가요?","options":[{"t":"있었던 일이 드러나게 한다","correct":true},{"t":"가장 예쁘게 꾸민다","mis":"K1-2-u3-X10"},{"t":"친구보다 크게 만든다","mis":"K1-2-u3-X10"}],"explanation":["드러남이 먼저예요.","꾸미기·크기 겨루기가 아니에요.","미술 시간 꾸미기가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
