INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_d#19','kor',1,2,'u3','','g1_2_kor_u3_review_d','unit_review','K1-2-u3-C6',3,'ox','auto','그림일기의 그림은 무슨 일인지 보이면 되고 색칠을 오래 하지 않아도 돼요.',ARRAY['K1-2-u3-X10']::text[],false,'{"seq":19,"concept":"K1-2-u3-C6","difficulty":3,"kind":"ox","stem":"그림일기의 그림은 무슨 일인지 보이면 되고 색칠을 오래 하지 않아도 돼요.","answer":"O","reason_options":[{"t":"그림일기는 미술 시간이 아니라 있었던 일을 남기는 것이니까","correct":true},{"t":"색칠은 하면 안 되니까","mis":"K1-2-u3-X10"}],"mis":"K1-2-u3-X10","explanation":["무슨 일인지 보이면 돼요.","색칠을 하면 안 되는 것이 아니라 오래 안 해도 된다는 뜻이에요.","드러남이 먼저."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_d#20','kor',1,2,'u3','','g1_2_kor_u3_review_d','unit_review','K1-2-u3-C4',3,'mc','auto','일과 느낌이 알맞게 이어진 것은 어느 것인가요?',ARRAY['K1-2-u3-X09']::text[],false,'{"seq":20,"concept":"K1-2-u3-C4","difficulty":3,"kind":"mc","stem":"일과 느낌이 알맞게 이어진 것은 어느 것인가요?","options":[{"t":"잃어버린 실내화를 찾아서 마음이 놓였다","correct":true},{"t":"잃어버린 실내화를 찾아서 속상했다","mis":"K1-2-u3-X09"},{"t":"잃어버린 실내화를 찾아서 졸렸다","mis":"K1-2-u3-X09"}],"explanation":["찾으면 마음이 놓여요.","속상·졸림은 맞지 않아요.","일과 느낌을 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
