INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_d#22','kor',1,2,'u3','','g1_2_kor_u3_review_d','unit_review','K1-2-u3-C7',3,'ox','auto','작품을 만들 때 예쁘게 꾸미는 것보다 있었던 일이 드러나는 것이 먼저예요.',ARRAY['K1-2-u3-X10']::text[],false,'{"seq":22,"concept":"K1-2-u3-C7","difficulty":3,"kind":"ox","stem":"작품을 만들 때 예쁘게 꾸미는 것보다 있었던 일이 드러나는 것이 먼저예요.","answer":"O","reason_options":[{"t":"그림만 보아도 무슨 일인지 알 수 있어야 하니까","correct":true},{"t":"꾸미기는 하면 안 되니까","mis":"K1-2-u3-X10"}],"mis":"K1-2-u3-X10","explanation":["드러남이 먼저예요.","꾸미기를 하면 안 된다는 뜻이 아니에요.","무슨 일인지 보이게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_d#23','kor',1,2,'u3','','g1_2_kor_u3_review_d','unit_review','K1-2-u3-C6',4,'sa','auto','그림을 보고 빈칸에 알맞은 말을 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_d#24','kor',1,2,'u3','','g1_2_kor_u3_review_d','unit_review','K1-2-u3-C6',4,'essay','teacher','은채의 일기를 보고, 날씨를 그날 느낌이 드러나게 한 문장으로 바꾸어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u3-C6","difficulty":4,"kind":"essay","stem":"은채의 일기를 보고, 날씨를 그날 느낌이 드러나게 한 문장으로 바꾸어 쓰세요.","answer_guide":{"answer":"예: 바람이 시원해서 빨래가 금방 말랐다. — 날씨와 느낌이 이어져 있으면 맞아요.","scoring_points":["날씨(바람)가 있는가","느낌이 있는가","한 문장인가"]},"explanation":["날씨도 느낌이 드러나게 써요.","「바람」만보다 그날이 되살아나요.","하늘을 떠올려요."],"asset":{"type":"diary","date":"9월 25일 목요일","weather":"☀️ 바람이 시원함","picture":"🧦🧺","lines":["저녁에 빨래 개기를 처음 도왔다.","양말 짝을 다 찾았을 때 어깨가 으쓱했다."],"name":"은채"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_d#25','kor',1,2,'u3','','g1_2_kor_u3_review_d','unit_review','K1-2-u3-C7',4,'essay','teacher','은채의 일기를 작품으로 만든다고 생각하고 소개말을 쓰세요. 제목 한마디, 그린 장면, 그때 느낌이 들어가게 세 문장으로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u3-C7","difficulty":4,"kind":"essay","stem":"은채의 일기를 작품으로 만든다고 생각하고 소개말을 쓰세요. 제목 한마디, 그린 장면, 그때 느낌이 들어가게 세 문장으로 쓰세요.","answer_guide":{"answer":"예: 내 작품 제목은 「양말 짝 찾기」예요. 빨래 바구니 앞에서 양말 짝을 맞추는 나를 그렸어요. 다 찾았을 때 어깨가 으쓱했어요. — 제목·장면·느낌이 있으면 맞아요.","scoring_points":["제목이 있는가","그린 장면이 한 장면인가","느낌이 있는가"]},"explanation":["제목부터 말해요.","한 장면을 말해요.","느낌까지."],"asset":{"type":"diary","date":"9월 25일 목요일","weather":"☀️ 바람이 시원함","picture":"🧦🧺","lines":["저녁에 빨래 개기를 처음 도왔다.","양말 짝을 다 찾았을 때 어깨가 으쓱했다."],"name":"은채"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
